# Auto-generated template dictionary for serverless deployment fallback
EMBEDDED_TEMPLATES = {
    'base.html': '<!doctype html>\n<html lang="en">\n<head>\n    <meta charset="utf-8" />\n    <meta name="viewport" content="width=device-width, initial-scale=1" />\n    <title>{% block title %}Sangguniang Kabataan ng Bukal Scholarship Portal{% endblock %}</title>\n    <link rel="preconnect" href="https://fonts.googleapis.com">\n    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n    <link href="https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;500;600;700;800&display=swap" rel="stylesheet">\n    <script src="https://cdn.tailwindcss.com"></script>\n    <script>\n        // Brand palette built from the logo green (#84B179).\n        tailwind.config = {\n            theme: {\n                extend: {\n                    fontFamily: {\n                        sans: [\'Poppins\', \'system-ui\', \'-apple-system\', \'BlinkMacSystemFont\',\n                               \'"Segoe UI"\', \'Roboto\', \'"Helvetica Neue"\', \'Arial\', \'sans-serif\'],\n                    },\n                    colors: {\n                        brand: {\n                            50:  \'#f1f7ef\',\n                            100: \'#e0eedb\',\n                            200: \'#c3deb9\',\n                            300: \'#a4cd95\',\n                            400: \'#84b179\',  // base brand color\n                            500: \'#6f9d63\',\n                            600: \'#5a8550\',\n                            700: \'#476a40\',\n                            800: \'#365031\',\n                            900: \'#283b25\',\n                        }\n                    },\n                    boxShadow: {\n                        card: \'0 6px 18px -8px rgba(40, 59, 37, 0.18), 0 2px 6px -2px rgba(40, 59, 37, 0.10)\',\n                        \'card-lg\': \'0 18px 40px -16px rgba(40, 59, 37, 0.30), 0 6px 14px -6px rgba(40, 59, 37, 0.18)\',\n                    }\n                }\n            }\n        };\n    </script>\n    <link rel="stylesheet" href="{{ url_for(\'static\', filename=\'css/app.css\') }}" />\n    <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"\n          referrerpolicy="no-referrer" />\n</head>\n<body class="min-h-screen bg-slate-50 text-slate-800 overflow-x-hidden {% block body_class %}{% endblock %}">\n    <header class="bg-white shadow-sm border-b-4 border-brand-400 sticky top-0 z-40">\n        <div class="max-w-6xl mx-auto px-3 sm:px-4 py-2 sm:py-3 flex items-center justify-between gap-2">\n            <a href="{% if session.get(\'role\') == \'student\' %}{{ url_for(\'student.announcements\') }}{% elif session.get(\'role\') == \'admin\' %}{{ url_for(\'admin.dashboard\') }}{% else %}{{ url_for(\'public.home\') }}{% endif %}" class="flex items-center gap-2 min-w-0">\n                <img src="{{ url_for(\'static\', filename=\'images/411138383_122115055322131251_5783589540994116709_n.jpg\') }}"\n                     alt="Logo" class="h-8 sm:h-9 w-auto rounded-md object-cover shrink-0" />\n                <span class="font-semibold text-sm sm:text-lg text-brand-700 leading-tight truncate">\n                    <span class="block truncate">Sangguniang Kabataan ng Bukal</span>\n                    <span class="block text-[11px] sm:text-sm font-medium text-brand-600">Scholarship Portal</span>\n                </span>\n            </a>\n            <nav class="flex items-center gap-2 sm:gap-4 text-sm shrink-0">\n                {% if session.get(\'role\') == \'student\' %}\n                    <span class="hidden sm:inline text-slate-500">Hi, {{ session.get(\'full_name\') }}</span>\n                {% elif session.get(\'role\') == \'admin\' %}\n                    <span class="hidden sm:inline text-slate-500">Admin: {{ session.get(\'full_name\') }}</span>\n                {% else %}\n                    <button type="button" data-about-open\n                            class="inline-flex items-center gap-1.5 px-2 sm:px-3 h-9 rounded-md text-brand-700 hover:bg-brand-50 font-medium">\n                        <i class="fa-regular fa-circle-question"></i>\n                        <span class="hidden sm:inline">About Us</span>\n                    </button>\n                    <a href="{{ url_for(\'public.login\') }}"\n                       class="inline-flex items-center justify-center w-9 h-9 rounded-md bg-brand-500 text-white hover:bg-brand-600"\n                       title="Log in" aria-label="Log in">\n                        <i class="fa-solid fa-right-to-bracket"></i>\n                    </a>\n                {% endif %}\n            </nav>\n        </div>\n    </header>\n\n    {% with messages = get_flashed_messages(with_categories=true) %}\n        {% if messages %}\n            <div class="max-w-6xl mx-auto px-3 sm:px-4 mt-3 space-y-2">\n                {% for category, msg in messages %}\n                    <div class="px-3 sm:px-4 py-2 rounded-md text-xs sm:text-sm\n                        {% if category == \'error\' %}bg-red-100 text-red-800\n                        {% elif category == \'success\' %}bg-green-100 text-green-800\n                        {% else %}bg-slate-100 text-slate-800{% endif %}">\n                        {{ msg }}\n                    </div>\n                {% endfor %}\n            </div>\n        {% endif %}\n    {% endwith %}\n\n    {% block hero %}{% endblock %}\n\n    {% block main %}\n    <main class="max-w-6xl mx-auto px-3 sm:px-4 py-4 sm:py-8">\n        {% block content %}{% endblock %}\n    </main>\n    {% endblock %}\n\n    {% block footer %}\n    {% if not session.get(\'user_id\') %}\n    <footer class="text-center text-xs text-slate-500 py-6">\n        <span>&copy; {{ 2026 }} Sangguniang Kabataan ng Bukal Scholarship Portal</span>\n    </footer>\n    {% endif %}\n    {% endblock %}\n\n    {# About Us modal #}\n    <div id="about-modal"\n         class="hidden fixed inset-0 z-[60] flex items-center justify-center p-4"\n         role="dialog" aria-modal="true" aria-labelledby="about-title">\n        <div class="absolute inset-0 bg-slate-900/60" data-about-close></div>\n        <div class="relative bg-white rounded-xl shadow-xl w-full max-w-2xl max-h-[85vh] flex flex-col overflow-hidden">\n            <div class="flex items-center justify-between px-5 py-3 border-b">\n                <h2 id="about-title" class="text-lg font-bold text-brand-700">About Us</h2>\n                <button type="button" data-about-close\n                        class="text-slate-400 hover:text-slate-600" aria-label="Close">\n                    <i class="fa-solid fa-xmark text-lg"></i>\n                </button>\n            </div>\n            <div class="px-5 py-4 overflow-y-auto text-sm text-slate-700 space-y-3 leading-relaxed">\n                <p>\n                    The <span class="font-semibold">Sangguniang Kabataan ng Barangay Bukal</span>\n                    is the official youth organization that partners with the\n                    barangay government to promote the welfare, rights, and\n                    development of the youth in the community. As a youth\n                    government organization, our goal is to be the voice of\n                    the youth and champion programs, projects, and activities\n                    focused on education, health, sports, leadership, the\n                    environment, and forming responsible citizens. The\n                    Sangguniang Kabataan was established to give the youth\n                    a chance to take part in governance and decision-making\n                    for the betterment of their community.\n                </p>\n                <p>\n                    We believe the youth are the key to a more progressive\n                    and brighter future. Through unity, active participation,\n                    and meaningful service, we continue to push initiatives\n                    that inspire and create opportunities for every young\n                    person from Bukal.\n                </p>\n                <p>\n                    As your youth leaders, we are committed to creating\n                    programs that bring a positive impact to everyone\'s\n                    life, while upholding transparency, inclusivity, and\n                    good governance. Our goal is to be the bridge between\n                    the youth and the local government so that their\n                    voices, needs, and aspirations are heard and acted on.\n                </p>\n                <blockquote class="border-l-4 border-brand-400 bg-brand-50 px-4 py-3 italic text-slate-700 rounded-r-md">\n                    "Youth of Bukal: United, Engaged, and Leading the Way to a More Progressive Future."\n                </blockquote>\n                <div class="pt-1">\n                    <a href="https://www.facebook.com/profile.php?id=61553937551899"\n                       target="_blank" rel="noopener"\n                       class="inline-flex items-center gap-2 text-brand-600 hover:underline font-medium">\n                        <i class="fa-brands fa-facebook text-lg"></i>\n                        Visit our Facebook page\n                    </a>\n                </div>\n            </div>\n        </div>\n    </div>\n\n    {# Logout confirmation modal — shown whenever the user clicks any link\n       that points to the logout endpoint. #}\n    <div id="logout-modal"\n         class="hidden fixed inset-0 z-[70] flex items-center justify-center p-4"\n         role="dialog" aria-modal="true" aria-labelledby="logout-title">\n        <div class="absolute inset-0 bg-slate-900/60" data-logout-cancel></div>\n        <div class="relative bg-white rounded-xl shadow-xl w-full max-w-sm overflow-hidden">\n            <div class="px-5 py-4 border-b flex items-center gap-3">\n                <span class="inline-flex items-center justify-center w-9 h-9 rounded-full bg-red-100 text-red-600">\n                    <i class="fa-solid fa-right-from-bracket"></i>\n                </span>\n                <h2 id="logout-title" class="text-base font-semibold text-slate-800">\n                    Log out\n                </h2>\n            </div>\n            <div class="px-5 py-4 text-sm text-slate-700">\n                Are you sure you want to log out?\n            </div>\n            <div class="px-5 py-3 bg-slate-50 border-t flex justify-end gap-2">\n                <button type="button" data-logout-cancel\n                        class="px-3 py-1.5 rounded-md text-sm font-medium text-slate-700 bg-white border border-slate-200 hover:bg-slate-100">\n                    Cancel\n                </button>\n                <a id="logout-confirm-link" href="{{ url_for(\'public.logout\') }}"\n                   class="px-3 py-1.5 rounded-md text-sm font-medium text-white bg-red-600 hover:bg-red-700">\n                    Log out\n                </a>\n            </div>\n        </div>\n    </div>\n\n    {# Logout confirmation behavior — intercept clicks on any anchor whose\n       href matches the logout URL and show the confirmation modal first. #}\n    <script>\n    (function () {\n        const LOGOUT_URL = {{ url_for(\'public.logout\') | tojson }};\n        const modal = document.getElementById(\'logout-modal\');\n        if (!modal) return;\n\n        function open()  { modal.classList.remove(\'hidden\'); document.body.classList.add(\'overflow-hidden\'); }\n        function close() { modal.classList.add(\'hidden\');    document.body.classList.remove(\'overflow-hidden\'); }\n\n        document.addEventListener(\'click\', function (e) {\n            // Cancel buttons / backdrop\n            if (e.target.closest(\'[data-logout-cancel]\')) {\n                e.preventDefault();\n                close();\n                return;\n            }\n            // Intercept any link to the logout URL (skip the confirm button itself)\n            const link = e.target.closest(\'a[href]\');\n            if (!link) return;\n            if (link.id === \'logout-confirm-link\') return;\n            try {\n                const url = new URL(link.href, window.location.origin);\n                if (url.pathname === LOGOUT_URL) {\n                    e.preventDefault();\n                    open();\n                }\n            } catch (_) { /* ignore malformed URLs */ }\n        });\n\n        document.addEventListener(\'keydown\', function (e) {\n            if (e.key === \'Escape\' && !modal.classList.contains(\'hidden\')) close();\n        });\n    })();\n    </script>\n\n    {# Global password show/hide toggle. Any button with [data-password-toggle]\n       toggles the type of the input it sits next to inside .password-field. #}\n    <script>\n    (function () {\n        document.addEventListener(\'click\', function (e) {\n            const btn = e.target.closest(\'[data-password-toggle]\');\n            if (!btn) return;\n            const wrapper = btn.closest(\'.password-field\');\n            if (!wrapper) return;\n            const input = wrapper.querySelector(\'input\');\n            const icon  = btn.querySelector(\'i\');\n            if (!input) return;\n            const showing = input.type === \'text\';\n            input.type = showing ? \'password\' : \'text\';\n            btn.setAttribute(\'aria-label\', showing ? \'Show password\' : \'Hide password\');\n            btn.setAttribute(\'aria-pressed\', showing ? \'false\' : \'true\');\n            if (icon) {\n                icon.classList.toggle(\'fa-eye\', showing);\n                icon.classList.toggle(\'fa-eye-slash\', !showing);\n            }\n        });\n    })();\n    </script>\n\n    {# Client-side pagination for tables / lists. #}\n    <script src="{{ url_for(\'static\', filename=\'js/pagination.js\') }}" defer></script>\n\n    {# About Us modal open/close #}\n    <script>\n    (function () {\n        const modal = document.getElementById(\'about-modal\');\n        if (!modal) return;\n        function open() { modal.classList.remove(\'hidden\'); }\n        function close() { modal.classList.add(\'hidden\'); }\n        document.addEventListener(\'click\', function (e) {\n            if (e.target.closest(\'[data-about-open]\')) { e.preventDefault(); open(); return; }\n            if (e.target.closest(\'[data-about-close]\')) { close(); return; }\n        });\n        document.addEventListener(\'keydown\', function (e) {\n            if (e.key === \'Escape\') close();\n        });\n    })();\n    </script>\n</body>\n</html>\n',
    '_notification_button.html': '{# Fixed notification bell shown on student/admin pages.\n   The dropdown panel sits directly below the button and reads from\n   the `notifications` context processor (services.notifications). #}\n\n{% set tone_styles = {\n    \'brand\':  \'bg-brand-50 text-brand-700\',\n    \'blue\':   \'bg-blue-50 text-blue-700\',\n    \'green\':  \'bg-green-50 text-green-700\',\n    \'red\':    \'bg-red-50 text-red-700\',\n    \'purple\': \'bg-purple-50 text-purple-700\',\n    \'slate\':  \'bg-slate-100 text-slate-700\',\n} %}\n\n<div class="fixed top-3 right-3 sm:top-4 sm:right-4 z-50">\n    <div class="relative" id="notif-root">\n        <button type="button" id="notif-button"\n                class="relative inline-flex items-center justify-center w-10 h-10 sm:w-11 sm:h-11 rounded-full bg-white shadow-lg border border-slate-200 text-slate-700 hover:text-brand-700 hover:bg-brand-50"\n                aria-haspopup="true" aria-expanded="false" aria-label="Notifications">\n            <i class="fa-solid fa-bell"></i>\n            <span id="notif-badge"\n                  class="hidden absolute -top-1 -right-1 min-w-[1.1rem] h-[1.1rem] px-1 rounded-full bg-red-500 text-white text-[10px] font-semibold flex items-center justify-center">\n                0\n            </span>\n        </button>\n\n        <div id="notif-panel"\n             class="hidden absolute right-0 mt-2 w-96 max-w-[calc(100vw-2rem)] bg-white rounded-xl shadow-xl border border-slate-100 overflow-hidden">\n            <div class="px-4 py-3 border-b flex items-center justify-between">\n                <span class="font-semibold text-sm">Notifications</span>\n                <div class="flex items-center gap-3">\n                    <button type="button" id="notif-mark-read"\n                            class="text-xs text-brand-600 hover:underline"\n                            title="Mark all as read">\n                        Mark all read\n                    </button>\n                    <button type="button" id="notif-close"\n                            class="text-slate-400 hover:text-slate-600"\n                            aria-label="Close">\n                        <i class="fa-solid fa-xmark"></i>\n                    </button>\n                </div>\n            </div>\n\n            <div class="max-h-96 overflow-y-auto divide-y divide-slate-100"\n                 id="notif-list" data-notif-list>\n                {% if notifications %}\n                    {% for n in notifications %}\n                        {% set href_url = url_for(n.endpoint) %}\n                        {% if n.anchor %}{% set href_url = href_url ~ \'#\' ~ n.anchor %}{% endif %}\n                        <a href="{{ href_url }}"\n                           class="block px-4 py-3 hover:bg-slate-50 transition"\n                           data-notif-item data-notif-id="{{ n.id }}">\n                            <div class="flex items-start gap-3">\n                                <span class="shrink-0 w-9 h-9 rounded-full flex items-center justify-center text-sm\n                                            {{ tone_styles.get(n.tone, \'bg-slate-100 text-slate-700\') }}">\n                                    <i class="fa-solid {{ n.icon }}"></i>\n                                </span>\n                                <div class="min-w-0 flex-1">\n                                    <div class="flex items-center justify-between gap-2">\n                                        <p class="text-sm font-semibold text-slate-800 truncate">\n                                            {{ n.title }}\n                                        </p>\n                                        {% if n.created_at %}\n                                            <time class="text-[11px] text-slate-400 whitespace-nowrap">\n                                                {{ n.created_at | ph_date }}\n                                            </time>\n                                        {% endif %}\n                                    </div>\n                                    {% if n.body %}\n                                        <p class="text-xs text-slate-600 mt-0.5 line-clamp-2">\n                                            {{ n.body }}\n                                        </p>\n                                    {% endif %}\n                                </div>\n                            </div>\n                        </a>\n                    {% endfor %}\n                {% else %}\n                    <p class="px-4 py-6 text-sm text-slate-500 text-center">\n                        You\'re all caught up.\n                    </p>\n                {% endif %}\n            </div>\n        </div>\n    </div>\n</div>\n\n<script>\n(function () {\n    const root    = document.getElementById(\'notif-root\');\n    const btn     = document.getElementById(\'notif-button\');\n    const panel   = document.getElementById(\'notif-panel\');\n    const closeB  = document.getElementById(\'notif-close\');\n    const badge   = document.getElementById(\'notif-badge\');\n    const list    = document.getElementById(\'notif-list\');\n    const markBtn = document.getElementById(\'notif-mark-read\');\n    if (!root || !btn || !panel) return;\n\n    // ----- Read state stored locally per browser -----\n    const STORAGE_KEY = \'sk-notif-read-v1\';\n    function readSet() {\n        try { return new Set(JSON.parse(localStorage.getItem(STORAGE_KEY) || \'[]\')); }\n        catch (_) { return new Set(); }\n    }\n    function writeSet(set) {\n        try { localStorage.setItem(STORAGE_KEY, JSON.stringify(Array.from(set))); }\n        catch (_) {}\n    }\n\n    function currentIds() {\n        return Array.from(list ? list.querySelectorAll(\'[data-notif-id]\') : [])\n                    .map(el => el.dataset.notifId);\n    }\n\n    function refreshBadge() {\n        if (!badge) return;\n        const ids   = currentIds();\n        const seen  = readSet();\n        const unread = ids.filter(id => !seen.has(id)).length;\n        if (unread > 0) {\n            badge.textContent = unread > 9 ? \'9+\' : String(unread);\n            badge.classList.remove(\'hidden\');\n        } else {\n            badge.classList.add(\'hidden\');\n        }\n    }\n\n    function markAllRead() {\n        const set = readSet();\n        currentIds().forEach(id => set.add(id));\n        writeSet(set);\n        refreshBadge();\n    }\n\n    // Mark items as read when the user clicks one (before the redirect).\n    if (list) {\n        list.addEventListener(\'click\', function (e) {\n            const item = e.target.closest(\'[data-notif-item]\');\n            if (!item) return;\n            const id = item.dataset.notifId;\n            if (!id) return;\n            const set = readSet();\n            set.add(id);\n            writeSet(set);\n            // No need to refresh the badge — we\'re navigating away anyway.\n        });\n    }\n\n    if (markBtn) {\n        markBtn.addEventListener(\'click\', function (e) {\n            e.stopPropagation();\n            markAllRead();\n        });\n    }\n\n    // ----- Open / close the panel -----\n    function open() {\n        panel.classList.remove(\'hidden\');\n        btn.setAttribute(\'aria-expanded\', \'true\');\n    }\n    function close() {\n        panel.classList.add(\'hidden\');\n        btn.setAttribute(\'aria-expanded\', \'false\');\n    }\n    function toggle() {\n        panel.classList.contains(\'hidden\') ? open() : close();\n    }\n\n    btn.addEventListener(\'click\', (e) => { e.stopPropagation(); toggle(); });\n    closeB && closeB.addEventListener(\'click\', close);\n    document.addEventListener(\'click\', (e) => {\n        if (!root.contains(e.target)) close();\n    });\n    document.addEventListener(\'keydown\', (e) => {\n        if (e.key === \'Escape\') close();\n    });\n\n    refreshBadge();\n})();\n</script>\n',
    'admin/announcements.html': '{% extends "admin/_layout.html" %}\n{% block title %}Events · Admin{% endblock %}\n\n{% set status_styles = {\n    \'open\':        \'bg-green-100 text-green-800\',\n    \'upcoming\':    \'bg-amber-100 text-amber-800\',\n    \'closed\':      \'bg-slate-200 text-slate-700\',\n    \'unscheduled\': \'bg-slate-100 text-slate-600\',\n} %}\n{% set category_styles = {\n    \'registration\': \'bg-brand-50 text-brand-700\',\n    \'payout\':       \'bg-blue-50 text-blue-700\',\n    \'general_orientation\':  \'bg-purple-50 text-purple-700\',\n    \'general\':      \'bg-slate-100 text-slate-700\',\n} %}\n\n{% block admin_content %}\n<div class="flex items-center justify-between flex-wrap gap-3 mb-4">\n    <div>\n        <h1 class="text-2xl font-bold text-brand-700">Events</h1>\n        <p class="text-sm text-slate-500">\n            {{ announcements|length }} published\n        </p>\n    </div>\n    <button type="button" data-announce-open\n            class="inline-flex items-center gap-2 px-4 py-2 rounded-md bg-brand-500 hover:bg-brand-600 text-white text-sm font-medium">\n        <i class="fa-solid fa-plus"></i>\n        Create event\n    </button>\n</div>\n\n{% if announcements %}\n    <div class="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">\n        <div class="px-3 py-3 border-b flex items-center gap-2 flex-wrap">\n            <div class="relative w-full sm:w-80">\n                <i class="fa-solid fa-magnifying-glass absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-xs"></i>\n                <input type="search" id="events-search" placeholder="Hanapin sa title, body, o category"\n                       class="w-full pl-8 pr-3 py-1.5 rounded-md border border-slate-300 text-sm focus:outline-none focus:ring-2 focus:ring-brand-400" />\n            </div>\n            <button type="button" data-search-btn="#events-search"\n                    class="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-md bg-brand-500 hover:bg-brand-600 text-white text-sm font-medium whitespace-nowrap">\n                <i class="fa-solid fa-magnifying-glass text-xs"></i>\n                Search\n            </button>\n        </div>\n        <div class="space-y-3 p-3 max-h-[40rem] overflow-y-auto"\n             data-paginate data-page-size="15"\n             data-paginate-search="#events-search"\n             data-pagination-into="#announcements-pagination">\n            {% for a in announcements %}\n                <article id="anc-{{ a.id }}" data-page-item class="bg-white rounded-lg shadow-sm p-4 border border-slate-100 scroll-mt-24">\n                    <div class="flex items-start justify-between gap-3 flex-wrap">\n                        <div class="min-w-0">\n                            <div class="flex items-center gap-2 flex-wrap mb-1">\n                                <span class="text-xs px-2 py-0.5 rounded {{ category_styles.get(a.category, \'bg-slate-100 text-slate-700\') }}">\n                                    {{ category_labels.get(a.category, \'General\') }}\n                                </span>\n                                <span class="text-xs uppercase px-2 py-0.5 rounded {{ status_styles.get(a.status, \'bg-slate-100 text-slate-700\') }}">\n                                    {{ a.status }}\n                                </span>\n                            </div>\n                            <h3 class="font-semibold">{{ a.title }}</h3>\n                        </div>\n                        <time class="text-xs text-slate-500 whitespace-nowrap">{{ a.created_at | ph_date }}</time>\n                    </div>\n                    {% if a.start_at and a.end_at %}\n                        <p class="text-xs text-slate-500 mt-1">\n                            <i class="fa-regular fa-calendar mr-1"></i>\n                            {{ a.start_at | ph }} → {{ a.end_at | ph }}\n                        </p>\n                    {% endif %}\n                    <p class="text-[11px] text-slate-500 mt-1 flex items-center gap-1.5 flex-wrap">\n                        <span class="uppercase tracking-wide">Channels:</span>\n                        {% if a.notify_landing %}\n                            <span class="inline-flex items-center gap-1 px-1.5 py-0.5 rounded bg-brand-50 text-brand-700"><i class="fa-solid fa-globe text-[10px]"></i> Landing</span>\n                        {% endif %}\n                        {% if a.notify_inapp %}\n                            <span class="inline-flex items-center gap-1 px-1.5 py-0.5 rounded bg-blue-50 text-blue-700"><i class="fa-solid fa-bell text-[10px]"></i> In-app</span>\n                        {% endif %}\n                        {% if a.notify_email %}\n                            <span class="inline-flex items-center gap-1 px-1.5 py-0.5 rounded bg-purple-50 text-purple-700"><i class="fa-solid fa-envelope text-[10px]"></i> Email</span>\n                        {% endif %}\n                        {% if not (a.notify_landing or a.notify_inapp or a.notify_email) %}\n                            <span class="text-slate-400">none</span>\n                        {% endif %}\n                    </p>\n                    <p class="mt-2 text-sm text-slate-700 whitespace-pre-line">{{ a.body }}</p>\n\n                    <div class="mt-3 flex items-center gap-3 flex-wrap">\n                        {% if a.category in (\'payout\', \'general_orientation\') %}\n                            <a href="{{ url_for(\'admin.announcement_joiners\', anc_id=a.id) }}"\n                               class="text-sm text-brand-600 hover:underline">\n                                <i class="fa-solid fa-users mr-1"></i>\n                                {{ a.join_count or 0 }} joined — view list\n                            </a>\n                        {% endif %}\n\n                        {# ---- Reopen / Close override ---- #}\n                        {% if a.category in (\'registration\', \'payout\', \'general_orientation\') %}\n                            <div class="inline-flex items-center gap-1 flex-wrap text-xs">\n                                {% if a.manual_status %}\n                                    <span class="px-2 py-0.5 rounded bg-amber-50 text-amber-700 border border-amber-200">\n                                        <i class="fa-solid fa-hand mr-1"></i>\n                                        Manually {{ a.manual_status }}\n                                    </span>\n                                    <form method="post"\n                                          action="{{ url_for(\'admin.set_announcement_status\', anc_id=a.id) }}"\n                                          class="inline">\n                                        <input type="hidden" name="manual_status" value="" />\n                                        <button type="submit"\n                                                class="px-2 py-1 rounded border border-slate-200 hover:bg-slate-50 text-slate-700">\n                                            <i class="fa-solid fa-rotate-left mr-1"></i>Use schedule\n                                        </button>\n                                    </form>\n                                {% endif %}\n                                {% if a.status != \'open\' %}\n                                    <form method="post"\n                                          action="{{ url_for(\'admin.set_announcement_status\', anc_id=a.id) }}"\n                                          class="inline"\n                                          onsubmit="return confirm(\'Reopen this event? Students can join again kahit lampas na sa schedule.\');">\n                                        <input type="hidden" name="manual_status" value="open" />\n                                        <button type="submit"\n                                                class="px-2 py-1 rounded bg-green-600 hover:bg-green-700 text-white">\n                                            <i class="fa-solid fa-lock-open mr-1"></i>Reopen\n                                        </button>\n                                    </form>\n                                {% endif %}\n                                {% if a.status != \'closed\' %}\n                                    <form method="post"\n                                          action="{{ url_for(\'admin.set_announcement_status\', anc_id=a.id) }}"\n                                          class="inline"\n                                          onsubmit="return confirm(\'Close this event now? Hindi makaka-join ang mga student kahit nasa schedule pa.\');">\n                                        <input type="hidden" name="manual_status" value="closed" />\n                                        <button type="submit"\n                                                class="px-2 py-1 rounded bg-slate-600 hover:bg-slate-700 text-white">\n                                            <i class="fa-solid fa-lock mr-1"></i>Close\n                                        </button>\n                                    </form>\n                                {% endif %}\n                            </div>\n                        {% endif %}\n\n                        <form method="post"\n                              action="{{ url_for(\'admin.delete_announcement\', anc_id=a.id) }}"\n                              onsubmit="return confirm({% if a.category == \'registration\' %}\'Delete this registration event? This will also remove every application (pending, verified, or rejected) tied to this window and the files they uploaded. Verified students will no longer count as scholars.\'{% elif a.category in (\'payout\', \'general_orientation\') %}\'Delete this event? Joiners attached to it will also be removed.\'{% else %}\'Delete this event?\'{% endif %});"\n                              class="ml-auto">\n                            <button type="submit"\n                                    class="text-xs text-red-600 hover:underline">\n                                <i class="fa-solid fa-trash mr-1"></i>Delete\n                            </button>\n                        </form>\n                    </div>\n                </article>\n            {% endfor %}\n        </div>\n        <div id="announcements-pagination"></div>\n    </div>\n{% else %}\n    <div class="bg-white rounded-xl shadow-sm border border-slate-100 p-10 text-center">\n        <i class="fa-solid fa-bullhorn text-4xl text-slate-300 mb-3"></i>\n        <p class="text-slate-500 text-sm">No events yet. Click <span class="font-medium text-brand-600">Create event</span> above to publish your first.</p>\n    </div>\n{% endif %}\n\n{# ===== Create announcement modal ===== #}\n<div id="announce-modal"\n     class="hidden fixed inset-0 z-[60] flex items-center justify-center p-4"\n     role="dialog" aria-modal="true" aria-labelledby="announce-title">\n    <div class="absolute inset-0 bg-slate-900/60" data-announce-close></div>\n    <div class="relative bg-white rounded-xl shadow-xl w-full max-w-lg max-h-[90vh] flex flex-col overflow-hidden">\n        <div class="flex items-center justify-between px-5 py-3 border-b">\n            <h2 id="announce-title" class="text-lg font-bold text-brand-700">Post event</h2>\n            <button type="button" data-announce-close\n                    class="text-slate-400 hover:text-slate-600" aria-label="Close">\n                <i class="fa-solid fa-xmark text-lg"></i>\n            </button>\n        </div>\n        <form method="post" class="flex-1 overflow-y-auto px-5 py-4 space-y-3" id="announce-form">\n            <div>\n                <label class="block text-sm font-medium mb-1">Category</label>\n                <select name="category" id="cat-select" required\n                        class="w-full rounded-md border border-slate-300 px-3 py-2 text-sm bg-white focus:outline-none focus:ring-2 focus:ring-brand-400">\n                    <option value="registration">Scholarship Registration</option>\n                    <option value="payout">Scholarship Pay Out</option>\n                    <option value="general_orientation">General Orientation</option>\n                </select>\n            </div>\n            \n            <div id="orientation-prerequisite-field" style="display:none;" class="bg-amber-50 border border-amber-200 rounded-md p-3">\n                <label class="block text-sm font-medium mb-1 text-amber-900">\n                    <i class="fa-solid fa-lock mr-1"></i>\n                    Required General Orientation (Optional)\n                </label>\n                <select name="required_orientation_id" id="orientation-select"\n                        class="w-full rounded-md border border-amber-300 px-3 py-2 text-sm bg-white focus:outline-none focus:ring-2 focus:ring-amber-400">\n                    <option value="">None — any student can join/apply</option>\n                    {% for orient in orientation_events %}\n                        <option value="{{ orient.id }}">\n                            {{ orient.title }}\n                            {% if orient.start_at %}\n                                ({{ orient.start_at | ph_date }})\n                            {% endif %}\n                        </option>\n                    {% endfor %}\n                </select>\n                <p class="text-xs text-amber-700 mt-1">\n                    Kung pipiliin mo ang orientation event, only students who attended that event can apply for the scholarship or join the pay-out.\n                </p>\n            </div>\n            <div>\n                <label class="block text-sm font-medium mb-1">Title</label>\n                <input name="title" required\n                       class="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-400" />\n            </div>\n            <div>\n                <label class="block text-sm font-medium mb-1">Body</label>\n                <textarea name="body" rows="5" required\n                          class="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-400"></textarea>\n            </div>\n\n            <div id="schedule-fields" class="space-y-3">\n                <div>\n                    <label class="block text-sm font-medium mb-1">Start date &amp; time</label>\n                    <input type="datetime-local" name="start_at"\n                           class="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-400" />\n                </div>\n                <div>\n                    <label class="block text-sm font-medium mb-1">End date &amp; time</label>\n                    <input type="datetime-local" name="end_at"\n                           class="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-400" />\n                </div>\n                <p class="text-xs text-slate-500">\n                    For <span class="font-medium">Registration</span>, students can apply / upload only between these dates.<br/>\n                    For <span class="font-medium">Pay Out</span>, students can join only between these dates.<br/>\n                    For <span class="font-medium">General Orientation</span>, students can join only between these dates.\n                </p>\n            </div>\n\n            <fieldset class="border border-slate-200 rounded-md p-3 pt-2">\n                <legend class="px-1 text-xs font-semibold text-slate-600 uppercase tracking-wide">\n                    Where should this event appear?\n                </legend>\n                <p class="text-xs text-slate-500 mb-2">\n                    Pumili ng kahit isa. Default: lahat.\n                </p>\n                <label class="flex items-start gap-2 text-sm py-1 cursor-pointer">\n                    <input type="checkbox" name="notify_landing" value="1" checked\n                           class="mt-1 h-4 w-4 rounded border-slate-300 text-brand-600 focus:ring-brand-400" />\n                    <span>\n                        <span class="font-medium">Public landing page</span>\n                        <span class="block text-xs text-slate-500">Lalabas sa /home, kahit hindi naka-log in.</span>\n                    </span>\n                </label>\n                <label class="flex items-start gap-2 text-sm py-1 cursor-pointer">\n                    <input type="checkbox" name="notify_inapp" value="1" checked\n                           class="mt-1 h-4 w-4 rounded border-slate-300 text-brand-600 focus:ring-brand-400" />\n                    <span>\n                        <span class="font-medium">In-app notifications</span>\n                        <span class="block text-xs text-slate-500">Lalabas sa bell icon ng student at admin.</span>\n                    </span>\n                </label>\n                <label class="flex items-start gap-2 text-sm py-1 cursor-pointer">\n                    <input type="checkbox" name="notify_email" value="1" checked\n                           class="mt-1 h-4 w-4 rounded border-slate-300 text-brand-600 focus:ring-brand-400" />\n                    <span>\n                        <span class="font-medium">Email blast</span>\n                        <span class="block text-xs text-slate-500">Ipapadala sa email ng lahat ng active students.</span>\n                    </span>\n                </label>\n            </fieldset>\n\n            <div class="pt-2 flex gap-2 justify-end">\n                <button type="button" data-announce-close\n                        class="px-4 py-2 rounded-md border border-slate-300 text-slate-700 hover:bg-slate-50 text-sm">\n                    Cancel\n                </button>\n                <button type="submit"\n                        class="px-4 py-2 rounded-md bg-brand-500 hover:bg-brand-600 text-white text-sm font-medium">\n                    <i class="fa-solid fa-paper-plane mr-1"></i>\n                    Publish\n                </button>\n            </div>\n        </form>\n    </div>\n</div>\n\n<script>\n(function () {\n    // ----- modal open/close -----\n    const modal = document.getElementById(\'announce-modal\');\n    if (modal) {\n        function open()  { modal.classList.remove(\'hidden\'); document.body.classList.add(\'overflow-hidden\'); }\n        function close() { modal.classList.add(\'hidden\');    document.body.classList.remove(\'overflow-hidden\'); }\n        document.addEventListener(\'click\', function (e) {\n            if (e.target.closest(\'[data-announce-open]\'))  { e.preventDefault(); open();  return; }\n            if (e.target.closest(\'[data-announce-close]\')) { close(); return; }\n        });\n        document.addEventListener(\'keydown\', function (e) {\n            if (e.key === \'Escape\' && !modal.classList.contains(\'hidden\')) close();\n        });\n\n        // Auto-open the modal if the form was submitted with errors and we\n        // came back to this page; otherwise stay closed.\n        {% if request.method == \'POST\' %}open();{% endif %}\n    }\n\n    // ----- show/hide schedule fields based on category -----\n    const cat   = document.getElementById(\'cat-select\');\n    const sched = document.getElementById(\'schedule-fields\');\n    const orientField = document.getElementById(\'orientation-prerequisite-field\');\n    const orientSelect = document.getElementById(\'orientation-select\');\n    if (cat && sched) {\n        const startInput = sched.querySelector(\'input[name="start_at"]\');\n        const endInput   = sched.querySelector(\'input[name="end_at"]\');\n        // Every event category needs a start/end window.\n        sched.style.display = \'\';\n        startInput.required = true;\n        endInput.required   = true;\n        \n        // Show/hide orientation prerequisite field for registration and payout\n        function updateOrientationField() {\n            if (cat.value === \'registration\' || cat.value === \'payout\') {\n                orientField.style.display = \'\';\n            } else {\n                orientField.style.display = \'none\';\n                if (orientSelect) orientSelect.value = \'\';\n            }\n        }\n        cat.addEventListener(\'change\', updateOrientationField);\n        updateOrientationField();\n    }\n})();\n</script>\n{% endblock %}\n',
    'admin/announcement_joiners.html': '{% extends "admin/_layout.html" %}\n{% block title %}Joiners · Admin{% endblock %}\n\n{% set status_styles = {\n    \'open\':        \'bg-green-100 text-green-800\',\n    \'upcoming\':    \'bg-amber-100 text-amber-800\',\n    \'closed\':      \'bg-slate-200 text-slate-700\',\n    \'unscheduled\': \'bg-slate-100 text-slate-600\',\n} %}\n{% set category_labels = {\n    \'payout\':      \'Scholarship Pay Out\',\n    \'general_orientation\': \'General Orientation\',\n} %}\n{% set category_styles = {\n    \'payout\':      \'bg-blue-50 text-blue-700\',\n    \'general_orientation\': \'bg-purple-50 text-purple-700\',\n} %}\n\n{% block admin_content %}\n<a href="{{ url_for(\'admin.announcements\') }}" class="text-sm text-brand-600 hover:underline">&larr; All events</a>\n\n<section class="bg-white rounded-xl shadow-sm border border-slate-100 p-6 mt-2">\n    <header class="mb-3 flex items-start justify-between gap-3 flex-wrap">\n        <div class="min-w-0">\n            <div class="flex items-center gap-2 flex-wrap">\n                <span class="text-xs px-2 py-0.5 rounded {{ category_styles.get(announcement.category, \'bg-slate-100 text-slate-700\') }}">\n                    {{ category_labels.get(announcement.category, \'Event\') }}\n                </span>\n                <span class="text-xs uppercase px-2 py-0.5 rounded {{ status_styles.get(announcement.status, \'bg-slate-100 text-slate-700\') }}">\n                    {{ announcement.status }}\n                </span>\n            </div>\n            <h1 class="text-xl font-bold mt-1">{{ announcement.title }}</h1>\n            {% if announcement.start_at and announcement.end_at %}\n                <p class="text-xs text-slate-500 mt-1">\n                    <i class="fa-regular fa-calendar mr-1"></i>\n                    {{ announcement.start_at | ph }} → {{ announcement.end_at | ph }}\n                </p>\n            {% endif %}\n            <p class="mt-2 text-sm text-slate-700 whitespace-pre-line">{{ announcement.body }}</p>\n        </div>\n        {% if joins %}\n            <a href="{{ url_for(\'admin.announcement_joiners_pdf\', anc_id=announcement.id) }}"\n               class="inline-flex items-center gap-2 px-3 py-2 rounded-md bg-brand-500 hover:bg-brand-600 text-white text-sm font-medium whitespace-nowrap">\n                <i class="fa-solid fa-file-pdf"></i>\n                Export attendance PDF\n            </a>\n        {% endif %}\n    </header>\n\n    <h2 class="font-semibold mt-4 mb-2">Joiners ({{ joins | length }})</h2>\n    {% if joins %}\n        <div class="mb-3 flex items-center gap-2 flex-wrap">\n            <div class="relative w-full sm:w-72">\n                <i class="fa-solid fa-magnifying-glass absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-xs"></i>\n                <input type="search" id="joiners-search" placeholder="Hanapin ang pangalan ng joiner"\n                       class="w-full pl-8 pr-3 py-1.5 rounded-md border border-slate-300 text-sm focus:outline-none focus:ring-2 focus:ring-brand-400" />\n            </div>\n            <button type="button" data-search-btn="#joiners-search"\n                    class="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-md bg-brand-500 hover:bg-brand-600 text-white text-sm font-medium">\n                <i class="fa-solid fa-magnifying-glass text-xs"></i>\n                Search\n            </button>\n        </div>\n        <div class="overflow-x-auto rounded-md border border-slate-100">\n            <table class="w-full text-sm">\n                <thead class="bg-slate-50 text-slate-600 text-left sticky top-0 z-10">\n                    <tr>\n                        <th class="px-3 py-2 w-10">#</th>\n                        <th class="px-3 py-2">Student</th>\n                        <th class="px-3 py-2">Date of join</th>\n                        <th class="px-3 py-2 w-72">Signature</th>\n                    </tr>\n                </thead>\n                <tbody class="divide-y divide-slate-100"\n                       data-paginate data-page-size="15"\n                       data-paginate-search="#joiners-search"\n                       data-pagination-into="#joiners-pagination">\n                    {% for j in joins %}\n                        <tr data-page-item>\n                            <td class="px-3 py-2 text-slate-500">{{ loop.index }}</td>\n                            <td class="px-3 py-2 font-medium text-slate-800">\n                                {{ j.student.full_name if j.student else \'—\' }}\n                            </td>\n                            <td class="px-3 py-2 text-slate-500">\n                                {{ (j.signed_at or j.joined_at) | ph if (j.signed_at or j.joined_at) else \'—\' }}\n                            </td>\n                            <td class="px-3 py-2">\n                                {% if j.signature_data %}\n                                    <img src="{{ j.signature_data }}" alt="Signature"\n                                         class="h-12 sm:h-14 w-auto bg-white border border-slate-200 rounded" />\n                                {% else %}\n                                    <span class="text-xs text-slate-400">No signature on file</span>\n                                {% endif %}\n                            </td>\n                        </tr>\n                    {% endfor %}\n                </tbody>\n            </table>\n        </div>\n        <div id="joiners-pagination"></div>\n    {% else %}\n        <p class="text-sm text-slate-500">No joiners yet.</p>\n    {% endif %}\n</section>\n{% endblock %}\n',
    'admin/applications.html': '{% extends "admin/_layout.html" %}\n{% block title %}Applications · Admin{% endblock %}\n\n{% set status_styles = {\n    \'pending\':  \'bg-amber-100 text-amber-800\',\n    \'verified\': \'bg-green-100 text-green-800\',\n    \'rejected\': \'bg-red-100 text-red-800\',\n} %}\n\n{% block admin_content %}\n<div class="mb-5 flex items-start justify-between gap-3 flex-wrap">\n    <div>\n        <h1 class="text-2xl font-bold text-brand-700">Applications</h1>\n        <p class="text-sm text-slate-500">All submitted scholarship applications.</p>\n    </div>\n    {% if orphan_count and orphan_count > 0 %}\n        <form method="post" action="{{ url_for(\'admin.purge_orphan_applications\') }}"\n              onsubmit="return confirm(\'Purge {{ orphan_count }} orphan application{{ \'\' if orphan_count == 1 else \'s\' }} (their registration was deleted)? This permanently removes the rows and their uploaded files. Verified students from those windows will stop being scholars.\');">\n            <button type="submit"\n                    class="inline-flex items-center gap-2 px-3 py-2 rounded-md bg-red-50 hover:bg-red-100 text-red-700 text-sm font-medium border border-red-200">\n                <i class="fa-solid fa-broom"></i>\n                Purge {{ orphan_count }} orphan{{ \'\' if orphan_count == 1 else \'s\' }}\n            </button>\n        </form>\n    {% endif %}\n</div>\n\n{% if orphan_count and orphan_count > 0 %}\n    <div class="mb-5 p-3 sm:p-4 rounded-xl border border-amber-200 bg-amber-50 text-amber-800 text-xs sm:text-sm flex items-start gap-2 sm:gap-3">\n        <i class="fa-solid fa-triangle-exclamation mt-0.5"></i>\n        <div>\n            <p class="font-semibold">May {{ orphan_count }} orphan application{{ \'\' if orphan_count == 1 else \'s\' }}.</p>\n            <p>Naka-tag silang verified/rejected/pending pero burado na ang kanilang registration window. Hindi na sila lalabas sa list pero nasa database pa rin. Pindutin ang <span class="font-medium">Purge orphans</span> para tuluyan silang tanggalin.</p>\n        </div>\n    </div>\n{% endif %}\n\n<div class="grid sm:grid-cols-3 gap-4 mb-6">\n    {% for key in [\'pending\', \'verified\', \'rejected\'] %}\n        <div class="bg-white rounded-xl shadow-sm p-4 border border-slate-100">\n            <div class="text-xs uppercase tracking-wide text-slate-500">{{ key }}</div>\n            <div class="text-3xl font-bold mt-1">{{ counts.get(key, 0) }}</div>\n        </div>\n    {% endfor %}\n</div>\n\n<section class="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">\n    <div class="px-5 py-3 border-b flex items-center justify-between gap-3 flex-wrap">\n        <span class="font-semibold">Applications</span>\n        <div class="flex items-center gap-2 w-full sm:w-auto">\n            <div class="relative w-full sm:w-72">\n                <i class="fa-solid fa-magnifying-glass absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-xs"></i>\n                <input type="search" id="apps-search" placeholder="Hanapin ang pangalan ng student"\n                       class="w-full pl-8 pr-3 py-1.5 rounded-md border border-slate-300 text-sm focus:outline-none focus:ring-2 focus:ring-brand-400" />\n            </div>\n            <button type="button" data-search-btn="#apps-search"\n                    class="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-md bg-brand-500 hover:bg-brand-600 text-white text-sm font-medium whitespace-nowrap">\n                <i class="fa-solid fa-magnifying-glass text-xs"></i>\n                Search\n            </button>\n        </div>\n    </div>\n    {% if applications %}\n        <div class="overflow-x-auto max-h-[36rem] overflow-y-auto">\n            <table class="w-full text-sm">\n                <thead class="bg-slate-50 text-slate-600 text-left sticky top-0 z-10">\n                    <tr>\n                        <th class="px-5 py-2">Student</th>\n                        <th class="px-5 py-2">Submitted</th>\n                        <th class="px-5 py-2">Status</th>\n                        <th class="px-5 py-2"></th>\n                    </tr>\n                </thead>\n                <tbody class="divide-y divide-slate-100"\n                       data-paginate data-page-size="15"\n                       data-paginate-search="#apps-search"\n                       data-pagination-into="#applications-pagination">\n                    {% for a in applications %}\n                        <tr data-page-item>\n                            <td class="px-5 py-2">{{ a.student.full_name if a.student else \'—\' }}</td>\n                            <td class="px-5 py-2 text-slate-500">{{ a.created_at | ph_date }}</td>\n                            <td class="px-5 py-2">\n                                <span class="text-xs uppercase px-2 py-1 rounded {{ status_styles.get(a.status, \'bg-slate-100 text-slate-700\') }}">\n                                    {{ a.status }}\n                                </span>\n                            </td>\n                            <td class="px-5 py-2 text-right">\n                                <div class="inline-flex items-center gap-3">\n                                    <a href="{{ url_for(\'admin.review\', app_id=a.id) }}"\n                                       class="text-brand-600 hover:underline">Review</a>\n                                    <form method="post"\n                                          action="{{ url_for(\'admin.delete_application\', app_id=a.id) }}"\n                                          onsubmit="return confirm(\'Permanently delete this application{{ \' for \' ~ a.student.full_name if a.student and a.student.full_name else \'\' }}? Their uploaded documents will also be removed. This cannot be undone.\');"\n                                          class="inline">\n                                        <button type="submit"\n                                                class="text-red-600 hover:underline inline-flex items-center gap-1"\n                                                aria-label="Delete application">\n                                            <i class="fa-solid fa-trash text-xs"></i>\n                                            Delete\n                                        </button>\n                                    </form>\n                                </div>\n                            </td>\n                        </tr>\n                    {% endfor %}\n                </tbody>\n            </table>\n        </div>\n        <div id="applications-pagination"></div>\n    {% else %}\n        <p class="px-5 py-6 text-slate-500 text-sm">No applications yet.</p>\n    {% endif %}\n</section>\n{% endblock %}\n',
    'admin/certificates.html': '{% extends "admin/_layout.html" %}\n{% block title %}Certificates · Admin{% endblock %}\n\n{% set status_styles = {\n    \'open\':        \'bg-green-100 text-green-800\',\n    \'upcoming\':    \'bg-amber-100 text-amber-800\',\n    \'closed\':      \'bg-slate-200 text-slate-700\',\n    \'unscheduled\': \'bg-slate-100 text-slate-600\',\n} %}\n\n{% block admin_content %}\n<div class="flex items-center justify-between flex-wrap gap-3 mb-4">\n    <div>\n        <h1 class="text-2xl font-bold text-brand-700">Certificates</h1>\n        <p class="text-sm text-slate-500">\n            Pumili ng okasyon at ma-generate ang Certificate of Attendance para sa mga sumali.\n        </p>\n    </div>\n    <a href="{{ url_for(\'admin.certificate_preview\') }}"\n       target="_blank"\n       class="inline-flex items-center gap-2 px-3 py-2 rounded-md border border-slate-200 bg-white text-slate-700 hover:bg-slate-50 text-sm">\n        <i class="fa-regular fa-eye"></i>\n        Open blank preview\n    </a>\n</div>\n\n{% if selected %}\n    <div class="mb-4 p-3 sm:p-4 rounded-xl border border-brand-200 bg-brand-50 text-brand-800 text-xs sm:text-sm flex items-start gap-2 sm:gap-3">\n        <i class="fa-solid fa-circle-check mt-0.5"></i>\n        <div class="flex-1 min-w-0">\n            <p class="font-semibold">Certificates ready for "{{ selected.title }}".</p>\n            <p>\n                {% if (selected.join_count or 0) > 0 %}\n                    {{ selected.join_count }} joiner{{ \'\' if selected.join_count == 1 else \'s\' }} eligible. Pindutin ang\n                    <span class="font-medium">Generate certificates</span> sa kanan para mabuksan ang print-ready page.\n                {% else %}\n                    Wala pang sumali sa event na ito. Lalabas ang Generate button kapag may umattend na.\n                {% endif %}\n            </p>\n        </div>\n    </div>\n{% endif %}\n\n<div class="grid lg:grid-cols-[20rem_1fr] gap-4 lg:gap-6">\n    {# ---------- Event picker ---------- #}\n    <section class="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden h-fit">\n        <header class="px-4 py-3 border-b font-semibold text-sm">\n            Pumili ng okasyon\n        </header>\n        {% if events %}\n            <div class="px-3 py-3 border-b flex items-center gap-2 flex-wrap">\n                <div class="relative flex-1 min-w-0">\n                    <i class="fa-solid fa-magnifying-glass absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-xs"></i>\n                    <input type="search" id="cert-events-search" placeholder="Hanapin ang event"\n                           class="w-full pl-8 pr-3 py-1.5 rounded-md border border-slate-300 text-sm focus:outline-none focus:ring-2 focus:ring-brand-400" />\n                </div>\n                <button type="button" data-search-btn="#cert-events-search"\n                        class="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-md bg-brand-500 hover:bg-brand-600 text-white text-sm font-medium whitespace-nowrap">\n                    <i class="fa-solid fa-magnifying-glass text-xs"></i>\n                    Search\n                </button>\n            </div>\n            <ul class="divide-y divide-slate-100 max-h-[34rem] overflow-y-auto"\n                data-paginate data-page-size="50"\n                data-paginate-search="#cert-events-search"\n                data-pagination-into="#cert-events-pagination">\n                {% for e in events %}\n                    {% set is_selected = selected and selected.id == e.id %}\n                    <li data-page-item>\n                        <a href="{{ url_for(\'admin.certificates\', event_id=e.id) }}"\n                           class="block px-4 py-3 hover:bg-slate-50 transition {{ \'bg-brand-50\' if is_selected else \'\' }}">\n                            <div class="flex items-start gap-2 flex-wrap">\n                                <span class="text-[10px] uppercase px-2 py-0.5 rounded\n                                    {% if e.category == \'payout\' %}bg-blue-50 text-blue-700\n                                    {% else %}bg-purple-50 text-purple-700{% endif %}">\n                                    {{ category_labels.get(e.category, \'Event\') }}\n                                </span>\n                                <span class="text-[10px] uppercase px-2 py-0.5 rounded {{ status_styles.get(e.status, \'bg-slate-100 text-slate-700\') }}">\n                                    {{ e.status }}\n                                </span>\n                            </div>\n                            <p class="font-semibold text-sm text-slate-800 mt-1 truncate">{{ e.title }}</p>\n                            {% if e.start_at and e.end_at %}\n                                <p class="text-[11px] text-slate-500 mt-0.5">\n                                    <i class="fa-regular fa-calendar mr-1"></i>\n                                    {{ e.start_at | ph_date }} → {{ e.end_at | ph_date }}\n                                </p>\n                            {% endif %}\n                            <p class="text-[11px] text-slate-500 mt-0.5">\n                                <i class="fa-solid fa-users mr-1"></i>\n                                {{ e.join_count or 0 }} joined\n                            </p>\n                        </a>\n                    </li>\n                {% endfor %}\n            </ul>\n            <div id="cert-events-pagination"></div>\n        {% else %}\n            <div class="px-4 py-8 text-center text-sm text-slate-500">\n                <i class="fa-solid fa-people-group text-2xl text-slate-300 mb-2 block"></i>\n                Wala pang Pay-out o General Orientation event na napost. Lumikha muna sa Events.\n            </div>\n        {% endif %}\n    </section>\n\n    {# ---------- Selected event details + preview ---------- #}\n    <section class="space-y-4 min-w-0">\n        {% if selected %}\n            <div class="bg-white rounded-xl shadow-sm border border-slate-100 p-4 sm:p-5">\n                <div class="flex items-start justify-between gap-3 flex-wrap">\n                    <div class="min-w-0">\n                        <span class="text-[10px] uppercase px-2 py-0.5 rounded\n                            {% if selected.category == \'payout\' %}bg-blue-50 text-blue-700\n                            {% else %}bg-purple-50 text-purple-700{% endif %}">\n                            {{ category_labels.get(selected.category, \'Event\') }}\n                        </span>\n                        <h2 class="text-lg sm:text-xl font-bold text-slate-800 mt-1 truncate">\n                            {{ selected.title }}\n                        </h2>\n                        {% if selected.start_at and selected.end_at %}\n                            <p class="text-xs text-slate-500 mt-1">\n                                <i class="fa-regular fa-calendar mr-1"></i>\n                                {{ selected.start_at | ph }} → {{ selected.end_at | ph }}\n                            </p>\n                        {% endif %}\n                        <p class="text-xs text-slate-500 mt-0.5">\n                            <i class="fa-solid fa-users mr-1"></i>\n                            {{ selected.join_count or 0 }} joiners eligible\n                        </p>\n                    </div>\n                    <div class="flex items-center gap-2 flex-wrap">\n                        <a href="{{ url_for(\'admin.announcement_joiners\', anc_id=selected.id) }}"\n                           class="inline-flex items-center gap-2 px-3 py-2 rounded-md border border-slate-200 bg-white text-slate-700 hover:bg-slate-50 text-sm">\n                            <i class="fa-solid fa-list-check"></i>\n                            View joiners\n                        </a>\n                        {% if (selected.join_count or 0) > 0 %}\n                            <a href="{{ url_for(\'admin.generate_certificates\', event_id=selected.id) }}"\n                               target="_blank"\n                               class="inline-flex items-center gap-2 px-3 py-2 rounded-md bg-brand-500 hover:bg-brand-600 text-white text-sm font-medium">\n                                <i class="fa-solid fa-file-arrow-down"></i>\n                                Generate certificates\n                            </a>\n                        {% else %}\n                            <button type="button" disabled\n                                    title="Walang sumali pa sa event na ito"\n                                    class="inline-flex items-center gap-2 px-3 py-2 rounded-md bg-slate-300 text-white text-sm font-medium cursor-not-allowed">\n                                <i class="fa-solid fa-file-arrow-down"></i>\n                                Generate certificates\n                            </button>\n                        {% endif %}\n                    </div>\n                </div>\n                {% if selected.body %}\n                    <p class="mt-3 text-sm text-slate-700 whitespace-pre-line">{{ selected.body }}</p>\n                {% endif %}\n            </div>\n        {% else %}\n            <div class="bg-white rounded-xl shadow-sm border border-slate-100 p-4 sm:p-5 text-sm text-slate-500">\n                <i class="fa-regular fa-hand-pointer mr-1"></i>\n                Pumili ng okasyon mula sa kaliwa para makita ang preview.\n            </div>\n        {% endif %}\n\n        <div class="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">\n            <header class="px-4 py-3 border-b flex items-center justify-between flex-wrap gap-2">\n                <div>\n                    <h3 class="font-semibold text-sm">Certificate preview</h3>\n                    <p class="text-[11px] text-slate-500">\n                        Ito ang design na gagamitin sa Certificate of Attendance.\n                    </p>\n                </div>\n                <a href="{{ url_for(\'admin.certificate_preview\') }}"\n                   target="_blank"\n                   class="text-xs text-brand-600 hover:underline">\n                    <i class="fa-solid fa-up-right-from-square mr-1"></i>\n                    Buksan sa bagong tab\n                </a>\n            </header>\n            <div class="p-3 sm:p-4 bg-slate-100">\n                <iframe src="{{ url_for(\'admin.certificate_preview\') }}"\n                        class="w-full bg-white rounded-md shadow-sm"\n                        style="height: 540px; border: 0;"\n                        title="Certificate preview"></iframe>\n            </div>\n        </div>\n    </section>\n</div>\n{% endblock %}\n',
    'admin/certificate_template.html': '<!doctype html>\n<html lang="en">\n<head>\n    <meta charset="utf-8" />\n    <title>{% if event %}{{ event.title }} · Certificates{% else %}Certificate of Attendance{% endif %}</title>\n    <link rel="preconnect" href="https://fonts.googleapis.com">\n    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n    <link href="https://fonts.googleapis.com/css2?family=Cinzel:wght@500;700;900&family=Cormorant+Garamond:wght@400;500;700&family=Poppins:wght@300;400;500;600;700&display=swap"\n          rel="stylesheet">\n    <style>\n        :root {\n            --gold:        #b08642;\n            --gold-light:  #d8b46d;\n            --paper:       #fdfaf1;\n            --ink:         #2b2b2b;\n            --ink-muted:   #4a4a4a;\n            --accent-blue: #1f3a8a;\n            --accent-red:  #b81d20;\n        }\n\n        * { box-sizing: border-box; }\n\n        @page { size: A4 landscape; margin: 0; }\n\n        html, body {\n            margin: 0;\n            padding: 0;\n            background: #e7e3d6;\n            font-family: \'Poppins\', system-ui, -apple-system, \'Segoe UI\', sans-serif;\n            color: var(--ink);\n            -webkit-print-color-adjust: exact;\n            print-color-adjust: exact;\n        }\n\n        .toolbar {\n            position: sticky;\n            top: 0;\n            z-index: 5;\n            background: rgba(255, 255, 255, .95);\n            border-bottom: 1px solid #d8d4c4;\n            padding: 8px 16px;\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            gap: 12px;\n            flex-wrap: wrap;\n            font-size: 13px;\n        }\n        .toolbar .info { color: #475569; }\n        .toolbar .info b { color: #1f2937; }\n        .toolbar .actions { display: flex; gap: 8px; }\n        .toolbar button, .toolbar a.btn {\n            display: inline-flex; align-items: center; gap: 6px;\n            padding: 6px 12px;\n            border-radius: 6px;\n            border: 1px solid transparent;\n            font-weight: 500;\n            cursor: pointer;\n            text-decoration: none;\n        }\n        .toolbar .btn-primary { background: #6f9d63; color: #fff; }\n        .toolbar .btn-primary:hover { background: #5a8550; }\n        .toolbar .btn-ghost { background: #fff; border-color: #e2e8f0; color: #1f2937; }\n        .toolbar .btn-ghost:hover { background: #f1f5f9; }\n        .toolbar .btn-mail { background: #1f3a8a; color: #fff; }\n        .toolbar .btn-mail:hover { background: #1a3071; }\n        .toolbar .btn-mail[disabled] { opacity: .65; cursor: progress; }\n\n        .send-row {\n            position: absolute;\n            top: 14px;\n            right: 28px;\n            z-index: 4;\n            display: flex;\n            gap: 6px;\n            font-family: \'Poppins\', sans-serif;\n        }\n        .send-row .send-btn {\n            display: inline-flex; align-items: center; gap: 6px;\n            padding: 6px 12px;\n            border-radius: 999px;\n            border: 1px solid #1f3a8a;\n            background: #1f3a8a;\n            color: #fff;\n            font-size: 12px;\n            font-weight: 600;\n            cursor: pointer;\n            box-shadow: 0 6px 14px -8px rgba(31,58,138,.6);\n        }\n        .send-row .send-btn:hover { background: #1a3071; }\n        .send-row .send-btn[disabled] { opacity: .55; cursor: progress; }\n        .send-row .send-status {\n            display: inline-flex;\n            align-items: center;\n            padding: 4px 10px;\n            border-radius: 999px;\n            font-size: 11px;\n            font-weight: 500;\n            background: #fff;\n            border: 1px solid #e2e8f0;\n            color: #475569;\n        }\n        .send-row .send-status.ok    { background: #ecfdf5; border-color: #a7f3d0; color: #065f46; }\n        .send-row .send-status.err   { background: #fef2f2; border-color: #fecaca; color: #991b1b; }\n        .send-row .send-status:empty { display: none; }\n\n        .page {\n            width: 1056px;\n            max-width: 100%;\n            aspect-ratio: 1056 / 612;       /* close to landscape A4 */\n            margin: 24px auto;\n            background: var(--paper);\n            position: relative;\n            overflow: hidden;\n            box-shadow: 0 24px 60px -28px rgba(0,0,0,.35), 0 6px 18px -10px rgba(0,0,0,.18);\n            border-radius: 6px;\n        }\n\n        /* ---------- Decorative borders ---------- */\n        .frame-outer {\n            position: absolute;\n            inset: 16px;\n            border: 6px double var(--gold);\n            border-radius: 4px;\n            pointer-events: none;\n        }\n        .frame-inner {\n            position: absolute;\n            inset: 28px;\n            border: 1px solid var(--gold-light);\n            border-radius: 2px;\n            pointer-events: none;\n        }\n\n        .watermark {\n            position: absolute;\n            inset: 0;\n            opacity: .08;\n            background-image:\n                radial-gradient(circle at 12% 28%, var(--gold) 0 1.2rem, transparent 1.4rem),\n                radial-gradient(circle at 88% 28%, var(--gold) 0 1.2rem, transparent 1.4rem),\n                radial-gradient(circle at 12% 78%, var(--gold) 0 1.2rem, transparent 1.4rem),\n                radial-gradient(circle at 88% 78%, var(--gold) 0 1.2rem, transparent 1.4rem);\n            pointer-events: none;\n        }\n        .silhouette { display: none; }\n\n        /* ---------- Header strip ---------- */\n        .header {\n            display: grid;\n            grid-template-columns: 96px 1fr 96px;\n            align-items: center;\n            text-align: center;\n            padding: 36px 56px 0;\n            position: relative;\n        }\n        .header .logo-wrap {\n            display: flex;\n            align-items: center;\n            justify-content: flex-start;\n        }\n        .header .logo-wrap img {\n            width: 88px;\n            height: 88px;\n            object-fit: contain;\n            border-radius: 8px;\n        }\n        .header .org {\n            font-family: \'Poppins\', sans-serif;\n            font-weight: 700;\n            font-size: 26px;\n            letter-spacing: .06em;\n            text-transform: uppercase;\n            color: var(--ink);\n        }\n        .header .location {\n            font-family: \'Poppins\', sans-serif;\n            font-size: 13px;\n            color: var(--ink-muted);\n            margin-top: 4px;\n            letter-spacing: .04em;\n        }\n\n        .title {\n            text-align: center;\n            font-family: \'Cinzel\', serif;\n            font-weight: 900;\n            font-size: 46px;\n            letter-spacing: .04em;\n            color: var(--ink);\n            margin: 22px 56px 8px;\n            text-shadow: 0 1px 0 rgba(0,0,0,.05);\n        }\n\n        .body {\n            text-align: center;\n            padding: 0 110px;\n            font-family: \'Cormorant Garamond\', \'Poppins\', serif;\n            color: var(--ink);\n            position: relative;\n            z-index: 1;\n        }\n        .body .lead {\n            font-size: 16px;\n            letter-spacing: .04em;\n            color: var(--ink-muted);\n            margin: 6px 0 4px;\n        }\n        .name-line {\n            border-bottom: 1.5px solid var(--ink);\n            padding: 4px 0;\n            margin: 6px auto 4px;\n            display: inline-block;\n            min-width: 70%;\n        }\n        .name-line .name {\n            font-family: \'Cinzel\', serif;\n            font-style: italic;\n            font-weight: 700;\n            font-size: 30px;\n            letter-spacing: .04em;\n        }\n        .home {\n            font-size: 15px;\n            color: var(--ink-muted);\n            margin: 2px 0 10px;\n        }\n        .narrative {\n            font-size: 15.5px;\n            line-height: 1.55;\n            color: var(--ink);\n            margin: 6px auto 0;\n            max-width: 720px;\n        }\n        .narrative .strong { font-weight: 700; }\n\n        .signatures {\n            margin: 22px 80px 0;\n            display: flex;\n            justify-content: center;\n            text-align: center;\n        }\n        .signatures > div {\n            min-width: 280px;\n            max-width: 360px;\n        }\n        .sig-block {\n            display: inline-block;\n            text-align: center;\n        }\n        .sig-name-top {\n            font-family: \'Cormorant Garamond\', serif;\n            font-weight: 700;\n            font-size: 16px;\n            margin-bottom: 2px;\n        }\n        .sig-line {\n            border-top: 1.2px solid var(--ink);\n            padding-top: 6px;\n            min-width: 240px;\n        }\n        .sig-role {\n            font-size: 11.5px;\n            color: var(--ink-muted);\n            letter-spacing: .04em;\n        }\n\n        .ribbon {\n            margin: 22px 36px 28px;\n            background: linear-gradient(90deg, var(--gold) 0%, #c89a4d 50%, var(--gold) 100%);\n            color: #fff;\n            text-align: center;\n            padding: 8px 24px;\n            font-family: \'Cinzel\', serif;\n            font-weight: 700;\n            font-size: 18px;\n            letter-spacing: .25em;\n            border-radius: 2px;\n            box-shadow: inset 0 0 0 1px var(--gold-light);\n        }\n        .ribbon .tag {\n            display: block;\n            font-family: \'Poppins\', sans-serif;\n            font-weight: 500;\n            font-size: 10px;\n            letter-spacing: .35em;\n            margin-top: 2px;\n            opacity: .9;\n        }\n\n        .ornament { display: none; }\n\n        /* ---------- Print ---------- */\n        @media print {\n            body { background: #fff; }\n            .toolbar { display: none !important; }\n            .send-row { display: none !important; }\n            .page {\n                margin: 0;\n                box-shadow: none;\n                border-radius: 0;\n                width: 100%;\n                aspect-ratio: auto;\n                height: 100vh;\n                page-break-after: always;\n                break-after: page;\n            }\n            .page:last-of-type {\n                page-break-after: auto;\n                break-after: auto;\n            }\n        }\n    </style>\n</head>\n<body>\n\n{% if not single %}\n<div class="toolbar">\n    <div class="info">\n        {% if event %}\n            <b>{{ event_label }}</b> &middot; {{ event.title }}\n        {% endif %}\n        <span style="margin-left:8px;">\n            {{ certificates | length }} certificate{{ \'\' if certificates|length == 1 else \'s\' }}\n        </span>\n    </div>\n    <div class="actions">\n        <a href="{{ url_for(\'admin.certificates\', event_id=event.id) if event else url_for(\'admin.certificates\') }}"\n           class="btn btn-ghost">\n            ← Back\n        </a>\n        {% if event %}\n            <button type="button"\n                    class="btn-mail"\n                    id="send-all-btn"\n                    data-url="{{ url_for(\'admin.send_certificates_bulk\', event_id=event.id) }}">\n                ✉ Send all to email\n            </button>\n        {% endif %}\n        <button type="button" class="btn-primary" onclick="window.print();">\n            🖨 Print / Save as PDF\n        </button>\n    </div>\n</div>\n{% endif %}\n\n{% for c in certificates %}\n    <div class="page" role="document" aria-label="Certificate of Attendance">\n        {% if not single and event and c.student_id %}\n            <div class="send-row" data-cert-row>\n                <span class="send-status" data-cert-status></span>\n                <button type="button"\n                        class="send-btn"\n                        data-cert-send\n                        data-url="{{ url_for(\'admin.send_certificate_to_student\', event_id=event.id, student_id=c.student_id) }}"\n                        data-name="{{ c.participant_name }}">\n                    ✉ Send to student\n                </button>\n            </div>\n        {% endif %}\n        <div class="frame-outer"></div>\n        <div class="frame-inner"></div>\n        <div class="watermark"></div>\n\n        <header class="header">\n            <div class="logo-wrap">\n                <img src="{{ url_for(\'static\', filename=\'images/411138383_122115055322131251_5783589540994116709_n.jpg\') }}"\n                     alt="SK Bukal Logo">\n            </div>\n            <div>\n                <div class="org">Sangguniang Kabataan</div>\n                <div class="location">Barangay Bukal, Majayjay, Laguna</div>\n            </div>\n            <div></div>\n        </header>\n\n        <h1 class="title">{{ c.title_text or \'CERTIFICATE OF ATTENDANCE\' }}</h1>\n\n        <section class="body">\n            <p class="lead">This is to certify that</p>\n            <div class="name-line">\n                <span class="name">{{ c.participant_name }}</span>\n            </div>\n            <p class="home">of {{ c.home_purok }}</p>\n\n            <p class="narrative">\n                has actively attended and participated in the\n                <span class="strong">{{ c.event_kind or c.event_title }}</span>{% if c.event_venue %} at {{ c.event_venue }}{% endif %}{% if c.event_theme %},\n                with the theme:\n                &ldquo;<span class="strong">{{ c.event_theme }}</span>&rdquo;{% endif %}.\n            </p>\n            {% if c.event_date %}\n                <p class="narrative" style="margin-top: 8px;">\n                    Held on <span class="strong">{{ c.event_date }}</span>.\n                </p>\n            {% endif %}\n        </section>\n\n        <section class="signatures">\n            <div>\n                <div class="sig-block">\n                    <div class="sig-name-top">{{ c.sk_chairperson }}</div>\n                    <div class="sig-line">\n                        <div class="sig-role">SK Chairperson</div>\n                    </div>\n                </div>\n            </div>\n        </section>\n\n        <div class="ribbon">\n            KATIPUNAN NG KABATAAN\n            <span class="tag">AKTIBONG KABATAAN, MAUNLAD NA PAMAYANAN</span>\n        </div>\n    </div>\n{% endfor %}\n\n{% if not single and event %}\n<script>\n(function () {\n    function setStatus(el, msg, kind) {\n        if (!el) return;\n        el.className = "send-status" + (kind ? " " + kind : "");\n        el.textContent = msg || "";\n    }\n\n    async function postJson(url) {\n        const res = await fetch(url, {\n            method: "POST",\n            headers: { "Accept": "application/json" },\n            credentials: "same-origin",\n        });\n        let data = {};\n        try { data = await res.json(); } catch (e) { /* non-JSON */ }\n        return { ok: res.ok && data.ok !== false, data, status: res.status };\n    }\n\n    // Per-certificate send buttons.\n    document.querySelectorAll("[data-cert-send]").forEach(function (btn) {\n        btn.addEventListener("click", async function () {\n            const row = btn.closest("[data-cert-row]");\n            const status = row ? row.querySelector("[data-cert-status]") : null;\n            btn.disabled = true;\n            setStatus(status, "Sending…");\n            try {\n                const { ok, data } = await postJson(btn.dataset.url);\n                if (ok) {\n                    setStatus(status, "Sent ✓ " + (data.email || ""), "ok");\n                    btn.textContent = "✓ Sent";\n                } else {\n                    setStatus(status,\n                        (data && data.error) || "Hindi naipadala.",\n                        "err");\n                    btn.disabled = false;\n                }\n            } catch (e) {\n                setStatus(status, "Network error.", "err");\n                btn.disabled = false;\n            }\n        });\n    });\n\n    // Bulk send.\n    const bulkBtn = document.getElementById("send-all-btn");\n    if (bulkBtn) {\n        bulkBtn.addEventListener("click", async function () {\n            const total = document.querySelectorAll("[data-cert-send]").length;\n            const msg = total\n                ? "Ipapadala ang " + total + " certificate(s) sa email ng bawat joiner. Ituloy?"\n                : "Ipapadala ang certificate sa email ng bawat joiner. Ituloy?";\n            if (!window.confirm(msg)) return;\n\n            const original = bulkBtn.textContent;\n            bulkBtn.disabled = true;\n            bulkBtn.textContent = "Sending…";\n            try {\n                const { ok, data } = await postJson(bulkBtn.dataset.url);\n                if (ok) {\n                    const queued = (data && (data.queued ?? data.sent)) || 0;\n                    window.alert(\n                        "Naka-queue na ang " + queued + " certificate. " +\n                        "Ipapadala sa email ng bawat joiner sa loob ng " +\n                        "ilang minuto.");\n                    // Mark every per-cert row as queued so the admin sees\n                    // we accepted the batch.\n                    document.querySelectorAll("[data-cert-row]").forEach(function (row) {\n                        const s = row.querySelector("[data-cert-status]");\n                        const b = row.querySelector("[data-cert-send]");\n                        setStatus(s, "Queued ✓", "ok");\n                        if (b) { b.disabled = true; b.textContent = "Queued"; }\n                    });\n                } else {\n                    window.alert((data && data.error) || "Hindi naipadala ang lahat.");\n                }\n            } catch (e) {\n                window.alert("Network error habang nag-send.");\n            } finally {\n                bulkBtn.disabled = false;\n                bulkBtn.textContent = original;\n            }\n        });\n    }\n})();\n</script>\n{% endif %}\n\n</body>\n</html>\n',
    'admin/dashboard.html': '{% extends "admin/_layout.html" %}\n{% block title %}Dashboard · Admin{% endblock %}\n\n{% set status_styles = {\n    \'pending\':  \'bg-amber-100 text-amber-800\',\n    \'verified\': \'bg-green-100 text-green-800\',\n    \'rejected\': \'bg-red-100 text-red-800\',\n    \'open\':        \'bg-green-100 text-green-800\',\n    \'upcoming\':    \'bg-amber-100 text-amber-800\',\n    \'closed\':      \'bg-slate-200 text-slate-700\',\n    \'unscheduled\': \'bg-slate-100 text-slate-600\',\n} %}\n\n{% macro stat_card(label, value, icon, tone=\'brand\', sub=None) %}\n    {% set tone_styles = {\n        \'brand\':  \'bg-brand-50 text-brand-700\',\n        \'blue\':   \'bg-blue-50 text-blue-700\',\n        \'green\':  \'bg-green-50 text-green-700\',\n        \'amber\':  \'bg-amber-50 text-amber-700\',\n        \'red\':    \'bg-red-50 text-red-700\',\n        \'purple\': \'bg-purple-50 text-purple-700\',\n        \'slate\':  \'bg-slate-100 text-slate-700\',\n    } %}\n    <div class="bg-white rounded-xl shadow-sm border border-slate-100 p-4 flex items-center gap-3">\n        <span class="w-11 h-11 rounded-md flex items-center justify-center text-lg {{ tone_styles.get(tone, tone_styles[\'brand\']) }}">\n            <i class="fa-solid {{ icon }}"></i>\n        </span>\n        <div class="min-w-0">\n            <p class="text-[11px] uppercase tracking-wide text-slate-500">{{ label }}</p>\n            <p class="text-2xl font-bold leading-tight truncate">{{ value }}</p>\n            {% if sub %}<p class="text-[11px] text-slate-500 truncate">{{ sub }}</p>{% endif %}\n        </div>\n    </div>\n{% endmacro %}\n\n{% block admin_content %}\n<header class="mb-5 flex items-start justify-between gap-3 flex-wrap">\n    <div>\n        <h1 class="text-2xl font-bold text-brand-700">Dashboard</h1>\n        <p class="text-sm text-slate-500">\n            Hi, {{ session.get(\'full_name\') or \'admin\' }}. Here\'s what\'s happening across the portal.\n        </p>\n    </div>\n    <div class="flex items-center gap-2 flex-wrap">\n        <a href="{{ url_for(\'admin.applications\') }}"\n           class="inline-flex items-center gap-2 px-3 py-2 rounded-md bg-brand-500 hover:bg-brand-600 text-white text-sm font-medium">\n            <i class="fa-solid fa-folder-open"></i> Review applications\n        </a>\n        <a href="{{ url_for(\'admin.announcements\') }}"\n           class="inline-flex items-center gap-2 px-3 py-2 rounded-md bg-white border border-slate-200 text-slate-700 hover:bg-slate-50 text-sm font-medium">\n            <i class="fa-solid fa-bullhorn"></i> Post event\n        </a>\n    </div>\n</header>\n\n{# ===================== Stat cards ===================== #}\n<div class="grid grid-cols-2 lg:grid-cols-4 gap-3 mb-5">\n    {{ stat_card(\'Pending review\', pending_count, \'fa-hourglass-half\', \'amber\',\n                 sub=\'waiting on admin\') }}\n    {{ stat_card(\'Verified scholars\', verified_count, \'fa-circle-check\', \'green\',\n                 sub=\'approved applications\') }}\n    {{ stat_card(\'Total students\', students_total, \'fa-user-graduate\', \'brand\',\n                 sub=(students_active|string) ~ \' active · \' ~ (students_deactivated|string) ~ \' deactivated\') }}\n    {{ stat_card(\'Event joiners\', joiners_total, \'fa-handshake\', \'blue\',\n                 sub=(events_total|string) ~ \' joinable events\') }}\n</div>\n\n{% if open_registration %}\n    <div class="mb-5 rounded-xl border border-brand-200 bg-brand-50 p-4 flex items-center gap-3 flex-wrap">\n        <span class="w-10 h-10 rounded-full bg-brand-500 text-white flex items-center justify-center shrink-0">\n            <i class="fa-solid fa-door-open"></i>\n        </span>\n        <div class="flex-1 min-w-0">\n            <p class="text-[11px] uppercase tracking-wide text-brand-700 font-semibold">\n                Registration window is open\n            </p>\n            <p class="font-semibold text-brand-800 truncate">{{ open_registration.title }}</p>\n            {% if open_registration.start_at and open_registration.end_at %}\n                <p class="text-xs text-brand-700/80">\n                    <i class="fa-regular fa-calendar mr-1"></i>\n                    {{ open_registration.start_at | ph }} → {{ open_registration.end_at | ph }}\n                </p>\n            {% endif %}\n        </div>\n        <a href="{{ url_for(\'admin.applications\') }}"\n           class="inline-flex items-center gap-2 px-3 py-2 rounded-md bg-brand-600 hover:bg-brand-700 text-white text-sm font-medium">\n            <i class="fa-solid fa-clipboard-list"></i> Track applications\n        </a>\n    </div>\n{% endif %}\n\n{# ===================== Charts ===================== #}\n<div class="grid lg:grid-cols-2 gap-4 mb-5">\n\n    {# 14-day trend #}\n    <section class="bg-white rounded-xl shadow-sm border border-slate-100 p-4">\n        <header class="flex items-center justify-between mb-3">\n            <div>\n                <h2 class="font-semibold">Submissions in the last 14 days</h2>\n                <p class="text-xs text-slate-500">Daily count of student applications.</p>\n            </div>\n            <i class="fa-solid fa-chart-line text-slate-300"></i>\n        </header>\n        <div class="h-[220px]">\n            <canvas id="chart-trend"></canvas>\n        </div>\n    </section>\n\n    {# Application status doughnut #}\n    <section class="bg-white rounded-xl shadow-sm border border-slate-100 p-4">\n        <header class="flex items-center justify-between mb-3">\n            <div>\n                <h2 class="font-semibold">Application status</h2>\n                <p class="text-xs text-slate-500">Pending vs verified vs rejected.</p>\n            </div>\n            <i class="fa-solid fa-circle-half-stroke text-slate-300"></i>\n        </header>\n        <div class="h-[220px] flex items-center justify-center">\n            <canvas id="chart-status"></canvas>\n        </div>\n    </section>\n\n    {# Education level bar #}\n    <section class="bg-white rounded-xl shadow-sm border border-slate-100 p-4">\n        <header class="flex items-center justify-between mb-3">\n            <div>\n                <h2 class="font-semibold">By education level</h2>\n                <p class="text-xs text-slate-500">All submitted applications.</p>\n            </div>\n            <i class="fa-solid fa-graduation-cap text-slate-300"></i>\n        </header>\n        <div class="h-[220px]">\n            <canvas id="chart-level"></canvas>\n        </div>\n    </section>\n\n    {# Year level bar #}\n    <section class="bg-white rounded-xl shadow-sm border border-slate-100 p-4">\n        <header class="flex items-center justify-between mb-3">\n            <div>\n                <h2 class="font-semibold">By year level</h2>\n                <p class="text-xs text-slate-500">Distribution across grades / years.</p>\n            </div>\n            <i class="fa-solid fa-layer-group text-slate-300"></i>\n        </header>\n        <div class="h-[220px]">\n            <canvas id="chart-year"></canvas>\n        </div>\n    </section>\n\n    {# Event category mix #}\n    <section class="bg-white rounded-xl shadow-sm border border-slate-100 p-4">\n        <header class="flex items-center justify-between mb-3">\n            <div>\n                <h2 class="font-semibold">Event mix</h2>\n                <p class="text-xs text-slate-500">Posts grouped by category.</p>\n            </div>\n            <i class="fa-solid fa-bullhorn text-slate-300"></i>\n        </header>\n        <div class="h-[220px] flex items-center justify-center">\n            <canvas id="chart-category"></canvas>\n        </div>\n    </section>\n\n    {# Top events by joiners #}\n    <section class="bg-white rounded-xl shadow-sm border border-slate-100 p-4">\n        <header class="flex items-center justify-between mb-3">\n            <div>\n                <h2 class="font-semibold">Top events by joiners</h2>\n                <p class="text-xs text-slate-500">Pay-outs and General Orientation events combined.</p>\n            </div>\n            <i class="fa-solid fa-people-group text-slate-300"></i>\n        </header>\n        <div class="h-[220px]">\n            <canvas id="chart-top-events"></canvas>\n        </div>\n    </section>\n</div>\n\n{# ===================== Lists ===================== #}\n<div class="grid lg:grid-cols-2 gap-4">\n\n    <section class="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">\n        <header class="px-4 py-3 border-b flex items-center justify-between">\n            <h2 class="font-semibold">Recent applications</h2>\n            <a href="{{ url_for(\'admin.applications\') }}" class="text-xs text-brand-600 hover:underline">\n                See all &rarr;\n            </a>\n        </header>\n        {% if recent_apps %}\n            <ul class="divide-y divide-slate-100">\n                {% for a in recent_apps %}\n                    <li>\n                        <a href="{{ url_for(\'admin.review\', app_id=a.id) }}"\n                           class="flex items-start gap-3 px-4 py-3 hover:bg-slate-50">\n                            <span class="w-9 h-9 rounded-full bg-brand-50 text-brand-600 flex items-center justify-center shrink-0">\n                                <i class="fa-solid fa-file-lines"></i>\n                            </span>\n                            <div class="flex-1 min-w-0">\n                                <div class="flex items-center gap-2 flex-wrap">\n                                    <p class="font-medium text-sm truncate">\n                                        {{ a.student.full_name if a.student else \'—\' }}\n                                    </p>\n                                    <span class="text-[10px] uppercase tracking-wide px-2 py-0.5 rounded {{ status_styles.get(a.status, \'bg-slate-100 text-slate-700\') }}">\n                                        {{ a.status }}\n                                    </span>\n                                </div>\n                                <p class="text-[11px] text-slate-500 truncate">\n                                    {{ a.registration.title if a.registration else \'No registration\' }}\n                                    <span class="text-slate-300">·</span>\n                                    {{ a.created_at | ph_date }}\n                                </p>\n                            </div>\n                            <i class="fa-solid fa-chevron-right text-slate-300 mt-1 text-xs"></i>\n                        </a>\n                    </li>\n                {% endfor %}\n            </ul>\n        {% else %}\n            <p class="px-4 py-8 text-center text-sm text-slate-500">No submissions yet.</p>\n        {% endif %}\n    </section>\n\n    <section class="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">\n        <header class="px-4 py-3 border-b flex items-center justify-between">\n            <h2 class="font-semibold">Upcoming &amp; open events</h2>\n            <a href="{{ url_for(\'admin.announcements\') }}" class="text-xs text-brand-600 hover:underline">\n                Manage &rarr;\n            </a>\n        </header>\n        {% if upcoming_events %}\n            <ul class="divide-y divide-slate-100">\n                {% for e in upcoming_events %}\n                    <li>\n                        <a href="{{ url_for(\'admin.announcement_joiners\', anc_id=e.id) }}"\n                           class="block px-4 py-3 hover:bg-slate-50">\n                            <div class="flex items-center gap-2 flex-wrap mb-0.5">\n                                <span class="text-[10px] uppercase px-2 py-0.5 rounded\n                                             {% if e.category == \'general_orientation\' %}bg-purple-50 text-purple-700\n                                             {% else %}bg-blue-50 text-blue-700{% endif %}">\n                                    {% if e.category == \'general_orientation\' %}General Orientation{% else %}Pay-out{% endif %}\n                                </span>\n                                <span class="text-[10px] uppercase px-2 py-0.5 rounded {{ status_styles.get(e.status, \'bg-slate-100 text-slate-700\') }}">\n                                    {{ e.status }}\n                                </span>\n                            </div>\n                            <p class="font-medium text-sm truncate">{{ e.title }}</p>\n                            {% if e.start_at and e.end_at %}\n                                <p class="text-[11px] text-slate-500">\n                                    <i class="fa-regular fa-calendar mr-1"></i>\n                                    {{ e.start_at | ph }} → {{ e.end_at | ph }}\n                                </p>\n                            {% endif %}\n                        </a>\n                    </li>\n                {% endfor %}\n            </ul>\n        {% else %}\n            <p class="px-4 py-8 text-center text-sm text-slate-500">No upcoming events.</p>\n        {% endif %}\n    </section>\n</div>\n\n<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js"></script>\n<script>\n(function () {\n    if (typeof Chart === \'undefined\') return;\n\n    const palette = {\n        brand:  \'#6f9d63\',\n        green:  \'#22c55e\',\n        amber:  \'#f59e0b\',\n        red:    \'#ef4444\',\n        blue:   \'#3b82f6\',\n        purple: \'#8b5cf6\',\n        slate:  \'#94a3b8\',\n    };\n\n    Chart.defaults.font.family = \'Poppins, system-ui, sans-serif\';\n    Chart.defaults.color = \'#475569\';\n    Chart.defaults.plugins.legend.labels.boxWidth = 12;\n\n    // ---------- 14-day submissions trend ----------\n    const trendCtx = document.getElementById(\'chart-trend\');\n    if (trendCtx) {\n        new Chart(trendCtx, {\n            type: \'line\',\n            data: {\n                labels: {{ trend_chart.categories | tojson }},\n                datasets: [{\n                    label: \'Submissions\',\n                    data: {{ trend_chart.series | tojson }},\n                    borderColor: palette.brand,\n                    backgroundColor: \'rgba(111, 157, 99, 0.18)\',\n                    borderWidth: 2,\n                    tension: 0.35,\n                    fill: true,\n                    pointRadius: 3,\n                    pointBackgroundColor: palette.brand,\n                }],\n            },\n            options: {\n                responsive: true,\n                maintainAspectRatio: false,\n                plugins: { legend: { display: false } },\n                scales: {\n                    y: { beginAtZero: true, ticks: { precision: 0 } },\n                    x: { grid: { display: false } },\n                },\n            },\n        });\n    }\n\n    // ---------- Application status doughnut ----------\n    const statusCtx = document.getElementById(\'chart-status\');\n    if (statusCtx) {\n        new Chart(statusCtx, {\n            type: \'doughnut\',\n            data: {\n                labels: {{ status_chart.categories | tojson }},\n                datasets: [{\n                    data: {{ status_chart.series | tojson }},\n                    backgroundColor: [palette.amber, palette.green, palette.red],\n                    borderWidth: 0,\n                }],\n            },\n            options: {\n                responsive: true,\n                maintainAspectRatio: false,\n                cutout: \'62%\',\n                plugins: {\n                    legend: { position: \'bottom\' },\n                },\n            },\n        });\n    }\n\n    // ---------- Education level bar ----------\n    const levelCtx = document.getElementById(\'chart-level\');\n    if (levelCtx) {\n        new Chart(levelCtx, {\n            type: \'bar\',\n            data: {\n                labels: {{ level_chart.categories | tojson }},\n                datasets: [{\n                    label: \'Applications\',\n                    data: {{ level_chart.series | tojson }},\n                    backgroundColor: palette.brand,\n                    borderRadius: 4,\n                }],\n            },\n            options: {\n                responsive: true,\n                maintainAspectRatio: false,\n                plugins: { legend: { display: false } },\n                scales: {\n                    y: { beginAtZero: true, ticks: { precision: 0 } },\n                    x: { grid: { display: false } },\n                },\n            },\n        });\n    }\n\n    // ---------- Year level bar ----------\n    const yearCtx = document.getElementById(\'chart-year\');\n    if (yearCtx) {\n        new Chart(yearCtx, {\n            type: \'bar\',\n            data: {\n                labels: {{ year_chart.categories | tojson }},\n                datasets: [{\n                    label: \'Applications\',\n                    data: {{ year_chart.series | tojson }},\n                    backgroundColor: palette.blue,\n                    borderRadius: 4,\n                }],\n            },\n            options: {\n                responsive: true,\n                maintainAspectRatio: false,\n                plugins: { legend: { display: false } },\n                scales: {\n                    y: { beginAtZero: true, ticks: { precision: 0 } },\n                    x: { grid: { display: false } },\n                },\n            },\n        });\n    }\n\n    // ---------- Event category pie ----------\n    const catCtx = document.getElementById(\'chart-category\');\n    if (catCtx) {\n        new Chart(catCtx, {\n            type: \'pie\',\n            data: {\n                labels: {{ category_chart.categories | tojson }},\n                datasets: [{\n                    data: {{ category_chart.series | tojson }},\n                    backgroundColor: [palette.brand, palette.blue, palette.purple, palette.slate, palette.amber],\n                    borderWidth: 0,\n                }],\n            },\n            options: {\n                responsive: true,\n                maintainAspectRatio: false,\n                plugins: {\n                    legend: { position: \'bottom\' },\n                },\n            },\n        });\n    }\n\n    // ---------- Top events horizontal bar ----------\n    const topCtx = document.getElementById(\'chart-top-events\');\n    if (topCtx) {\n        new Chart(topCtx, {\n            type: \'bar\',\n            data: {\n                labels: {{ top_events_chart.categories | tojson }},\n                datasets: [{\n                    label: \'Joiners\',\n                    data: {{ top_events_chart.series | tojson }},\n                    backgroundColor: palette.purple,\n                    borderRadius: 4,\n                }],\n            },\n            options: {\n                indexAxis: \'y\',\n                responsive: true,\n                maintainAspectRatio: false,\n                plugins: { legend: { display: false } },\n                scales: {\n                    x: { beginAtZero: true, ticks: { precision: 0 } },\n                    y: { grid: { display: false } },\n                },\n            },\n        });\n    }\n})();\n</script>\n{% endblock %}\n',
    'admin/general_announcements.html': '{% extends "admin/_layout.html" %}\n{% block title %}Announcements · Admin{% endblock %}\n\n{% block admin_content %}\n<div class="flex items-center justify-between flex-wrap gap-3 mb-4">\n    <div>\n        <h1 class="text-2xl font-bold text-brand-700">Announcements</h1>\n        <p class="text-sm text-slate-500">\n            {{ announcements|length }} published\n        </p>\n    </div>\n    <button type="button" data-announce-open\n            class="inline-flex items-center gap-2 px-4 py-2 rounded-md bg-brand-500 hover:bg-brand-600 text-white text-sm font-medium">\n        <i class="fa-solid fa-plus"></i>\n        Create announcement\n    </button>\n</div>\n\n{% if announcements %}\n    <div class="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">\n        <div class="px-3 py-3 border-b flex items-center gap-2 flex-wrap">\n            <div class="relative w-full sm:w-80">\n                <i class="fa-solid fa-magnifying-glass absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-xs"></i>\n                <input type="search" id="general-anc-search" placeholder="Hanapin sa title o body"\n                       class="w-full pl-8 pr-3 py-1.5 rounded-md border border-slate-300 text-sm focus:outline-none focus:ring-2 focus:ring-brand-400" />\n            </div>\n            <button type="button" data-search-btn="#general-anc-search"\n                    class="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-md bg-brand-500 hover:bg-brand-600 text-white text-sm font-medium whitespace-nowrap">\n                <i class="fa-solid fa-magnifying-glass text-xs"></i>\n                Search\n            </button>\n        </div>\n        <div class="space-y-3 p-3 max-h-[40rem] overflow-y-auto"\n             data-paginate data-page-size="15"\n             data-paginate-search="#general-anc-search"\n             data-pagination-into="#general-anc-pagination">\n            {% for a in announcements %}\n                <article id="anc-{{ a.id }}" data-page-item class="bg-white rounded-lg shadow-sm p-4 border border-slate-100 scroll-mt-24">\n                    <div class="flex items-start justify-between gap-3 flex-wrap">\n                        <div class="min-w-0">\n                            <div class="flex items-center gap-2 flex-wrap mb-1">\n                                <span class="text-xs px-2 py-0.5 rounded bg-slate-100 text-slate-700">\n                                    General\n                                </span>\n                                {% if not a.is_visible %}\n                                    <span class="text-xs uppercase px-2 py-0.5 rounded bg-slate-200 text-slate-600">\n                                        Expired\n                                    </span>\n                                {% endif %}\n                            </div>\n                            <h3 class="font-semibold">{{ a.title }}</h3>\n                        </div>\n                        <time class="text-xs text-slate-500 whitespace-nowrap">{{ a.created_at | ph_date }}</time>\n                    </div>\n\n                    {% if a.end_at %}\n                        <p class="text-xs text-slate-500 mt-1">\n                            <i class="fa-regular fa-clock mr-1"></i>\n                            Display until {{ a.end_at | ph }}\n                        </p>\n                    {% else %}\n                        <p class="text-xs text-slate-500 mt-1">\n                            <i class="fa-regular fa-clock mr-1"></i>\n                            No expiry — stays visible\n                        </p>\n                    {% endif %}\n\n                    <p class="text-[11px] text-slate-500 mt-1 flex items-center gap-1.5 flex-wrap">\n                        <span class="uppercase tracking-wide">Channels:</span>\n                        {% if a.notify_landing %}\n                            <span class="inline-flex items-center gap-1 px-1.5 py-0.5 rounded bg-brand-50 text-brand-700"><i class="fa-solid fa-globe text-[10px]"></i> Landing</span>\n                        {% endif %}\n                        {% if a.notify_inapp %}\n                            <span class="inline-flex items-center gap-1 px-1.5 py-0.5 rounded bg-blue-50 text-blue-700"><i class="fa-solid fa-bell text-[10px]"></i> In-app</span>\n                        {% endif %}\n                        {% if a.notify_email %}\n                            <span class="inline-flex items-center gap-1 px-1.5 py-0.5 rounded bg-purple-50 text-purple-700"><i class="fa-solid fa-envelope text-[10px]"></i> Email</span>\n                        {% endif %}\n                        {% if not (a.notify_landing or a.notify_inapp or a.notify_email) %}\n                            <span class="text-slate-400">none</span>\n                        {% endif %}\n                    </p>\n\n                    <p class="mt-2 text-sm text-slate-700 whitespace-pre-line">{{ a.body }}</p>\n\n                    <div class="mt-3 flex items-center gap-3 flex-wrap">\n                        <form method="post"\n                              action="{{ url_for(\'admin.delete_general_announcement\', anc_id=a.id) }}"\n                              onsubmit="return confirm(\'Delete this announcement?\');"\n                              class="ml-auto">\n                            <button type="submit" class="text-xs text-red-600 hover:underline">\n                                <i class="fa-solid fa-trash mr-1"></i>Delete\n                            </button>\n                        </form>\n                    </div>\n                </article>\n            {% endfor %}\n        </div>\n        <div id="general-anc-pagination"></div>\n    </div>\n{% else %}\n    <div class="bg-white rounded-xl shadow-sm border border-slate-100 p-10 text-center">\n        <i class="fa-solid fa-bullhorn text-4xl text-slate-300 mb-3"></i>\n        <p class="text-slate-500 text-sm">No announcements yet. Click <span class="font-medium text-brand-600">Create announcement</span> above to publish your first.</p>\n    </div>\n{% endif %}\n\n{# ===== Create announcement modal ===== #}\n<div id="announce-modal"\n     class="hidden fixed inset-0 z-[60] flex items-center justify-center p-4"\n     role="dialog" aria-modal="true" aria-labelledby="announce-title">\n    <div class="absolute inset-0 bg-slate-900/60" data-announce-close></div>\n    <div class="relative bg-white rounded-xl shadow-xl w-full max-w-lg max-h-[90vh] flex flex-col overflow-hidden">\n        <div class="flex items-center justify-between px-5 py-3 border-b">\n            <h2 id="announce-title" class="text-lg font-bold text-brand-700">Post announcement</h2>\n            <button type="button" data-announce-close\n                    class="text-slate-400 hover:text-slate-600" aria-label="Close">\n                <i class="fa-solid fa-xmark text-lg"></i>\n            </button>\n        </div>\n        <form method="post" class="flex-1 overflow-y-auto px-5 py-4 space-y-3" id="announce-form">\n            <div>\n                <label class="block text-sm font-medium mb-1">Title</label>\n                <input name="title" required\n                       class="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-400" />\n            </div>\n            <div>\n                <label class="block text-sm font-medium mb-1">Body</label>\n                <textarea name="body" rows="5" required\n                          class="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-400"></textarea>\n            </div>\n\n            <div>\n                <label class="block text-sm font-medium mb-1">Display until <span class="text-slate-400 font-normal">(optional)</span></label>\n                <input type="datetime-local" name="display_until"\n                       class="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-400" />\n                <p class="text-xs text-slate-500 mt-1">\n                    Pag walang inilagay, mananatili ang post hanggang manu-manong tanggalin.\n                </p>\n            </div>\n\n            <fieldset class="border border-slate-200 rounded-md p-3 pt-2">\n                <legend class="px-1 text-xs font-semibold text-slate-600 uppercase tracking-wide">\n                    Where should this announcement appear?\n                </legend>\n                <p class="text-xs text-slate-500 mb-2">\n                    Pumili ng kahit isa. Default: lahat.\n                </p>\n                <label class="flex items-start gap-2 text-sm py-1 cursor-pointer">\n                    <input type="checkbox" name="notify_landing" value="1" checked\n                           class="mt-1 h-4 w-4 rounded border-slate-300 text-brand-600 focus:ring-brand-400" />\n                    <span>\n                        <span class="font-medium">Public landing page</span>\n                        <span class="block text-xs text-slate-500">Lalabas sa /home, kahit hindi naka-log in.</span>\n                    </span>\n                </label>\n                <label class="flex items-start gap-2 text-sm py-1 cursor-pointer">\n                    <input type="checkbox" name="notify_inapp" value="1" checked\n                           class="mt-1 h-4 w-4 rounded border-slate-300 text-brand-600 focus:ring-brand-400" />\n                    <span>\n                        <span class="font-medium">In-app notifications</span>\n                        <span class="block text-xs text-slate-500">Lalabas sa bell icon ng student at admin.</span>\n                    </span>\n                </label>\n                <label class="flex items-start gap-2 text-sm py-1 cursor-pointer">\n                    <input type="checkbox" name="notify_email" value="1" checked\n                           class="mt-1 h-4 w-4 rounded border-slate-300 text-brand-600 focus:ring-brand-400" />\n                    <span>\n                        <span class="font-medium">Email blast</span>\n                        <span class="block text-xs text-slate-500">Ipapadala sa email ng lahat ng active students.</span>\n                    </span>\n                </label>\n            </fieldset>\n\n            <div class="pt-2 flex gap-2 justify-end">\n                <button type="button" data-announce-close\n                        class="px-4 py-2 rounded-md border border-slate-300 text-slate-700 hover:bg-slate-50 text-sm">\n                    Cancel\n                </button>\n                <button type="submit"\n                        class="px-4 py-2 rounded-md bg-brand-500 hover:bg-brand-600 text-white text-sm font-medium">\n                    <i class="fa-solid fa-paper-plane mr-1"></i>\n                    Publish\n                </button>\n            </div>\n        </form>\n    </div>\n</div>\n\n<script>\n(function () {\n    const modal = document.getElementById(\'announce-modal\');\n    if (!modal) return;\n    function open()  { modal.classList.remove(\'hidden\'); document.body.classList.add(\'overflow-hidden\'); }\n    function close() { modal.classList.add(\'hidden\');    document.body.classList.remove(\'overflow-hidden\'); }\n    document.addEventListener(\'click\', function (e) {\n        if (e.target.closest(\'[data-announce-open]\'))  { e.preventDefault(); open();  return; }\n        if (e.target.closest(\'[data-announce-close]\')) { close(); return; }\n    });\n    document.addEventListener(\'keydown\', function (e) {\n        if (e.key === \'Escape\' && !modal.classList.contains(\'hidden\')) close();\n    });\n    {% if request.method == \'POST\' %}open();{% endif %}\n})();\n</script>\n{% endblock %}\n',
    'admin/monitoring.html': '{% extends "admin/_layout.html" %}\n{% block title %}Monitoring · Admin{% endblock %}\n\n{% set status_styles = {\n    \'open\':        \'bg-green-100 text-green-800\',\n    \'upcoming\':    \'bg-amber-100 text-amber-800\',\n    \'closed\':      \'bg-slate-200 text-slate-700\',\n    \'unscheduled\': \'bg-slate-100 text-slate-600\',\n} %}\n{% set category_styles = {\n    \'payout\':      \'bg-blue-50 text-blue-700\',\n    \'general_orientation\': \'bg-purple-50 text-purple-700\',\n} %}\n{% set category_labels = {\n    \'payout\':      \'Pay-out\',\n    \'general_orientation\': \'General Orientation\',\n} %}\n\n{% macro stat_card(label, value, icon, tone=\'brand\') %}\n    {% set tone_styles = {\n        \'brand\':  \'bg-brand-50 text-brand-700\',\n        \'blue\':   \'bg-blue-50 text-blue-700\',\n        \'green\':  \'bg-green-50 text-green-700\',\n        \'purple\': \'bg-purple-50 text-purple-700\',\n        \'slate\':  \'bg-slate-100 text-slate-700\',\n    } %}\n    <div class="bg-white rounded-xl shadow-sm border border-slate-100 p-4 flex items-center gap-3">\n        <span class="w-10 h-10 rounded-md flex items-center justify-center {{ tone_styles.get(tone, tone_styles[\'brand\']) }}">\n            <i class="fa-solid {{ icon }}"></i>\n        </span>\n        <div>\n            <p class="text-xs uppercase tracking-wide text-slate-500">{{ label }}</p>\n            <p class="text-2xl font-bold leading-tight">{{ value }}</p>\n        </div>\n    </div>\n{% endmacro %}\n\n{% macro breakdown_list(rows, total) %}\n    {% if rows %}\n        <ul class="space-y-2">\n            {% for r in rows %}\n                {% set pct = (r.count * 100 / total) if total else 0 %}\n                <li>\n                    <div class="flex items-center justify-between text-sm mb-1">\n                        <span class="text-slate-700">{{ r.label }}</span>\n                        <span class="font-semibold">\n                            {{ r.count }}\n                            <span class="text-xs text-slate-400 font-normal">({{ \'%.0f\' % pct }}%)</span>\n                        </span>\n                    </div>\n                    <div class="h-1.5 rounded bg-slate-100 overflow-hidden">\n                        <div class="h-full bg-brand-400" style="width: {{ pct }}%;"></div>\n                    </div>\n                </li>\n            {% endfor %}\n        </ul>\n    {% else %}\n        <p class="text-sm text-slate-500">No data yet.</p>\n    {% endif %}\n{% endmacro %}\n\n{% block admin_content %}\n<div class="mb-5">\n    <h1 class="text-2xl font-bold text-brand-700">Monitoring</h1>\n    <p class="text-sm text-slate-500">Verified scholars per registration window and joiners of every event.</p>\n</div>\n\n{# ---------- Tab switcher ---------- #}\n<div class="flex gap-2 mb-5 border-b border-slate-200" role="tablist">\n    <button type="button" data-tab-btn data-target="tab-scholars"\n            class="px-4 py-2 text-sm font-medium text-brand-700 border-b-2 border-brand-500 -mb-px">\n        <i class="fa-solid fa-graduation-cap mr-1"></i>\n        Verified scholars\n    </button>\n    <button type="button" data-tab-btn data-target="tab-events"\n            class="px-4 py-2 text-sm font-medium text-slate-500 hover:text-slate-700 border-b-2 border-transparent -mb-px">\n        <i class="fa-solid fa-people-group mr-1"></i>\n        Event joiners\n    </button>\n</div>\n\n{# ===================== Verified scholars tab ===================== #}\n<section data-tab-panel id="tab-scholars" class="space-y-5">\n\n    <div class="grid sm:grid-cols-3 gap-4">\n        {{ stat_card(\'Verified scholars\', verified_total, \'fa-circle-check\', \'green\') }}\n        {{ stat_card(\'Unique students\', verified_unique_students, \'fa-user-graduate\', \'brand\') }}\n        {{ stat_card(\'Registration windows\', registration_count, \'fa-clipboard-list\', \'blue\') }}\n    </div>\n\n    <div class="grid lg:grid-cols-2 gap-4">\n        <div class="bg-white rounded-xl shadow-sm border border-slate-100 p-5">\n            <h2 class="font-semibold mb-3">By education level</h2>\n            {{ breakdown_list(level_breakdown, verified_total) }}\n        </div>\n        <div class="bg-white rounded-xl shadow-sm border border-slate-100 p-5">\n            <h2 class="font-semibold mb-3">By year level</h2>\n            {{ breakdown_list(year_breakdown, verified_total) }}\n        </div>\n    </div>\n\n    {# ---- Search bar ---- #}\n    <form method="get" class="bg-white rounded-xl shadow-sm border border-slate-100 p-3 sm:p-4 flex items-center gap-2 sm:gap-3 flex-wrap">\n        <div class="flex-1 min-w-0 relative">\n            <i class="fa-solid fa-magnifying-glass absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-sm"></i>\n            <input type="search" name="q" value="{{ q_scholars }}"\n                   placeholder="Search a scholar by name, level, or year"\n                   class="w-full pl-9 pr-3 py-2 rounded-md border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-brand-400" />\n        </div>\n        {# Preserve the joiners filter when scholars search is submitted. #}\n        {% if q_joiners %}\n            <input type="hidden" name="qj" value="{{ q_joiners }}" />\n        {% endif %}\n        <button type="submit"\n                class="px-4 py-2 rounded-md bg-brand-500 hover:bg-brand-600 text-white text-sm font-medium">\n            Search\n        </button>\n        {% if q_scholars %}\n            <a href="{{ url_for(\'admin.monitoring\', qj=q_joiners) if q_joiners else url_for(\'admin.monitoring\') }}"\n               class="text-xs text-slate-500 hover:underline">Clear</a>\n        {% endif %}\n    </form>\n\n    {# ---- Per-registration groups ---- #}\n    {% if scholar_groups %}\n        <div class="space-y-4">\n            {% for g in scholar_groups %}\n                {% set shown = g[\'items\'] | length %}\n                <section class="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">\n                    <header class="px-4 sm:px-5 py-3 border-b flex items-start justify-between gap-3 flex-wrap">\n                        <div class="min-w-0">\n                            <h3 class="font-semibold text-slate-800 truncate">\n                                <i class="fa-solid fa-clipboard-list text-brand-500 mr-1"></i>\n                                {{ g[\'title\'] }}\n                            </h3>\n                            {% if g[\'start_at\'] and g[\'end_at\'] %}\n                                <p class="text-[11px] sm:text-xs text-slate-500 mt-0.5">\n                                    <i class="fa-regular fa-calendar mr-1"></i>\n                                    {{ g[\'start_at\'] | ph }} → {{ g[\'end_at\'] | ph }}\n                                </p>\n                            {% endif %}\n                        </div>\n                        <div class="text-right">\n                            <p class="text-2xl font-bold leading-tight text-brand-700">{{ g[\'total\'] }}</p>\n                            <p class="text-[10px] uppercase tracking-wide text-slate-400">verified</p>\n                            {% if q_scholars and shown != g[\'total\'] %}\n                                <p class="text-[11px] text-slate-500">\n                                    Showing {{ shown }} match{{ \'\' if shown == 1 else \'es\' }}\n                                </p>\n                            {% endif %}\n                        </div>\n                    </header>\n\n                    {% if g[\'items\'] %}\n                        <div class="overflow-x-auto">\n                            <table class="w-full text-sm">\n                                <thead class="bg-slate-50 text-slate-600 text-left">\n                                    <tr>\n                                        <th class="px-4 sm:px-5 py-2">Student</th>\n                                        <th class="px-4 sm:px-5 py-2">Level</th>\n                                        <th class="px-4 sm:px-5 py-2">Year</th>\n                                        <th class="px-4 sm:px-5 py-2">Verified on</th>\n                                        <th class="px-4 sm:px-5 py-2"></th>\n                                    </tr>\n                                </thead>\n                                <tbody class="divide-y divide-slate-100"\n                                       data-paginate data-page-size="15"\n                                       data-pagination-into="#scholars-pagination-{{ loop.index }}">\n                                    {% for v in g[\'items\'] %}\n                                        <tr data-page-item>\n                                            <td class="px-4 sm:px-5 py-2">{{ v.student.full_name if v.student else \'—\' }}</td>\n                                            <td class="px-4 sm:px-5 py-2 text-slate-600">{{ v.level_label }}</td>\n                                            <td class="px-4 sm:px-5 py-2 text-slate-600">{{ v.year_label }}</td>\n                                            <td class="px-4 sm:px-5 py-2 text-slate-500">\n                                                {% if v.reviewed_at %}\n                                                    {{ v.reviewed_at | ph }}\n                                                {% else %}—{% endif %}\n                                            </td>\n                                            <td class="px-4 sm:px-5 py-2 text-right">\n                                                <a href="{{ url_for(\'admin.review\', app_id=v.id) }}"\n                                                   class="text-brand-600 hover:underline text-sm">View</a>\n                                            </td>\n                                        </tr>\n                                    {% endfor %}\n                                </tbody>\n                            </table>\n                        </div>\n                        <div id="scholars-pagination-{{ loop.index }}"></div>\n                    {% else %}\n                        <p class="px-5 py-6 text-sm text-slate-500 text-center">\n                            {% if q_scholars %}\n                                No scholar in this window matches "{{ q_scholars }}".\n                            {% else %}\n                                No verified scholars in this window yet.\n                            {% endif %}\n                        </p>\n                    {% endif %}\n                </section>\n            {% endfor %}\n        </div>\n    {% else %}\n        <div class="bg-white rounded-xl shadow-sm border border-slate-100 p-10 text-center">\n            <i class="fa-solid fa-graduation-cap text-4xl text-slate-300 mb-3"></i>\n            <p class="text-slate-500 text-sm">No verified scholars yet.</p>\n        </div>\n    {% endif %}\n</section>\n\n{# ===================== Event joiners tab ===================== #}\n<section data-tab-panel id="tab-events" class="space-y-5 hidden">\n\n    <div class="grid sm:grid-cols-4 gap-4">\n        {{ stat_card(\'Total joiners\', total_joins, \'fa-handshake\', \'blue\') }}\n        {{ stat_card(\'Joinable events\', events_total, \'fa-bullhorn\', \'brand\') }}\n        {{ stat_card(\'Pay-outs\', payouts_count, \'fa-hand-holding-dollar\', \'blue\') }}\n        {{ stat_card(\'General Orientation\', orientation_count, \'fa-people-group\', \'purple\') }}\n    </div>\n\n    {# ---- Search bar ---- #}\n    <form method="get" class="bg-white rounded-xl shadow-sm border border-slate-100 p-3 sm:p-4 flex items-center gap-2 sm:gap-3 flex-wrap">\n        <div class="flex-1 min-w-0 relative">\n            <i class="fa-solid fa-magnifying-glass absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-sm"></i>\n            <input type="search" name="qj" value="{{ q_joiners }}"\n                   placeholder="Search a joiner by name"\n                   class="w-full pl-9 pr-3 py-2 rounded-md border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-brand-400" />\n        </div>\n        {# Preserve the scholars filter so switching tabs doesn\'t lose it. #}\n        {% if q_scholars %}\n            <input type="hidden" name="q" value="{{ q_scholars }}" />\n        {% endif %}\n        <button type="submit"\n                class="px-4 py-2 rounded-md bg-brand-500 hover:bg-brand-600 text-white text-sm font-medium">\n            Search\n        </button>\n        {% if q_joiners %}\n            <a href="{{ url_for(\'admin.monitoring\', q=q_scholars) if q_scholars else url_for(\'admin.monitoring\') }}#tab-events"\n               class="text-xs text-slate-500 hover:underline">Clear</a>\n        {% endif %}\n    </form>\n\n    {# ---- Per-event groups ---- #}\n    {% if event_groups %}\n        <div class="space-y-4">\n            {% for e in event_groups %}\n                {% set shown = e[\'joiners\'] | length %}\n                <section class="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">\n                    <header class="px-4 sm:px-5 py-3 border-b flex items-start justify-between gap-3 flex-wrap">\n                        <div class="min-w-0">\n                            <div class="flex items-center gap-2 flex-wrap mb-0.5">\n                                <span class="text-[10px] uppercase px-2 py-0.5 rounded {{ category_styles.get(e[\'category\'], \'bg-slate-100 text-slate-700\') }}">\n                                    {{ category_labels.get(e[\'category\'], \'Event\') }}\n                                </span>\n                                <span class="text-[10px] uppercase px-2 py-0.5 rounded {{ status_styles.get(e[\'status\'], \'bg-slate-100 text-slate-700\') }}">\n                                    {{ e[\'status\'] }}\n                                </span>\n                            </div>\n                            <h3 class="font-semibold text-slate-800 truncate">{{ e[\'title\'] }}</h3>\n                            {% if e[\'start_at\'] and e[\'end_at\'] %}\n                                <p class="text-[11px] sm:text-xs text-slate-500 mt-0.5">\n                                    <i class="fa-regular fa-calendar mr-1"></i>\n                                    {{ e[\'start_at\'] | ph }} → {{ e[\'end_at\'] | ph }}\n                                </p>\n                            {% endif %}\n                        </div>\n                        <div class="text-right">\n                            <p class="text-2xl font-bold leading-tight">{{ e[\'join_count\'] }}</p>\n                            <p class="text-[10px] uppercase tracking-wide text-slate-400">joined</p>\n                            {% if q_joiners and shown != e[\'join_count\'] %}\n                                <p class="text-[11px] text-slate-500">\n                                    Showing {{ shown }} match{{ \'\' if shown == 1 else \'es\' }}\n                                </p>\n                            {% endif %}\n                        </div>\n                    </header>\n\n                    {% if e[\'joiners\'] %}\n                        <div class="overflow-x-auto">\n                            <table class="w-full text-sm">\n                                <thead class="bg-slate-50 text-slate-600 text-left">\n                                    <tr>\n                                        <th class="px-4 sm:px-5 py-2">Student</th>\n                                        <th class="px-4 sm:px-5 py-2">Date of join</th>\n                                        <th class="px-4 sm:px-5 py-2">Signature</th>\n                                        <th class="px-4 sm:px-5 py-2 text-right">\n                                            <a href="{{ url_for(\'admin.announcement_joiners_pdf\', anc_id=e[\'id\']) }}"\n                                               class="text-xs text-brand-600 hover:underline mr-3">\n                                                <i class="fa-solid fa-file-pdf"></i> Export PDF\n                                            </a>\n                                            <a href="{{ url_for(\'admin.announcement_joiners\', anc_id=e[\'id\']) }}"\n                                               class="text-xs text-brand-600 hover:underline">View page &rarr;</a>\n                                        </th>\n                                    </tr>\n                                </thead>\n                                <tbody class="divide-y divide-slate-100"\n                                       data-paginate data-page-size="15"\n                                       data-pagination-into="#joiners-pagination-{{ loop.index }}">\n                                    {% for j in e[\'joiners\'] %}\n                                        <tr data-page-item>\n                                            <td class="px-4 sm:px-5 py-2 font-medium text-slate-800">\n                                                {{ j.student.full_name if j.student else \'—\' }}\n                                            </td>\n                                            <td class="px-4 sm:px-5 py-2 text-slate-500">\n                                                {% set when = j.signed_at or j.joined_at %}\n                                                {% if when %}{{ when | ph }}{% else %}—{% endif %}\n                                            </td>\n                                            <td class="px-4 sm:px-5 py-2">\n                                                {% if j.signature_data %}\n                                                    <img src="{{ j.signature_data }}" alt="Signature"\n                                                         class="h-10 w-auto bg-white border border-slate-200 rounded" />\n                                                {% else %}\n                                                    <span class="text-xs text-slate-400">—</span>\n                                                {% endif %}\n                                            </td>\n                                            <td></td>\n                                        </tr>\n                                    {% endfor %}\n                                </tbody>\n                            </table>\n                        </div>\n                        <div id="joiners-pagination-{{ loop.index }}"></div>\n                    {% else %}\n                        <p class="px-5 py-6 text-sm text-slate-500 text-center">\n                            {% if q_joiners %}\n                                No joiner in this event matches "{{ q_joiners }}".\n                            {% else %}\n                                No joiners yet.\n                            {% endif %}\n                        </p>\n                    {% endif %}\n                </section>\n            {% endfor %}\n        </div>\n    {% else %}\n        <div class="bg-white rounded-xl shadow-sm border border-slate-100 p-10 text-center">\n            <i class="fa-solid fa-people-group text-4xl text-slate-300 mb-3"></i>\n            <p class="text-slate-500 text-sm">No joinable events yet.</p>\n        </div>\n    {% endif %}\n</section>\n\n<script>\n(function () {\n    const buttons = document.querySelectorAll(\'[data-tab-btn]\');\n    const panels  = document.querySelectorAll(\'[data-tab-panel]\');\n    if (!buttons.length || !panels.length) return;\n\n    const ACTIVE = [\'text-brand-700\', \'border-brand-500\'];\n    const IDLE   = [\'text-slate-500\', \'hover:text-slate-700\', \'border-transparent\'];\n\n    function activate(target) {\n        buttons.forEach(b => {\n            const on = b.dataset.target === target;\n            ACTIVE.forEach(c => b.classList.toggle(c, on));\n            IDLE.forEach(c   => b.classList.toggle(c, !on));\n        });\n        panels.forEach(p => p.classList.toggle(\'hidden\', p.id !== target));\n    }\n    buttons.forEach(b =>\n        b.addEventListener(\'click\', () => activate(b.dataset.target)));\n\n    // Honor a #tab-events anchor so links can deep-link directly there.\n    if (window.location.hash === \'#tab-events\') {\n        activate(\'tab-events\');\n    }\n})();\n</script>\n{% endblock %}\n',
    'admin/review.html': '{% extends "admin/_layout.html" %}\n{% block title %}Review · Admin{% endblock %}\n\n{% set status_styles = {\n    \'pending\':  \'bg-amber-100 text-amber-800\',\n    \'verified\': \'bg-green-100 text-green-800\',\n    \'rejected\': \'bg-red-100 text-red-800\',\n} %}\n\n{% set slot_labels = {\n    \'card\':      \'Report Card\',\n    \'cor\':       \'Certificate of Registration (COR)\',\n    \'id\':        \'Valid School ID\',\n    \'indigency\': \'Certificate of Indigency\',\n    \'psa\':       \'PSA Birth Certificate\',\n} %}\n\n{% block admin_content %}\n<a href="{{ url_for(\'admin.applications\') }}" class="text-sm text-brand-600 hover:underline">&larr; All applications</a>\n\n<div class="grid md:grid-cols-3 gap-6 mt-2">\n    <section class="md:col-span-2 bg-white rounded-xl shadow-sm p-6 border border-slate-100">\n        <div class="flex items-center justify-between flex-wrap gap-2">\n            <h1 class="text-2xl font-bold">\n                {{ app.student.full_name if app.student else \'Unknown student\' }}\n            </h1>\n            <span class="text-xs uppercase px-2 py-1 rounded {{ status_styles.get(app.status, \'bg-slate-100 text-slate-700\') }}">\n                {{ app.status }}\n            </span>\n        </div>\n        <p class="text-sm text-slate-500 mt-1">Submitted {{ app.created_at | ph_date }}</p>\n\n        {# ===== Applicant details ===== #}\n        <div class="mt-5 rounded-lg border border-slate-100 bg-slate-50/60 p-4">\n            <div class="flex items-center justify-between gap-2 flex-wrap mb-3">\n                <h2 class="font-semibold">Applicant details</h2>\n                {% if app.student and app.student.id %}\n                    <a href="{{ url_for(\'admin.user_detail\', student_id=app.student.id) }}"\n                       class="text-xs text-brand-600 hover:underline">\n                        View full profile <i class="fa-solid fa-arrow-right ml-0.5"></i>\n                    </a>\n                {% endif %}\n            </div>\n\n            <dl class="grid sm:grid-cols-2 gap-x-6 gap-y-3 text-sm">\n                <div>\n                    <dt class="text-xs font-medium text-slate-500">Full name</dt>\n                    <dd class="text-slate-800">{{ app.student.full_name if app.student else \'—\' }}</dd>\n                </div>\n                <div>\n                    <dt class="text-xs font-medium text-slate-500">Email</dt>\n                    <dd class="text-slate-800 break-all">{{ (app.student.email if app.student else \'\') or \'—\' }}</dd>\n                </div>\n                <div>\n                    <dt class="text-xs font-medium text-slate-500">Education level</dt>\n                    <dd class="text-slate-800">{{ app.level_label or \'—\' }}</dd>\n                </div>\n                <div>\n                    <dt class="text-xs font-medium text-slate-500">Grade / Year level</dt>\n                    <dd>\n                        <span class="inline-flex items-center gap-1 px-2 py-0.5 rounded bg-brand-50 text-brand-700 text-xs font-medium">\n                            <i class="fa-solid fa-graduation-cap"></i>\n                            {{ app.year_label or \'—\' }}\n                        </span>\n                    </dd>\n                </div>\n                <div>\n                    <dt class="text-xs font-medium text-slate-500">Facebook</dt>\n                    <dd class="text-slate-800 truncate">\n                        {% if app.student and app.student.facebook_url %}\n                            <a href="{{ app.student.facebook_url }}" target="_blank" rel="noopener"\n                               class="text-brand-700 hover:underline inline-flex items-center gap-1">\n                                <i class="fa-brands fa-facebook"></i>\n                                <span class="truncate">{{ app.student.facebook_url }}</span>\n                            </a>\n                        {% else %}—{% endif %}\n                    </dd>\n                </div>\n                <div>\n                    <dt class="text-xs font-medium text-slate-500">Joined</dt>\n                    <dd class="text-slate-800">\n                        {{ (app.student.created_at | ph_date) if app.student and app.student.created_at else \'—\' }}\n                    </dd>\n                </div>\n                {# Address — show as one readable line and break down per field. #}\n                {% set s = app.student or {} %}\n                {% set addr_parts = [\n                    s.address_house_no, s.address_street, s.address_purok,\n                    s.address_barangay, s.address_city, s.address_province, s.address_zip\n                ] | select | list %}\n                <div class="sm:col-span-2">\n                    <dt class="text-xs font-medium text-slate-500">Home address</dt>\n                    <dd class="text-slate-800">\n                        {% if addr_parts %}\n                            {{ addr_parts | join(\', \') }}\n                        {% else %}—{% endif %}\n                    </dd>\n                </div>\n                <div>\n                    <dt class="text-xs font-medium text-slate-500">House / Lot / Block</dt>\n                    <dd class="text-slate-800">{{ s.address_house_no or \'—\' }}</dd>\n                </div>\n                <div>\n                    <dt class="text-xs font-medium text-slate-500">Street</dt>\n                    <dd class="text-slate-800">{{ s.address_street or \'—\' }}</dd>\n                </div>\n                <div>\n                    <dt class="text-xs font-medium text-slate-500">Purok / Sitio</dt>\n                    <dd class="text-slate-800">{{ s.address_purok or \'—\' }}</dd>\n                </div>\n                <div>\n                    <dt class="text-xs font-medium text-slate-500">Barangay</dt>\n                    <dd class="text-slate-800">{{ s.address_barangay or \'—\' }}</dd>\n                </div>\n                <div>\n                    <dt class="text-xs font-medium text-slate-500">City / Municipality</dt>\n                    <dd class="text-slate-800">{{ s.address_city or \'—\' }}</dd>\n                </div>\n                <div>\n                    <dt class="text-xs font-medium text-slate-500">Province</dt>\n                    <dd class="text-slate-800">{{ s.address_province or \'—\' }}</dd>\n                </div>\n                <div>\n                    <dt class="text-xs font-medium text-slate-500">ZIP code</dt>\n                    <dd class="text-slate-800">{{ s.address_zip or \'—\' }}</dd>\n                </div>\n            </dl>\n        </div>\n\n        <div class="mt-5 flex items-center justify-between gap-2 flex-wrap">\n            <h2 class="font-semibold">Uploaded documents</h2>\n            {% if files %}\n                <a href="{{ url_for(\'admin.print_packet\', app_id=app.id) }}"\n                   target="_blank"\n                   class="inline-flex items-center gap-2 px-3 py-1.5 rounded-md bg-brand-500 hover:bg-brand-600 text-white text-sm font-medium">\n                    <i class="fa-solid fa-print"></i>\n                    Print all documents\n                </a>\n            {% endif %}\n        </div>\n\n        {% if files %}\n            <ul class="divide-y divide-slate-100 mt-2">\n                {% for f in files %}\n                    {% set is_image = (f.mime_type or \'\').startswith(\'image/\') %}\n                    <li class="py-2 flex items-center justify-between gap-3 text-sm">\n                        <div class="min-w-0 flex items-center gap-2">\n                            <i class="fa-solid {{ \'fa-image text-blue-500\' if is_image else \'fa-file-pdf text-red-500\' }}"></i>\n                            <div class="min-w-0">\n                                <p class="font-medium truncate">{{ slot_labels.get(f.slot, f.slot or \'Document\') }}</p>\n                                <p class="text-xs text-slate-500 truncate">{{ f.file_name }}</p>\n                            </div>\n                        </div>\n                        <button type="button"\n                                class="shrink-0 inline-flex items-center gap-1 px-2.5 py-1 rounded-md bg-brand-50 hover:bg-brand-100 text-brand-700 text-xs font-medium"\n                                data-doc-open\n                                data-doc-url="{{ url_for(\'admin.view_file\', app_id=app.id, file_id=f.id) }}"\n                                data-doc-kind="{{ \'image\' if is_image else \'pdf\' }}"\n                                data-doc-title="{{ slot_labels.get(f.slot, f.slot or \'Document\') }} — {{ f.file_name }}">\n                            <i class="fa-solid fa-eye"></i>\n                            View\n                        </button>\n                    </li>\n                {% endfor %}\n            </ul>\n        {% else %}\n            <p class="text-sm text-slate-500 mt-2">No documents uploaded.</p>\n        {% endif %}\n    </section>\n\n    <aside class="bg-white rounded-xl shadow-sm p-6 border border-slate-100 h-fit">\n        <h2 class="font-semibold mb-3">Decision</h2>\n        <form method="post" action="{{ url_for(\'admin.decide\', app_id=app.id) }}" class="space-y-3">\n            <textarea name="notes" rows="4"\n                      placeholder="Notes for the student (optional)"\n                      class="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-400">{{ app.notes or \'\' }}</textarea>\n            <div class="flex gap-2">\n                <button name="decision" value="verified"\n                        class="flex-1 bg-green-600 hover:bg-green-700 text-white text-sm py-2 rounded-md">\n                    <i class="fa-solid fa-check mr-1"></i> Verify\n                </button>\n                <button name="decision" value="rejected"\n                        class="flex-1 bg-red-600 hover:bg-red-700 text-white text-sm py-2 rounded-md">\n                    <i class="fa-solid fa-xmark mr-1"></i> Reject\n                </button>\n            </div>\n        </form>\n    </aside>\n</div>\n\n{# ===== Document preview modal ===== #}\n<div id="doc-modal"\n     class="hidden fixed inset-0 z-[70] flex items-center justify-center p-4"\n     role="dialog" aria-modal="true" aria-labelledby="doc-modal-title">\n    <div class="absolute inset-0 bg-slate-900/70" data-doc-close></div>\n    <div class="relative bg-white rounded-xl shadow-2xl w-full max-w-5xl h-[90vh] flex flex-col overflow-hidden">\n        <div class="flex items-center justify-between px-4 py-3 border-b">\n            <h2 id="doc-modal-title" class="text-sm font-semibold text-slate-700 truncate"></h2>\n            <div class="flex items-center gap-2">\n                <a id="doc-modal-newtab" href="#" target="_blank"\n                   class="text-xs text-brand-600 hover:underline">Open in new tab</a>\n                <button type="button" data-doc-close\n                        class="text-slate-400 hover:text-slate-600" aria-label="Close">\n                    <i class="fa-solid fa-xmark text-lg"></i>\n                </button>\n            </div>\n        </div>\n        <div class="flex-1 bg-slate-100 overflow-auto flex items-center justify-center">\n            <iframe id="doc-modal-iframe" class="hidden w-full h-full bg-white" src="about:blank"></iframe>\n            <img    id="doc-modal-image"  class="hidden max-w-full max-h-full object-contain" alt="" src="" />\n        </div>\n    </div>\n</div>\n\n<script>\n(function () {\n    const modal  = document.getElementById(\'doc-modal\');\n    const title  = document.getElementById(\'doc-modal-title\');\n    const iframe = document.getElementById(\'doc-modal-iframe\');\n    const image  = document.getElementById(\'doc-modal-image\');\n    const newtab = document.getElementById(\'doc-modal-newtab\');\n    if (!modal) return;\n\n    function open(url, kind, label) {\n        title.textContent = label || \'Document\';\n        newtab.href = url;\n        if (kind === \'image\') {\n            iframe.classList.add(\'hidden\');\n            iframe.src = \'about:blank\';\n            image.src  = url;\n            image.classList.remove(\'hidden\');\n        } else {\n            image.classList.add(\'hidden\');\n            image.src = \'\';\n            iframe.src = url;\n            iframe.classList.remove(\'hidden\');\n        }\n        modal.classList.remove(\'hidden\');\n    }\n    function close() {\n        modal.classList.add(\'hidden\');\n        iframe.src = \'about:blank\';\n        image.src  = \'\';\n    }\n\n    document.addEventListener(\'click\', function (e) {\n        const opener = e.target.closest(\'[data-doc-open]\');\n        if (opener) {\n            e.preventDefault();\n            open(opener.dataset.docUrl, opener.dataset.docKind, opener.dataset.docTitle);\n            return;\n        }\n        if (e.target.closest(\'[data-doc-close]\')) {\n            close();\n        }\n    });\n    document.addEventListener(\'keydown\', function (e) {\n        if (e.key === \'Escape\') close();\n    });\n})();\n</script>\n{% endblock %}\n',
    'admin/users.html': '{% extends "admin/_layout.html" %}\n{% block title %}User management · Admin{% endblock %}\n\n{% block admin_content %}\n<div class="flex items-center justify-between flex-wrap gap-3 mb-4">\n    <div>\n        <h1 class="text-2xl font-bold text-brand-700">User management</h1>\n        <p class="text-sm text-slate-500">Manage student accounts — view details, deactivate, or delete.</p>\n    </div>\n</div>\n\n{# Stat cards #}\n<div class="grid sm:grid-cols-3 gap-4 mb-6">\n    <div class="bg-white rounded-xl shadow-sm p-4 border border-slate-100">\n        <div class="text-xs uppercase tracking-wide text-slate-500">Total students</div>\n        <div class="text-3xl font-bold mt-1">{{ counts.total }}</div>\n    </div>\n    <div class="bg-white rounded-xl shadow-sm p-4 border border-slate-100">\n        <div class="text-xs uppercase tracking-wide text-slate-500">Active</div>\n        <div class="text-3xl font-bold mt-1 text-green-700">{{ counts.active }}</div>\n    </div>\n    <div class="bg-white rounded-xl shadow-sm p-4 border border-slate-100">\n        <div class="text-xs uppercase tracking-wide text-slate-500">Deactivated</div>\n        <div class="text-3xl font-bold mt-1 text-red-700">{{ counts.deactivated }}</div>\n    </div>\n</div>\n\n<section class="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">\n    <div class="px-5 py-3 border-b flex items-center justify-between gap-3 flex-wrap">\n        <span class="font-semibold">Students</span>\n        <form method="get" class="flex items-center gap-2">\n            <div class="relative">\n                <i class="fa-solid fa-magnifying-glass absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 text-xs"></i>\n                <input type="text" name="q" value="{{ query }}" placeholder="Search name or email"\n                       class="pl-8 pr-3 py-1.5 rounded-md border border-slate-300 text-sm focus:outline-none focus:ring-2 focus:ring-brand-400" />\n            </div>\n            {% if query %}\n                <a href="{{ url_for(\'admin.users\') }}" class="text-xs text-slate-500 hover:underline">Clear</a>\n            {% endif %}\n        </form>\n    </div>\n\n    {% if students %}\n        <div class="overflow-x-auto max-h-[40rem] overflow-y-auto">\n            <table class="w-full text-sm">\n                <thead class="bg-slate-50 text-slate-600 text-left sticky top-0 z-10">\n                    <tr>\n                        <th class="px-5 py-2">Student</th>\n                        <th class="px-5 py-2">Email</th>\n                        <th class="px-5 py-2">Applications</th>\n                        <th class="px-5 py-2">Joined</th>\n                        <th class="px-5 py-2">Status</th>\n                        <th class="px-5 py-2"></th>\n                    </tr>\n                </thead>\n                <tbody class="divide-y divide-slate-100"\n                       data-paginate data-page-size="15"\n                       data-pagination-into="#users-pagination">\n                    {% for s in students %}\n                        <tr data-page-item>\n                            <td class="px-5 py-2">\n                                <div class="flex items-center gap-2 min-w-0">\n                                    <span class="w-8 h-8 rounded-full bg-brand-100 text-brand-700 flex items-center justify-center text-xs font-bold shrink-0">\n                                        {{ (s.first_name or s.full_name or \'?\')[:1] | upper }}{{ (s.last_name or \'\')[:1] | upper }}\n                                    </span>\n                                    <span class="font-medium truncate">{{ s.full_name or \'—\' }}</span>\n                                </div>\n                            </td>\n                            <td class="px-5 py-2 text-slate-600 truncate">{{ s.email or \'—\' }}</td>\n                            <td class="px-5 py-2 text-slate-500">{{ s.app_count }}</td>\n                            <td class="px-5 py-2 text-slate-500">{{ s.created_at | ph_date }}</td>\n                            <td class="px-5 py-2">\n                                {% if s.is_active %}\n                                    <span class="text-xs uppercase px-2 py-1 rounded bg-green-100 text-green-800">Active</span>\n                                {% else %}\n                                    <span class="text-xs uppercase px-2 py-1 rounded bg-red-100 text-red-800">Deactivated</span>\n                                {% endif %}\n                                {% if not s.email_verified %}\n                                    <span class="text-xs uppercase px-2 py-1 rounded bg-amber-100 text-amber-800 ml-1">Unverified</span>\n                                {% endif %}\n                            </td>\n                            <td class="px-5 py-2 text-right whitespace-nowrap">\n                                <a href="{{ url_for(\'admin.user_detail\', student_id=s.id) }}"\n                                   class="text-brand-600 hover:underline">View</a>\n                            </td>\n                        </tr>\n                    {% endfor %}\n                </tbody>\n            </table>\n        </div>\n        <div id="users-pagination"></div>\n    {% else %}\n        <p class="px-5 py-6 text-slate-500 text-sm">\n            {% if query %}No students matched "{{ query }}".{% else %}No students yet.{% endif %}\n        </p>\n    {% endif %}\n</section>\n{% endblock %}\n',
    'admin/user_detail.html': '{% extends "admin/_layout.html" %}\n{% block title %}{{ student.full_name or \'Student\' }} · Admin{% endblock %}\n\n{% set status_styles = {\n    \'pending\':  \'bg-amber-100 text-amber-800\',\n    \'verified\': \'bg-green-100 text-green-800\',\n    \'rejected\': \'bg-red-100 text-red-800\',\n} %}\n\n{% block admin_content %}\n<a href="{{ url_for(\'admin.users\') }}" class="text-sm text-brand-600 hover:underline">&larr; All students</a>\n\n<div class="grid lg:grid-cols-3 gap-6 mt-2">\n\n    {# ----- Left: profile + actions ----- #}\n    <section class="lg:col-span-2 space-y-6">\n\n        {# Header card #}\n        <div class="bg-white rounded-xl shadow-sm border border-slate-100 p-6">\n            <div class="flex items-start gap-4 flex-wrap">\n                <div class="w-14 h-14 rounded-full bg-brand-100 text-brand-700 flex items-center justify-center text-xl font-bold">\n                    {{ (student.first_name or student.full_name or \'?\')[:1] | upper }}{{ (student.last_name or \'\')[:1] | upper }}\n                </div>\n                <div class="min-w-0 flex-1">\n                    <div class="flex items-center gap-2 flex-wrap">\n                        <h1 class="text-2xl font-bold truncate">{{ student.full_name or \'Student\' }}</h1>\n                        {% if student.is_active %}\n                            <span class="text-xs uppercase px-2 py-1 rounded bg-green-100 text-green-800">Active</span>\n                        {% else %}\n                            <span class="text-xs uppercase px-2 py-1 rounded bg-red-100 text-red-800">Deactivated</span>\n                        {% endif %}\n                        {% if not student.email_verified %}\n                            <span class="text-xs uppercase px-2 py-1 rounded bg-amber-100 text-amber-800">Email unverified</span>\n                        {% endif %}\n                    </div>\n                    <p class="text-sm text-slate-500 capitalize">{{ student.role or \'student\' }}</p>\n                    <p class="text-xs text-slate-400 mt-1">Joined {{ student.created_at | ph_date }}</p>\n                </div>\n            </div>\n        </div>\n\n        {# Personal info #}\n        <div class="bg-white rounded-xl shadow-sm border border-slate-100 p-6">\n            <header class="mb-4">\n                <h2 class="font-semibold text-lg">Personal information</h2>\n            </header>\n            <div class="grid sm:grid-cols-2 gap-4 text-sm">\n                <div>\n                    <label class="block text-xs font-medium text-slate-500 mb-1">First name</label>\n                    <input type="text" value="{{ student.first_name or \'—\' }}" readonly\n                           class="w-full rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-slate-700" />\n                </div>\n                <div>\n                    <label class="block text-xs font-medium text-slate-500 mb-1">Middle name</label>\n                    <input type="text" value="{{ student.middle_name or \'—\' }}" readonly\n                           class="w-full rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-slate-700" />\n                </div>\n                <div>\n                    <label class="block text-xs font-medium text-slate-500 mb-1">Last name</label>\n                    <input type="text" value="{{ student.last_name or \'—\' }}" readonly\n                           class="w-full rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-slate-700" />\n                </div>\n                <div>\n                    <label class="block text-xs font-medium text-slate-500 mb-1">Suffix</label>\n                    <input type="text" value="{{ student.suffix or \'—\' }}" readonly\n                           class="w-full rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-slate-700" />\n                </div>\n            </div>\n        </div>\n\n        {# Contact #}\n        <div class="bg-white rounded-xl shadow-sm border border-slate-100 p-6">\n            <header class="mb-4">\n                <h2 class="font-semibold text-lg">Contact</h2>\n            </header>\n            <div class="grid sm:grid-cols-2 gap-4 text-sm">\n                <div>\n                    <label class="block text-xs font-medium text-slate-500 mb-1">Email</label>\n                    <input type="text" value="{{ student.email or \'—\' }}" readonly\n                           class="w-full rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-slate-700" />\n                </div>\n                <div>\n                    <label class="block text-xs font-medium text-slate-500 mb-1">Facebook</label>\n                    {% if student.facebook_url %}\n                        <a href="{{ student.facebook_url }}" target="_blank" rel="noopener"\n                           class="inline-flex items-center gap-2 px-3 py-2 rounded-md border border-slate-200 bg-slate-50 text-brand-700 hover:underline w-full truncate">\n                            <i class="fa-brands fa-facebook"></i>\n                            <span class="truncate">{{ student.facebook_url }}</span>\n                        </a>\n                    {% else %}\n                        <input type="text" value="—" readonly\n                               class="w-full rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-slate-700" />\n                    {% endif %}\n                </div>\n            </div>\n        </div>\n\n        {# Address — captured at sign-up #}\n        <div class="bg-white rounded-xl shadow-sm border border-slate-100 p-6">\n            <header class="mb-4">\n                <h2 class="font-semibold text-lg">Home address</h2>\n            </header>\n            <div class="grid sm:grid-cols-3 gap-4 text-sm">\n                <div>\n                    <label class="block text-xs font-medium text-slate-500 mb-1">House / Lot / Block</label>\n                    <input type="text" value="{{ student.address_house_no or \'—\' }}" readonly\n                           class="w-full rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-slate-700" />\n                </div>\n                <div>\n                    <label class="block text-xs font-medium text-slate-500 mb-1">Street</label>\n                    <input type="text" value="{{ student.address_street or \'—\' }}" readonly\n                           class="w-full rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-slate-700" />\n                </div>\n                <div>\n                    <label class="block text-xs font-medium text-slate-500 mb-1">Purok / Sitio</label>\n                    <input type="text" value="{{ student.address_purok or \'—\' }}" readonly\n                           class="w-full rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-slate-700" />\n                </div>\n                <div>\n                    <label class="block text-xs font-medium text-slate-500 mb-1">Barangay</label>\n                    <input type="text" value="{{ student.address_barangay or \'—\' }}" readonly\n                           class="w-full rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-slate-700" />\n                </div>\n                <div>\n                    <label class="block text-xs font-medium text-slate-500 mb-1">City / Municipality</label>\n                    <input type="text" value="{{ student.address_city or \'—\' }}" readonly\n                           class="w-full rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-slate-700" />\n                </div>\n                <div>\n                    <label class="block text-xs font-medium text-slate-500 mb-1">Province</label>\n                    <input type="text" value="{{ student.address_province or \'—\' }}" readonly\n                           class="w-full rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-slate-700" />\n                </div>\n                <div>\n                    <label class="block text-xs font-medium text-slate-500 mb-1">ZIP code</label>\n                    <input type="text" value="{{ student.address_zip or \'—\' }}" readonly\n                           class="w-full rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-slate-700" />\n                </div>\n            </div>\n        </div>\n\n        {# Application history #}\n        <div class="bg-white rounded-xl shadow-sm border border-slate-100 p-6">\n            <header class="flex items-center justify-between gap-3 mb-4 flex-wrap">\n                <h2 class="font-semibold text-lg">Applications ({{ applications | length }})</h2>\n            </header>\n\n            {% if applications %}\n                <ul class="divide-y divide-slate-100">\n                    {% for a in applications %}\n                        <li class="py-3">\n                            <a href="{{ url_for(\'admin.review\', app_id=a.id) }}"\n                               class="flex items-start gap-3 hover:bg-slate-50 -mx-2 px-2 py-1 rounded-md">\n                                <span class="w-9 h-9 rounded-md bg-brand-50 text-brand-600 flex items-center justify-center shrink-0">\n                                    <i class="fa-solid fa-file-lines"></i>\n                                </span>\n                                <div class="flex-1 min-w-0">\n                                    <p class="font-medium text-sm truncate">\n                                        {{ a.registration.title if a.registration else \'Application\' }}\n                                    </p>\n                                    <p class="text-xs text-slate-500">\n                                        {{ a.level_label }} · {{ a.year_label }}\n                                        <span class="text-slate-300">·</span>\n                                        {{ a.created_at | ph_date }}\n                                    </p>\n                                </div>\n                                <span class="text-xs uppercase tracking-wide px-2 py-1 rounded shrink-0 {{ status_styles.get(a.status, \'bg-slate-100 text-slate-700\') }}">\n                                    {{ a.status }}\n                                </span>\n                            </a>\n                        </li>\n                    {% endfor %}\n                </ul>\n            {% else %}\n                <p class="text-sm text-slate-500">No applications yet.</p>\n            {% endif %}\n        </div>\n\n        {# Pay-out joins #}\n        <div class="bg-white rounded-xl shadow-sm border border-slate-100 p-6">\n            <header class="mb-4">\n                <h2 class="font-semibold text-lg">Pay-out joiners ({{ payout_joins | length }})</h2>\n            </header>\n            {% if payout_joins %}\n                <ul class="divide-y divide-slate-100">\n                    {% for j in payout_joins %}\n                        <li class="py-2 flex items-center gap-3 text-sm">\n                            <span class="w-9 h-9 rounded-md bg-blue-50 text-blue-600 flex items-center justify-center shrink-0">\n                                <i class="fa-solid fa-hand-holding-dollar"></i>\n                            </span>\n                            <div class="flex-1 min-w-0">\n                                <p class="font-medium truncate">\n                                    {{ j.announcement.title if j.announcement else \'Pay-out\' }}\n                                </p>\n                                <p class="text-xs text-slate-500">Joined {{ j.joined_at | ph }}</p>\n                            </div>\n                        </li>\n                    {% endfor %}\n                </ul>\n            {% else %}\n                <p class="text-sm text-slate-500">No pay-outs joined yet.</p>\n            {% endif %}\n        </div>\n    </section>\n\n    {# ----- Right: action panel ----- #}\n    <aside class="space-y-4">\n        <div class="bg-white rounded-xl shadow-sm border border-slate-100 p-6 lg:sticky lg:top-24">\n            <h2 class="font-semibold text-lg mb-2">Account actions</h2>\n            <p class="text-xs text-slate-500 mb-4">\n                Deactivating blocks login but keeps history. Deleting wipes everything — this cannot be undone.\n            </p>\n\n            <form method="post" action="{{ url_for(\'admin.user_set_status\', student_id=student.id) }}" class="mb-3">\n                {% if student.is_active %}\n                    <input type="hidden" name="action" value="deactivate" />\n                    <button type="submit"\n                            onclick="return confirm(\'Deactivate this account? They will not be able to log in until you activate it again.\');"\n                            class="w-full inline-flex items-center justify-center gap-2 px-4 py-2 rounded-md bg-amber-500 hover:bg-amber-600 text-white text-sm font-medium">\n                        <i class="fa-solid fa-user-slash"></i> Deactivate account\n                    </button>\n                {% else %}\n                    <input type="hidden" name="action" value="activate" />\n                    <button type="submit"\n                            class="w-full inline-flex items-center justify-center gap-2 px-4 py-2 rounded-md bg-green-600 hover:bg-green-700 text-white text-sm font-medium">\n                        <i class="fa-solid fa-user-check"></i> Activate account\n                    </button>\n                {% endif %}\n            </form>\n\n            <form method="post" action="{{ url_for(\'admin.user_delete\', student_id=student.id) }}"\n                  onsubmit="return confirm(\'Permanently delete {{ (student.full_name or \'this student\') | e }}? All applications and uploaded files will be lost. This cannot be undone.\');">\n                <button type="submit"\n                        class="w-full inline-flex items-center justify-center gap-2 px-4 py-2 rounded-md bg-red-600 hover:bg-red-700 text-white text-sm font-medium">\n                    <i class="fa-solid fa-trash"></i> Delete account\n                </button>\n            </form>\n        </div>\n    </aside>\n</div>\n{% endblock %}\n',
    'admin/_layout.html': '{% extends "base.html" %}\n\n{# Sidebar layout for admin pages.\n   Pages should override `admin_content` instead of `content`.\n   Desktop: persistent left sidebar.\n   Mobile : a hamburger button that opens a centered modal menu. #}\n\n{% block content %}\n<div class="md:grid md:grid-cols-[15rem_1fr] md:gap-6">\n\n    {# ----- Mobile top bar ----- #}\n    <div class="md:hidden flex items-center justify-between mb-3">\n        <button type="button" data-admin-menu-open\n                class="inline-flex items-center gap-2 px-3 py-1.5 rounded-md bg-white border border-slate-200 text-slate-700 text-sm">\n            <i class="fa-solid fa-bars"></i>\n            <span class="font-medium">Menu</span>\n        </button>\n        <span class="text-xs text-slate-500">Admin</span>\n    </div>\n\n    {# ----- Desktop sidebar ----- #}\n    <aside class="hidden md:block">\n        <div class="bg-white rounded-xl shadow-sm border border-slate-100 p-3 sticky top-24 max-h-[calc(100vh-7rem)] overflow-y-auto">\n            <span class="block text-xs uppercase tracking-wide text-slate-500 mb-2 px-1">Admin menu</span>\n\n            {% set nav_base = "flex items-center gap-3 px-3 py-2 rounded-md text-sm font-medium" %}\n            {% set nav_active = "bg-brand-50 text-brand-700" %}\n            {% set nav_idle = "text-slate-700 hover:bg-slate-100" %}\n\n            <nav class="space-y-1">\n                <a href="{{ url_for(\'admin.dashboard\') }}"\n                   class="{{ nav_base }} {% if request.endpoint == \'admin.dashboard\' %}{{ nav_active }}{% else %}{{ nav_idle }}{% endif %}">\n                    <i class="fa-solid fa-gauge-high w-5 text-center"></i>\n                    <span>Dashboard</span>\n                </a>\n                <a href="{{ url_for(\'admin.applications\') }}"\n                   class="{{ nav_base }} {% if request.endpoint in [\'admin.applications\', \'admin.review\'] %}{{ nav_active }}{% else %}{{ nav_idle }}{% endif %}">\n                    <i class="fa-solid fa-folder-open w-5 text-center"></i>\n                    <span>Applications</span>\n                </a>\n                <a href="{{ url_for(\'admin.monitoring\') }}"\n                   class="{{ nav_base }} {% if request.endpoint == \'admin.monitoring\' %}{{ nav_active }}{% else %}{{ nav_idle }}{% endif %}">\n                    <i class="fa-solid fa-chart-line w-5 text-center"></i>\n                    <span>Monitoring</span>\n                </a>\n                <a href="{{ url_for(\'admin.users\') }}"\n                   class="{{ nav_base }} {% if request.endpoint in [\'admin.users\', \'admin.user_detail\'] %}{{ nav_active }}{% else %}{{ nav_idle }}{% endif %}">\n                    <i class="fa-solid fa-user-gear w-5 text-center"></i>\n                    <span>User management</span>\n                </a>\n                <a href="{{ url_for(\'admin.announcements\') }}"\n                   class="{{ nav_base }} {% if request.endpoint in [\'admin.announcements\', \'admin.announcement_joiners\'] %}{{ nav_active }}{% else %}{{ nav_idle }}{% endif %}">\n                    <i class="fa-solid fa-bullhorn w-5 text-center"></i>\n                    <span>Events</span>\n                </a>\n                <a href="{{ url_for(\'admin.general_announcements\') }}"\n                   class="{{ nav_base }} {% if request.endpoint == \'admin.general_announcements\' %}{{ nav_active }}{% else %}{{ nav_idle }}{% endif %}">\n                    <i class="fa-regular fa-newspaper w-5 text-center"></i>\n                    <span>Announcements</span>\n                </a>\n                <a href="{{ url_for(\'admin.certificates\') }}"\n                   class="{{ nav_base }} {% if request.endpoint in [\'admin.certificates\', \'admin.certificate_preview\'] %}{{ nav_active }}{% else %}{{ nav_idle }}{% endif %}">\n                    <i class="fa-solid fa-certificate w-5 text-center"></i>\n                    <span>Certificates</span>\n                </a>\n                <a href="{{ url_for(\'public.home\') }}"\n                   class="{{ nav_base }} {{ nav_idle }}">\n                    <i class="fa-solid fa-house w-5 text-center"></i>\n                    <span>Public site</span>\n                </a>\n                <a href="{{ url_for(\'public.logout\') }}"\n                   class="{{ nav_base }} text-red-600 hover:bg-red-50">\n                    <i class="fa-solid fa-right-from-bracket w-5 text-center"></i>\n                    <span>Log out</span>\n                </a>\n            </nav>\n        </div>\n    </aside>\n\n    {# ----- Main content ----- #}\n    <div class="min-w-0">\n        {% block admin_content %}{% endblock %}\n    </div>\n</div>\n\n{# ----- Mobile menu modal ----- #}\n<div id="admin-menu-modal"\n     class="hidden fixed inset-0 z-[60] flex items-end sm:items-center justify-center md:hidden"\n     role="dialog" aria-modal="true" aria-labelledby="admin-menu-title">\n    <div class="absolute inset-0 bg-slate-900/50" data-admin-menu-close></div>\n    <div class="relative bg-white w-full sm:max-w-sm sm:mx-4 rounded-t-2xl sm:rounded-2xl shadow-2xl overflow-hidden">\n        <div class="flex items-center justify-between px-4 py-3 border-b">\n            <span id="admin-menu-title" class="text-xs uppercase tracking-wide text-slate-500">Admin menu</span>\n            <button type="button" data-admin-menu-close\n                    class="text-slate-400 hover:text-slate-600 p-1" aria-label="Close menu">\n                <i class="fa-solid fa-xmark"></i>\n            </button>\n        </div>\n\n        {% set m_base = "flex items-center gap-3 px-4 py-3 text-sm" %}\n        {% set m_active = "bg-brand-50 text-brand-700 font-semibold" %}\n        {% set m_idle = "text-slate-700 hover:bg-slate-50" %}\n\n        <nav class="divide-y divide-slate-100">\n            <a href="{{ url_for(\'admin.dashboard\') }}"\n               class="{{ m_base }} {% if request.endpoint == \'admin.dashboard\' %}{{ m_active }}{% else %}{{ m_idle }}{% endif %}">\n                <i class="fa-solid fa-gauge-high w-5 text-center"></i>\n                <span>Dashboard</span>\n            </a>\n            <a href="{{ url_for(\'admin.applications\') }}"\n               class="{{ m_base }} {% if request.endpoint in [\'admin.applications\', \'admin.review\'] %}{{ m_active }}{% else %}{{ m_idle }}{% endif %}">\n                <i class="fa-solid fa-folder-open w-5 text-center"></i>\n                <span>Applications</span>\n            </a>\n            <a href="{{ url_for(\'admin.monitoring\') }}"\n               class="{{ m_base }} {% if request.endpoint == \'admin.monitoring\' %}{{ m_active }}{% else %}{{ m_idle }}{% endif %}">\n                <i class="fa-solid fa-chart-line w-5 text-center"></i>\n                <span>Monitoring</span>\n            </a>\n            <a href="{{ url_for(\'admin.users\') }}"\n               class="{{ m_base }} {% if request.endpoint in [\'admin.users\', \'admin.user_detail\'] %}{{ m_active }}{% else %}{{ m_idle }}{% endif %}">\n                <i class="fa-solid fa-user-gear w-5 text-center"></i>\n                <span>User management</span>\n            </a>\n            <a href="{{ url_for(\'admin.announcements\') }}"\n               class="{{ m_base }} {% if request.endpoint in [\'admin.announcements\', \'admin.announcement_joiners\'] %}{{ m_active }}{% else %}{{ m_idle }}{% endif %}">\n                <i class="fa-solid fa-bullhorn w-5 text-center"></i>\n                <span>Events</span>\n            </a>\n            <a href="{{ url_for(\'admin.general_announcements\') }}"\n               class="{{ m_base }} {% if request.endpoint == \'admin.general_announcements\' %}{{ m_active }}{% else %}{{ m_idle }}{% endif %}">\n                <i class="fa-regular fa-newspaper w-5 text-center"></i>\n                <span>Announcements</span>\n            </a>\n            <a href="{{ url_for(\'admin.certificates\') }}"\n               class="{{ m_base }} {% if request.endpoint in [\'admin.certificates\', \'admin.certificate_preview\'] %}{{ m_active }}{% else %}{{ m_idle }}{% endif %}">\n                <i class="fa-solid fa-certificate w-5 text-center"></i>\n                <span>Certificates</span>\n            </a>\n            <a href="{{ url_for(\'public.home\') }}"\n               class="{{ m_base }} {{ m_idle }}">\n                <i class="fa-solid fa-house w-5 text-center"></i>\n                <span>Public site</span>\n            </a>\n            <a href="{{ url_for(\'public.logout\') }}"\n               class="{{ m_base }} text-red-600 hover:bg-red-50">\n                <i class="fa-solid fa-right-from-bracket w-5 text-center"></i>\n                <span>Log out</span>\n            </a>\n        </nav>\n    </div>\n</div>\n\n{% include "_notification_button.html" %}\n\n<script>\n(function () {\n    const modal = document.getElementById(\'admin-menu-modal\');\n    if (!modal) return;\n    function open()  { modal.classList.remove(\'hidden\'); document.body.classList.add(\'overflow-hidden\'); }\n    function close() { modal.classList.add(\'hidden\');    document.body.classList.remove(\'overflow-hidden\'); }\n    document.addEventListener(\'click\', function (e) {\n        if (e.target.closest(\'[data-admin-menu-open]\'))  { e.preventDefault(); open();  return; }\n        if (e.target.closest(\'[data-admin-menu-close]\')) { close(); return; }\n    });\n    document.addEventListener(\'keydown\', function (e) {\n        if (e.key === \'Escape\' && !modal.classList.contains(\'hidden\')) close();\n    });\n})();\n</script>\n{% endblock %}\n',
    'public/forgot_password.html': '{% extends "public/_auth_layout.html" %}\n{% block title %}Forgot password · Sangguniang Kabataan ng Bukal Scholarship Portal{% endblock %}\n\n{% block auth_content %}\n<h1 class="text-xl font-bold mb-1 text-brand-700">Forgot password?</h1>\n<p class="text-sm text-slate-600 mb-4">\n    Ilagay ang email mo at magpapadala kami ng 6-digit code para ma-reset ang password.\n</p>\n\n<form method="post" class="space-y-3">\n    <div>\n        <label class="block text-sm font-medium mb-1">Email</label>\n        <input name="email" type="email" required value="{{ email }}"\n               placeholder="you@example.com"\n               class="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-400" />\n    </div>\n    <button type="submit"\n            class="w-full bg-brand-500 hover:bg-brand-600 text-white font-medium py-2 rounded-md text-sm">\n        Send reset code\n    </button>\n</form>\n\n<p class="text-sm text-slate-600 mt-3">\n    Remembered your password?\n    <a href="{{ url_for(\'public.login\') }}" class="text-brand-600 hover:underline">Log in</a>\n</p>\n{% endblock %}\n',
    'public/home.html': '{% extends "base.html" %}\n{% block title %}Events · Sangguniang Kabataan ng Bukal Scholarship Portal{% endblock %}\n\n{% set slides = [\n    \'images/473265073_122186308370131251_417259699920810235_n.jpg\',\n    \'images/473338489_122186310134131251_7193305214024562341_n.jpg\',\n    \'images/473570088_122186310158131251_2841917794290302851_n.jpg\',\n] %}\n\n{% block hero %}\n<section id="hero-slider"\n         class="relative w-screen overflow-hidden shadow h-[260px] sm:h-[360px] md:h-[420px]">\n    {% for slide in slides %}\n        <div class="slide absolute inset-0 transition-opacity duration-700\n                    {% if loop.first %}opacity-100{% else %}opacity-0{% endif %}">\n            <div class="absolute inset-0 bg-cover bg-center"\n                 style="background-image: url(\'{{ url_for(\'static\', filename=slide) }}\');"></div>\n            <div class="absolute inset-0 bg-gradient-to-r from-brand-900/80 to-slate-900/40"></div>\n        </div>\n    {% endfor %}\n\n    <div class="relative h-full max-w-6xl mx-auto flex flex-col justify-center px-5 sm:px-8 py-10 sm:py-16 text-white">\n        <h1 class="text-2xl sm:text-3xl md:text-4xl font-bold drop-shadow">Apply for your scholarship</h1>\n        <p class="mt-2 max-w-2xl text-xs sm:text-base text-brand-100 drop-shadow">\n            Submit your documents online, track your application status, and stay\n            updated through official events from the scholarship office.\n        </p>\n    </div>\n\n    <div class="absolute bottom-3 sm:bottom-4 left-1/2 -translate-x-1/2 flex gap-2 z-10">\n        {% for slide in slides %}\n            <button type="button"\n                    data-index="{{ loop.index0 }}"\n                    class="slide-dot w-2 h-2 sm:w-2.5 sm:h-2.5 rounded-full bg-white/50 hover:bg-white transition\n                           {% if loop.first %}!bg-white{% endif %}"\n                    aria-label="Go to slide {{ loop.index }}"></button>\n        {% endfor %}\n    </div>\n</section>\n{% endblock %}\n\n{% block content %}\n{% set status_styles = {\n    \'open\':        \'bg-green-100 text-green-800\',\n    \'upcoming\':    \'bg-amber-100 text-amber-800\',\n    \'closed\':      \'bg-slate-200 text-slate-700\',\n    \'unscheduled\': \'bg-slate-100 text-slate-600\',\n} %}\n{% set category_labels = {\n    \'registration\': \'Scholarship Registration\',\n    \'payout\':       \'Scholarship Pay Out\',\n    \'general_orientation\':  \'General Orientation\',\n    \'general\':      \'General\',\n} %}\n{% set category_styles = {\n    \'registration\': \'bg-brand-50 text-brand-700\',\n    \'payout\':       \'bg-blue-50 text-blue-700\',\n    \'general_orientation\':  \'bg-purple-50 text-purple-700\',\n    \'general\':      \'bg-slate-100 text-slate-700\',\n} %}\n\n<h2 class="text-lg sm:text-xl font-semibold mb-3 sm:mb-4 text-brand-700">Latest events</h2>\n{% if announcements %}\n    <div class="space-y-3 sm:space-y-4">\n        {% for a in announcements %}\n            <article class="bg-white rounded-lg shadow-sm p-3 sm:p-5 border border-slate-100">\n                <div class="flex items-start justify-between gap-2 sm:gap-3 flex-wrap">\n                    <div class="min-w-0">\n                        <div class="flex items-center gap-1.5 sm:gap-2 flex-wrap mb-1">\n                            <span class="text-[10px] sm:text-xs px-2 py-0.5 rounded {{ category_styles.get(a.category, \'bg-slate-100 text-slate-700\') }}">\n                                {{ category_labels.get(a.category, \'General\') }}\n                            </span>\n                            {% if a.status != \'unscheduled\' %}\n                                <span class="text-[10px] sm:text-xs uppercase px-2 py-0.5 rounded {{ status_styles.get(a.status, \'bg-slate-100 text-slate-700\') }}">\n                                    {{ a.status }}\n                                </span>\n                            {% endif %}\n                        </div>\n                        <h3 class="font-semibold text-base sm:text-lg">{{ a.title }}</h3>\n                    </div>\n                    <time class="text-[11px] sm:text-xs text-slate-500 whitespace-nowrap">{{ a.created_at | ph_date }}</time>\n                </div>\n                {% if a.start_at and a.end_at %}\n                    <p class="text-[11px] sm:text-xs text-slate-500 mt-1">\n                        <i class="fa-regular fa-calendar mr-1"></i>\n                        {{ a.start_at | ph }} → {{ a.end_at | ph }}\n                    </p>\n                {% endif %}\n                <p class="mt-2 text-sm text-slate-700 whitespace-pre-line">{{ a.body }}</p>\n\n                {% if a.category == \'registration\' %}\n                    <div class="mt-3">\n                        {% if a.status == \'open\' %}\n                            <a href="{{ url_for(\'public.login\', next=url_for(\'student.dashboard\')) }}"\n                               class="inline-flex items-center gap-2 px-3 sm:px-4 py-1.5 sm:py-2 rounded-md bg-brand-500 hover:bg-brand-600 text-white text-xs sm:text-sm font-medium">\n                                <i class="fa-solid fa-paper-plane"></i> Apply now\n                            </a>\n                        {% elif a.status == \'upcoming\' %}\n                            <button type="button" disabled\n                                    class="inline-flex items-center gap-2 px-3 sm:px-4 py-1.5 sm:py-2 rounded-md bg-slate-200 text-slate-500 text-xs sm:text-sm font-medium cursor-not-allowed">\n                                <i class="fa-regular fa-clock"></i> Opens {{ a.start_at | ph_date }}\n                            </button>\n                        {% else %}\n                            <button type="button" disabled\n                                    class="inline-flex items-center gap-2 px-3 sm:px-4 py-1.5 sm:py-2 rounded-md bg-slate-200 text-slate-500 text-xs sm:text-sm font-medium cursor-not-allowed">\n                                <i class="fa-solid fa-lock"></i> Registration closed\n                            </button>\n                        {% endif %}\n                    </div>\n                {% elif a.category == \'payout\' %}\n                    <div class="mt-3">\n                        {% if a.status == \'open\' %}\n                            <a href="{{ url_for(\'public.login\', next=url_for(\'student.announcements\')) }}"\n                               class="inline-flex items-center gap-2 px-3 sm:px-4 py-1.5 sm:py-2 rounded-md bg-blue-600 hover:bg-blue-700 text-white text-xs sm:text-sm font-medium">\n                                <i class="fa-solid fa-handshake"></i> Log in to join\n                            </a>\n                        {% elif a.status == \'upcoming\' %}\n                            <button type="button" disabled\n                                    class="inline-flex items-center gap-2 px-3 sm:px-4 py-1.5 sm:py-2 rounded-md bg-slate-200 text-slate-500 text-xs sm:text-sm font-medium cursor-not-allowed">\n                                <i class="fa-regular fa-clock"></i> Opens {{ a.start_at | ph_date }}\n                            </button>\n                        {% else %}\n                            <button type="button" disabled\n                                    class="inline-flex items-center gap-2 px-3 sm:px-4 py-1.5 sm:py-2 rounded-md bg-slate-200 text-slate-500 text-xs sm:text-sm font-medium cursor-not-allowed">\n                                <i class="fa-solid fa-lock"></i> Pay-out closed\n                            </button>\n                        {% endif %}\n                    </div>\n                {% elif a.category == \'general_orientation\' %}\n                    <div class="mt-3">\n                        {% if a.status == \'open\' %}\n                            <a href="{{ url_for(\'public.login\', next=url_for(\'student.announcements\')) }}"\n                               class="inline-flex items-center gap-2 px-3 sm:px-4 py-1.5 sm:py-2 rounded-md bg-purple-600 hover:bg-purple-700 text-white text-xs sm:text-sm font-medium">\n                                <i class="fa-solid fa-people-group"></i> Log in to join\n                            </a>\n                        {% elif a.status == \'upcoming\' %}\n                            <button type="button" disabled\n                                    class="inline-flex items-center gap-2 px-3 sm:px-4 py-1.5 sm:py-2 rounded-md bg-slate-200 text-slate-500 text-xs sm:text-sm font-medium cursor-not-allowed">\n                                <i class="fa-regular fa-clock"></i> Opens {{ a.start_at | ph_date }}\n                            </button>\n                        {% else %}\n                            <button type="button" disabled\n                                    class="inline-flex items-center gap-2 px-3 sm:px-4 py-1.5 sm:py-2 rounded-md bg-slate-200 text-slate-500 text-xs sm:text-sm font-medium cursor-not-allowed">\n                                <i class="fa-solid fa-lock"></i> Orientation closed\n                            </button>\n                        {% endif %}\n                    </div>\n                {% endif %}\n            </article>\n        {% endfor %}\n    </div>\n{% else %}\n    <p class="text-slate-500 text-sm">No events yet. Check back later.</p>\n{% endif %}\n\n<script>\n(function () {\n    const root = document.getElementById(\'hero-slider\');\n    if (!root) return;\n    const slides = root.querySelectorAll(\'.slide\');\n    const dots   = root.querySelectorAll(\'.slide-dot\');\n    let current  = 0;\n\n    function show(i) {\n        slides.forEach((s, idx) => {\n            s.style.opacity = idx === i ? \'1\' : \'0\';\n        });\n        dots.forEach((d, idx) => {\n            d.classList.toggle(\'!bg-white\', idx === i);\n        });\n        current = i;\n    }\n\n    dots.forEach(d => d.addEventListener(\'click\', () => {\n        show(parseInt(d.dataset.index, 10));\n    }));\n\n    setInterval(() => show((current + 1) % slides.length), 5000);\n})();\n</script>\n{% endblock %}\n',
    'public/login.html': '{% extends "public/_auth_layout.html" %}\n{% block title %}Log in · Sangguniang Kabataan ng Bukal Scholarship Portal{% endblock %}\n\n{% block auth_content %}\n<h1 class="text-xl font-bold mb-1 text-brand-700">Welcome back</h1>\n<p class="text-sm text-slate-500 mb-4">Log in to continue your application.</p>\n\n{% set is_locked = (lockout_seconds or 0) > 0 %}\n\n{# Lockout banner. The countdown ticks live and survives refreshes because\n   ``lockout_seconds`` is computed server-side from the stored expiry. #}\n<div id="lockout-banner"\n     class="mb-3 p-3 rounded-md border border-red-200 bg-red-50 text-red-700 text-sm\n            {% if not is_locked %}hidden{% endif %}"\n     role="alert" aria-live="polite"\n     data-lockout-seconds="{{ lockout_seconds or 0 }}">\n    <div class="flex items-start gap-2">\n        <i class="fa-solid fa-lock mt-0.5"></i>\n        <div class="min-w-0">\n            <p class="font-medium">Account temporarily locked</p>\n            <p class="text-xs">\n                Too many failed attempts. Please try again in\n                <span id="lockout-countdown" class="font-semibold">{{ lockout_seconds or 0 }}</span>\n                second<span id="lockout-plural">{% if (lockout_seconds or 0) != 1 %}s{% endif %}</span>.\n            </p>\n        </div>\n    </div>\n</div>\n\n<form method="post" class="space-y-3" id="login-form">\n    {% if next %}\n        <input type="hidden" name="next" value="{{ next }}" />\n    {% endif %}\n    <div>\n        <label class="block text-sm font-medium mb-1">Email</label>\n        <input name="email" type="email" required\n               value="{{ lockout_email or \'\' }}"\n               {% if is_locked %}readonly{% endif %}\n               class="w-full rounded-md border border-slate-300 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-brand-400 read-only:bg-slate-50" />\n    </div>\n    <div>\n        <label class="block text-sm font-medium mb-1">Password</label>\n        <div class="password-field relative">\n            <input name="password" type="password" required\n                   {% if is_locked %}disabled{% endif %}\n                   class="w-full rounded-md border border-slate-300 px-3 py-2 pr-10 text-sm focus:outline-none focus:ring-2 focus:ring-brand-400 disabled:bg-slate-50" />\n            <button type="button" data-password-toggle\n                    class="absolute inset-y-0 right-0 px-3 flex items-center text-slate-500 hover:text-slate-700"\n                    aria-label="Show password" aria-pressed="false">\n                <i class="fa-regular fa-eye"></i>\n            </button>\n        </div>\n        <p class="mt-1.5 text-right">\n            <a href="{{ url_for(\'public.forgot_password\') }}"\n               class="text-xs text-brand-600 hover:underline">\n                Forgot password?\n            </a>\n        </p>\n    </div>\n    <button type="submit" id="login-submit"\n            {% if is_locked %}disabled{% endif %}\n            class="w-full bg-brand-500 hover:bg-brand-600 disabled:bg-slate-300 disabled:cursor-not-allowed text-white font-medium py-2 rounded-md text-sm">\n        {% if is_locked %}\n            Locked — try again in <span id="lockout-button-countdown">{{ lockout_seconds or 0 }}</span>s\n        {% else %}\n            Log in\n        {% endif %}\n    </button>\n</form>\n\n<p class="text-sm text-slate-600 mt-3">\n    Don\'t have an account?\n    <a href="{{ url_for(\'public.signup\') }}" class="text-brand-600 hover:underline">Sign up</a>\n</p>\n\n<script>\n(function () {\n    const banner = document.getElementById(\'lockout-banner\');\n    if (!banner) return;\n\n    let remaining = parseInt(banner.dataset.lockoutSeconds || \'0\', 10);\n    if (!Number.isFinite(remaining) || remaining <= 0) return;\n\n    const form    = document.getElementById(\'login-form\');\n    const submit  = document.getElementById(\'login-submit\');\n    const pwInput = form ? form.querySelector(\'input[name="password"]\') : null;\n    const counter = document.getElementById(\'lockout-countdown\');\n    const plural  = document.getElementById(\'lockout-plural\');\n    const btnCount = document.getElementById(\'lockout-button-countdown\');\n\n    function render() {\n        if (counter)  counter.textContent  = String(remaining);\n        if (btnCount) btnCount.textContent = String(remaining);\n        if (plural)   plural.textContent   = remaining === 1 ? \'\' : \'s\';\n    }\n\n    function unlock() {\n        banner.classList.add(\'hidden\');\n        if (submit) {\n            submit.disabled = false;\n            submit.textContent = \'Log in\';\n        }\n        if (pwInput) pwInput.disabled = false;\n    }\n\n    render();\n    const tick = setInterval(function () {\n        remaining -= 1;\n        if (remaining <= 0) {\n            clearInterval(tick);\n            unlock();\n            return;\n        }\n        render();\n    }, 1000);\n})();\n</script>\n{% endblock %}\n',
    'public/reset_password.html': '{% extends "public/_auth_layout.html" %}\n{% block title %}Reset password · Sangguniang Kabataan ng Bukal Scholarship Portal{% endblock %}\n\n{% block auth_content %}\n<h1 class="text-xl font-bold mb-1 text-brand-700">Reset your password</h1>\n<p class="text-sm text-slate-600 mb-4">\n    Nagpadala kami ng 6-digit code sa\n    <span class="font-medium text-slate-800">{{ email }}</span>.\n    I-enter ito at maglagay ng bagong password.\n</p>\n\n<form method="post" class="space-y-3">\n    <input type="hidden" name="email" value="{{ email }}" />\n\n    <div>\n        <label class="block text-sm font-medium mb-1">Verification code</label>\n        <input name="token" required maxlength="6" inputmode="numeric"\n               pattern="[0-9]{6}" placeholder="123456"\n               class="w-full rounded-md border border-slate-300 px-3 py-2 text-center text-lg tracking-[0.5em] font-mono focus:outline-none focus:ring-2 focus:ring-brand-400" />\n    </div>\n\n    <div>\n        <label class="block text-sm font-medium mb-1">New password</label>\n        <div class="password-field relative">\n            <input id="reset-password" name="password" type="password" required minlength="8"\n                   pattern="(?=.*\\d)(?=.*[^A-Za-z0-9]).{8,}"\n                   title="At least 8 characters, with one number and one special character."\n                   class="w-full rounded-md border border-slate-300 px-3 py-2 pr-10 text-sm focus:outline-none focus:ring-2 focus:ring-brand-400" />\n            <button type="button" data-password-toggle\n                    class="absolute inset-y-0 right-0 px-3 flex items-center text-slate-500 hover:text-slate-700"\n                    aria-label="Show password" aria-pressed="false">\n                <i class="fa-regular fa-eye"></i>\n            </button>\n        </div>\n        <ul id="reset-pw-rules" class="mt-1.5 space-y-0.5 text-xs text-slate-500" aria-live="polite">\n            <li data-rule="length" class="flex items-center gap-1.5">\n                <i class="fa-regular fa-circle text-slate-300"></i>\n                <span>At least 8 characters</span>\n            </li>\n            <li data-rule="number" class="flex items-center gap-1.5">\n                <i class="fa-regular fa-circle text-slate-300"></i>\n                <span>Contains a number</span>\n            </li>\n            <li data-rule="special" class="flex items-center gap-1.5">\n                <i class="fa-regular fa-circle text-slate-300"></i>\n                <span>Contains a special character (e.g. ! @ # $ %)</span>\n            </li>\n        </ul>\n    </div>\n\n    <div>\n        <label class="block text-sm font-medium mb-1">Confirm new password</label>\n        <div class="password-field relative">\n            <input id="reset-password-confirm" name="password_confirm" type="password" required minlength="8"\n                   class="w-full rounded-md border border-slate-300 px-3 py-2 pr-10 text-sm focus:outline-none focus:ring-2 focus:ring-brand-400" />\n            <button type="button" data-password-toggle\n                    class="absolute inset-y-0 right-0 px-3 flex items-center text-slate-500 hover:text-slate-700"\n                    aria-label="Show password" aria-pressed="false">\n                <i class="fa-regular fa-eye"></i>\n            </button>\n        </div>\n        <p id="reset-pw-match" class="mt-1.5 text-xs text-slate-500 hidden"></p>\n    </div>\n\n    <button type="submit"\n            class="w-full bg-brand-500 hover:bg-brand-600 text-white font-medium py-2 rounded-md text-sm">\n        Update password\n    </button>\n</form>\n\n<form method="post" action="{{ url_for(\'public.resend_reset_code\') }}" class="mt-2">\n    <input type="hidden" name="email" value="{{ email }}" />\n    <button type="submit"\n            class="w-full text-sm text-brand-600 hover:underline">\n        Resend code\n    </button>\n</form>\n\n<p class="text-sm text-slate-600 mt-3">\n    <a href="{{ url_for(\'public.login\') }}" class="text-brand-600 hover:underline">&larr; Back to log in</a>\n</p>\n\n<script>\n(function () {\n    const pw      = document.getElementById(\'reset-password\');\n    const confirm = document.getElementById(\'reset-password-confirm\');\n    const rules   = document.getElementById(\'reset-pw-rules\');\n    const match   = document.getElementById(\'reset-pw-match\');\n    if (!pw || !rules) return;\n\n    const checks = {\n        length:  v => v.length >= 8,\n        number:  v => /\\d/.test(v),\n        special: v => /[^A-Za-z0-9]/.test(v),\n    };\n\n    function setRule(name, ok) {\n        const li = rules.querySelector(\'[data-rule="\' + name + \'"]\');\n        if (!li) return;\n        const icon = li.querySelector(\'i\');\n        if (ok) {\n            li.classList.remove(\'text-slate-500\');\n            li.classList.add(\'text-green-600\');\n            icon.className = \'fa-solid fa-circle-check\';\n        } else {\n            li.classList.remove(\'text-green-600\');\n            li.classList.add(\'text-slate-500\');\n            icon.className = \'fa-regular fa-circle text-slate-300\';\n        }\n    }\n\n    function refresh() {\n        const v = pw.value || \'\';\n        Object.keys(checks).forEach(k => setRule(k, checks[k](v)));\n\n        if (confirm && (confirm.value || \'\').length > 0) {\n            match.classList.remove(\'hidden\');\n            if (v === confirm.value) {\n                match.textContent = \'Passwords match.\';\n                match.className = \'mt-1.5 text-xs text-green-600\';\n            } else {\n                match.textContent = \'Passwords do not match.\';\n                match.className = \'mt-1.5 text-xs text-red-600\';\n            }\n        } else if (match) {\n            match.classList.add(\'hidden\');\n        }\n    }\n\n    pw.addEventListener(\'input\', refresh);\n    if (confirm) confirm.addEventListener(\'input\', refresh);\n    refresh();\n})();\n</script>\n{% endblock %}\n',
    'public/signup.html': '{% extends "public/_auth_layout.html" %}\n{% block title %}Sign up · Sangguniang Kabataan ng Bukal Scholarship Portal{% endblock %}\n\n{% block auth_card_width %}max-w-2xl{% endblock %}\n\n{% block auth_content %}\n<h1 class="text-xl font-bold mb-1 text-brand-700">Create your account</h1>\n<p class="text-sm text-slate-500 mb-4">Sign up as a student to apply for a scholarship.</p>\n\n{# Tight spacing: smaller gaps + smaller inputs so the whole form fits in the viewport. #}\n<form method="post" class="space-y-3 text-sm">\n    <div class="grid sm:grid-cols-2 gap-3">\n        <div>\n            <label class="block font-medium mb-1">First name</label>\n            <input name="first_name" required value="{{ form.first_name or \'\' }}"\n                   class="w-full rounded-md border border-slate-300 px-3 py-1.5 focus:outline-none focus:ring-2 focus:ring-brand-400" />\n        </div>\n        <div>\n            <label class="block font-medium mb-1">Middle name <span class="text-slate-400 font-normal">(optional)</span></label>\n            <input name="middle_name" value="{{ form.middle_name or \'\' }}"\n                   class="w-full rounded-md border border-slate-300 px-3 py-1.5 focus:outline-none focus:ring-2 focus:ring-brand-400" />\n        </div>\n        <div>\n            <label class="block font-medium mb-1">Last name (Surname)</label>\n            <input name="last_name" required value="{{ form.last_name or \'\' }}"\n                   class="w-full rounded-md border border-slate-300 px-3 py-1.5 focus:outline-none focus:ring-2 focus:ring-brand-400" />\n        </div>\n        <div>\n            <label class="block font-medium mb-1">Suffix</label>\n            <select name="suffix"\n                    class="w-full rounded-md border border-slate-300 px-3 py-1.5 bg-white focus:outline-none focus:ring-2 focus:ring-brand-400">\n                <option value="">— None —</option>\n                {% for s in [\'Jr.\', \'Sr.\', \'II\', \'III\', \'IV\', \'V\'] %}\n                    <option value="{{ s }}" {% if form.suffix == s %}selected{% endif %}>{{ s }}</option>\n                {% endfor %}\n            </select>\n        </div>\n    </div>\n\n    <div class="grid sm:grid-cols-2 gap-3">\n        <div>\n            <label class="block font-medium mb-1">Email</label>\n            <input name="email" type="email" required value="{{ form.email or \'\' }}"\n                   class="w-full rounded-md border border-slate-300 px-3 py-1.5 focus:outline-none focus:ring-2 focus:ring-brand-400" />\n        </div>\n        <div>\n            <label class="block font-medium mb-1">Facebook profile URL</label>\n            <input name="facebook_url" type="url" required\n                   placeholder="https://www.facebook.com/yourname"\n                   value="{{ form.facebook_url or \'\' }}"\n                   class="w-full rounded-md border border-slate-300 px-3 py-1.5 focus:outline-none focus:ring-2 focus:ring-brand-400" />\n        </div>\n    </div>\n\n    {# ---------- Address ----------\n       Cascading PSGC dropdowns: pick Region → Province → City/Municipality →\n       Barangay. The names are submitted as plain text so we never depend\n       on PSGC codes server-side. House number, street, and purok stay as\n       free text. #}\n    <fieldset class="border border-slate-200 rounded-md p-3 pt-2">\n        <legend class="px-1 text-xs font-semibold text-slate-600 uppercase tracking-wide">Home address</legend>\n\n        <div class="grid sm:grid-cols-3 gap-3">\n            <div>\n                <label class="block font-medium mb-1">House / Lot / Block no.</label>\n                <input name="address_house_no" required\n                       placeholder="e.g. 123 / Lot 4 Blk 2"\n                       value="{{ form.address_house_no or \'\' }}"\n                       class="w-full rounded-md border border-slate-300 px-3 py-1.5 focus:outline-none focus:ring-2 focus:ring-brand-400" />\n            </div>\n            <div>\n                <label class="block font-medium mb-1">Street <span class="text-slate-400 font-normal">(optional)</span></label>\n                <input name="address_street"\n                       placeholder="e.g. Rizal St."\n                       value="{{ form.address_street or \'\' }}"\n                       class="w-full rounded-md border border-slate-300 px-3 py-1.5 focus:outline-none focus:ring-2 focus:ring-brand-400" />\n            </div>\n            <div>\n                <label class="block font-medium mb-1">Purok / Sitio</label>\n                <input name="address_purok" required\n                       placeholder="e.g. Purok 3"\n                       value="{{ form.address_purok or \'\' }}"\n                       class="w-full rounded-md border border-slate-300 px-3 py-1.5 focus:outline-none focus:ring-2 focus:ring-brand-400" />\n            </div>\n        </div>\n\n        <div class="grid sm:grid-cols-2 gap-3 mt-3">\n            <div>\n                <label class="block font-medium mb-1">Region</label>\n                <select id="addr-region" required\n                        data-prefill="{{ form.address_region or \'\' }}"\n                        class="w-full rounded-md border border-slate-300 px-3 py-1.5 bg-white focus:outline-none focus:ring-2 focus:ring-brand-400">\n                    <option value="">Loading regions…</option>\n                </select>\n                {# Hidden input so we POST the human-readable name. #}\n                <input type="hidden" name="address_region" id="addr-region-name"\n                       value="{{ form.address_region or \'\' }}" />\n            </div>\n            <div>\n                <label class="block font-medium mb-1">Province</label>\n                <select id="addr-province" required disabled\n                        data-prefill="{{ form.address_province or \'\' }}"\n                        class="w-full rounded-md border border-slate-300 px-3 py-1.5 bg-white focus:outline-none focus:ring-2 focus:ring-brand-400 disabled:bg-slate-100">\n                    <option value="">Pumili muna ng region</option>\n                </select>\n                <input type="hidden" name="address_province" id="addr-province-name"\n                       value="{{ form.address_province or \'\' }}" />\n            </div>\n        </div>\n\n        <div class="grid sm:grid-cols-2 gap-3 mt-3">\n            <div>\n                <label class="block font-medium mb-1">City / Municipality</label>\n                <select id="addr-city" required disabled\n                        data-prefill="{{ form.address_city or \'\' }}"\n                        class="w-full rounded-md border border-slate-300 px-3 py-1.5 bg-white focus:outline-none focus:ring-2 focus:ring-brand-400 disabled:bg-slate-100">\n                    <option value="">Pumili muna ng province</option>\n                </select>\n                <input type="hidden" name="address_city" id="addr-city-name"\n                       value="{{ form.address_city or \'\' }}" />\n            </div>\n            <div>\n                <label class="block font-medium mb-1">Barangay</label>\n                <select id="addr-barangay" required disabled\n                        data-prefill="{{ form.address_barangay or \'\' }}"\n                        class="w-full rounded-md border border-slate-300 px-3 py-1.5 bg-white focus:outline-none focus:ring-2 focus:ring-brand-400 disabled:bg-slate-100">\n                    <option value="">Pumili muna ng city/municipality</option>\n                </select>\n                <input type="hidden" name="address_barangay" id="addr-barangay-name"\n                       value="{{ form.address_barangay or \'\' }}" />\n            </div>\n        </div>\n\n        <div class="grid sm:grid-cols-2 gap-3 mt-3">\n            <div>\n                <label class="block font-medium mb-1">ZIP code <span class="text-slate-400 font-normal">(optional)</span></label>\n                <input name="address_zip" inputmode="numeric" pattern="\\d{4}"\n                       placeholder="e.g. 4327"\n                       value="{{ form.address_zip or \'\' }}"\n                       class="w-full rounded-md border border-slate-300 px-3 py-1.5 focus:outline-none focus:ring-2 focus:ring-brand-400" />\n            </div>\n        </div>\n    </fieldset>\n\n    <div class="grid sm:grid-cols-2 gap-3">\n        <div>\n            <label class="block font-medium mb-1">Password</label>\n            <div class="password-field relative">\n                <input id="signup-password" name="password" type="password" minlength="8" required\n                       pattern="(?=.*\\d)(?=.*[^A-Za-z0-9]).{8,}"\n                       title="At least 8 characters, with one number and one special character."\n                       class="w-full rounded-md border border-slate-300 px-3 py-1.5 pr-10 focus:outline-none focus:ring-2 focus:ring-brand-400" />\n                <button type="button" data-password-toggle\n                        class="absolute inset-y-0 right-0 px-3 flex items-center text-slate-500 hover:text-slate-700"\n                        aria-label="Show password" aria-pressed="false">\n                    <i class="fa-regular fa-eye"></i>\n                </button>\n            </div>\n            <ul id="pw-rules" class="mt-1.5 space-y-0.5 text-xs text-slate-500" aria-live="polite">\n                <li data-rule="length" class="flex items-center gap-1.5">\n                    <i class="fa-regular fa-circle text-slate-300"></i>\n                    <span>At least 8 characters</span>\n                </li>\n                <li data-rule="number" class="flex items-center gap-1.5">\n                    <i class="fa-regular fa-circle text-slate-300"></i>\n                    <span>Contains a number</span>\n                </li>\n                <li data-rule="special" class="flex items-center gap-1.5">\n                    <i class="fa-regular fa-circle text-slate-300"></i>\n                    <span>Contains a special character (e.g. ! @ # $ %)</span>\n                </li>\n            </ul>\n        </div>\n        <div>\n            <label class="block font-medium mb-1">Confirm password</label>\n            <div class="password-field relative">\n                <input id="signup-password-confirm" name="password_confirm" type="password" minlength="8" required\n                       class="w-full rounded-md border border-slate-300 px-3 py-1.5 pr-10 focus:outline-none focus:ring-2 focus:ring-brand-400" />\n                <button type="button" data-password-toggle\n                        class="absolute inset-y-0 right-0 px-3 flex items-center text-slate-500 hover:text-slate-700"\n                        aria-label="Show password" aria-pressed="false">\n                    <i class="fa-regular fa-eye"></i>\n                </button>\n            </div>\n            <p id="pw-match" class="mt-1.5 text-xs text-slate-500 hidden"></p>\n        </div>\n    </div>\n\n    <button type="submit"\n            class="w-full bg-brand-500 hover:bg-brand-600 text-white font-medium py-2 rounded-md">\n        Create account\n    </button>\n</form>\n\n<p class="text-sm text-slate-600 mt-3">\n    Already have an account?\n    <a href="{{ url_for(\'public.login\') }}" class="text-brand-600 hover:underline">Log in</a>\n</p>\n\n<script>\n(function () {\n    const regionSel   = document.getElementById(\'addr-region\');\n    const provinceSel = document.getElementById(\'addr-province\');\n    const citySel     = document.getElementById(\'addr-city\');\n    const barangaySel = document.getElementById(\'addr-barangay\');\n    const regionName   = document.getElementById(\'addr-region-name\');\n    const provinceName = document.getElementById(\'addr-province-name\');\n    const cityName     = document.getElementById(\'addr-city-name\');\n    const barangayName = document.getElementById(\'addr-barangay-name\');\n    if (!regionSel || !provinceSel || !citySel || !barangaySel) return;\n\n    function setOptions(select, items, placeholder) {\n        select.innerHTML = \'\';\n        const blank = document.createElement(\'option\');\n        blank.value = \'\';\n        blank.textContent = placeholder;\n        select.appendChild(blank);\n        items.forEach(function (it) {\n            const opt = document.createElement(\'option\');\n            opt.value = it.code;\n            opt.textContent = it.name;\n            opt.dataset.name = it.name;\n            select.appendChild(opt);\n        });\n    }\n\n    function preselect(select, prefillName) {\n        if (!prefillName) return false;\n        const target = String(prefillName).toLowerCase();\n        for (const opt of select.options) {\n            if ((opt.dataset.name || \'\').toLowerCase() === target) {\n                opt.selected = true;\n                return true;\n            }\n        }\n        return false;\n    }\n\n    async function fetchJson(url) {\n        try {\n            const r = await fetch(url, { credentials: \'same-origin\' });\n            if (!r.ok) return [];\n            return await r.json();\n        } catch (_) { return []; }\n    }\n\n    function reset(select, placeholder, hidden) {\n        select.disabled = true;\n        select.innerHTML = \'<option value="">\' + placeholder + \'</option>\';\n        if (hidden) hidden.value = \'\';\n    }\n\n    async function loadProvinces(regionCode, prefillName) {\n        reset(provinceSel, \'Loading…\', provinceName);\n        reset(citySel, \'Pumili muna ng province\', cityName);\n        reset(barangaySel, \'Pumili muna ng city/municipality\', barangayName);\n        const items = await fetchJson(\'/api/psgc/regions/\' + encodeURIComponent(regionCode) + \'/provinces\');\n        if (items.length) {\n            setOptions(provinceSel, items, \'Pumili ng province\');\n            provinceSel.disabled = false;\n        } else {\n            // Region without provinces (e.g. NCR) — skip straight to cities.\n            setOptions(provinceSel, [], \'Walang province (NCR)\');\n            provinceSel.disabled = true;\n            provinceName.value = \'\';\n            await loadCities(regionCode, \'\', prefillName ? null : \'\');\n            return;\n        }\n        if (preselect(provinceSel, prefillName)) {\n            provinceName.value = provinceSel.options[provinceSel.selectedIndex].dataset.name || \'\';\n            await loadCities(regionCode, provinceSel.value, null);\n        }\n    }\n\n    async function loadCities(regionCode, provinceCode, prefillName) {\n        reset(citySel, \'Loading…\', cityName);\n        reset(barangaySel, \'Pumili muna ng city/municipality\', barangayName);\n        const url = \'/api/psgc/cities-municipalities?\'\n            + \'region=\' + encodeURIComponent(regionCode || \'\')\n            + (provinceCode ? \'&province=\' + encodeURIComponent(provinceCode) : \'\');\n        const items = await fetchJson(url);\n        setOptions(citySel, items, \'Pumili ng city / municipality\');\n        citySel.disabled = items.length === 0;\n        if (preselect(citySel, prefillName)) {\n            cityName.value = citySel.options[citySel.selectedIndex].dataset.name || \'\';\n            await loadBarangays(citySel.value, null);\n        }\n    }\n\n    async function loadBarangays(cityCode, prefillName) {\n        reset(barangaySel, \'Loading…\', barangayName);\n        const items = await fetchJson(\'/api/psgc/cities-municipalities/\' + encodeURIComponent(cityCode) + \'/barangays\');\n        setOptions(barangaySel, items, \'Pumili ng barangay\');\n        barangaySel.disabled = items.length === 0;\n        if (preselect(barangaySel, prefillName)) {\n            barangayName.value = barangaySel.options[barangaySel.selectedIndex].dataset.name || \'\';\n        }\n    }\n\n    regionSel.addEventListener(\'change\', async function () {\n        regionName.value = regionSel.options[regionSel.selectedIndex].dataset.name || \'\';\n        if (regionSel.value) await loadProvinces(regionSel.value, null);\n        else {\n            reset(provinceSel, \'Pumili muna ng region\', provinceName);\n            reset(citySel, \'Pumili muna ng province\', cityName);\n            reset(barangaySel, \'Pumili muna ng city/municipality\', barangayName);\n        }\n    });\n    provinceSel.addEventListener(\'change\', async function () {\n        provinceName.value = provinceSel.options[provinceSel.selectedIndex]?.dataset.name || \'\';\n        if (provinceSel.value) await loadCities(regionSel.value, provinceSel.value, null);\n        else {\n            reset(citySel, \'Pumili muna ng province\', cityName);\n            reset(barangaySel, \'Pumili muna ng city/municipality\', barangayName);\n        }\n    });\n    citySel.addEventListener(\'change\', async function () {\n        cityName.value = citySel.options[citySel.selectedIndex]?.dataset.name || \'\';\n        if (citySel.value) await loadBarangays(citySel.value, null);\n        else reset(barangaySel, \'Pumili muna ng city/municipality\', barangayName);\n    });\n    barangaySel.addEventListener(\'change\', function () {\n        barangayName.value = barangaySel.options[barangaySel.selectedIndex]?.dataset.name || \'\';\n    });\n\n    (async function init() {\n        const regions = await fetchJson(\'/api/psgc/regions\');\n        if (!regions.length) {\n            regionSel.innerHTML = \'<option value="">Hindi ma-load ang regions — i-refresh ang page.</option>\';\n            return;\n        }\n        setOptions(regionSel, regions, \'Pumili ng region\');\n        const prefillRegion = regionSel.dataset.prefill;\n        const prefillProv   = provinceSel.dataset.prefill;\n        const prefillCity   = citySel.dataset.prefill;\n        const prefillBgy    = barangaySel.dataset.prefill;\n        if (preselect(regionSel, prefillRegion)) {\n            regionName.value = regionSel.options[regionSel.selectedIndex].dataset.name || \'\';\n            await loadProvinces(regionSel.value, prefillProv);\n            // If region has no provinces, loadProvinces already calls loadCities;\n            // otherwise loadProvinces preselects and loads cities itself.\n            if (prefillCity) {\n                // Wait for the city dropdown to have items, then preselect.\n                if (!citySel.disabled && preselect(citySel, prefillCity)) {\n                    cityName.value = citySel.options[citySel.selectedIndex].dataset.name || \'\';\n                    await loadBarangays(citySel.value, prefillBgy);\n                }\n            }\n        }\n    })();\n})();\n</script>\n\n<script>\n(function () {\n    const pw      = document.getElementById(\'signup-password\');\n    const confirm = document.getElementById(\'signup-password-confirm\');\n    const rules   = document.getElementById(\'pw-rules\');\n    const match   = document.getElementById(\'pw-match\');\n    if (!pw || !rules) return;\n\n    const checks = {\n        length:  v => v.length >= 8,\n        number:  v => /\\d/.test(v),\n        special: v => /[^A-Za-z0-9]/.test(v),\n    };\n\n    function setRule(name, ok) {\n        const li = rules.querySelector(\'[data-rule="\' + name + \'"]\');\n        if (!li) return;\n        const icon = li.querySelector(\'i\');\n        if (ok) {\n            li.classList.remove(\'text-slate-500\');\n            li.classList.add(\'text-green-600\');\n            icon.className = \'fa-solid fa-circle-check\';\n        } else {\n            li.classList.remove(\'text-green-600\');\n            li.classList.add(\'text-slate-500\');\n            icon.className = \'fa-regular fa-circle text-slate-300\';\n        }\n    }\n\n    function refresh() {\n        const v = pw.value || \'\';\n        Object.keys(checks).forEach(k => setRule(k, checks[k](v)));\n\n        if (confirm && (confirm.value || \'\').length > 0) {\n            match.classList.remove(\'hidden\');\n            if (v === confirm.value) {\n                match.textContent = \'Passwords match.\';\n                match.className = \'mt-1.5 text-xs text-green-600\';\n            } else {\n                match.textContent = \'Passwords do not match.\';\n                match.className = \'mt-1.5 text-xs text-red-600\';\n            }\n        } else if (match) {\n            match.classList.add(\'hidden\');\n        }\n    }\n\n    pw.addEventListener(\'input\', refresh);\n    if (confirm) confirm.addEventListener(\'input\', refresh);\n    refresh();\n})();\n</script>\n{% endblock %}\n',
    'public/verify.html': '{% extends "public/_auth_layout.html" %}\n{% block title %}Verify email · Sangguniang Kabataan ng Bukal Scholarship Portal{% endblock %}\n\n{% block auth_content %}\n<h1 class="text-xl font-bold mb-1 text-brand-700">Verify your email</h1>\n<p class="text-sm text-slate-600 mb-4">\n    We sent a 6-digit verification code to\n    <span class="font-medium text-slate-800">{{ email }}</span>.\n    Enter it below to activate your account.\n</p>\n\n<form method="post" class="space-y-3">\n    <input type="hidden" name="email" value="{{ email }}" />\n    <div>\n        <label class="block text-sm font-medium mb-1">Verification code</label>\n        <input name="token" required maxlength="6" inputmode="numeric"\n               pattern="[0-9]{6}" placeholder="123456"\n               class="w-full rounded-md border border-slate-300 px-3 py-2 text-center text-lg tracking-[0.5em] font-mono focus:outline-none focus:ring-2 focus:ring-brand-400" />\n    </div>\n    <button type="submit"\n            class="w-full bg-brand-500 hover:bg-brand-600 text-white font-medium py-2 rounded-md text-sm">\n        Verify and continue\n    </button>\n</form>\n\n<form method="post" action="{{ url_for(\'public.resend_code\') }}" class="mt-2">\n    <input type="hidden" name="email" value="{{ email }}" />\n    <button type="submit"\n            class="w-full text-sm text-brand-600 hover:underline">\n        Resend code\n    </button>\n</form>\n{% endblock %}\n',
    'public/_auth_layout.html': '{% extends "base.html" %}\n\n{# Auth pages (login, signup, verify): lock the viewport so the page never\n   scrolls. The header stays at the top, footer at the bottom, and the card\n   fills the remaining space. If the form is ever taller than the available\n   space (very small phones), the card itself scrolls instead of the page. #}\n\n{% block body_class %}h-screen overflow-hidden flex flex-col{% endblock %}\n\n{% block main %}\n<main class="flex-1 min-h-0 flex items-center justify-center px-4 py-4">\n    <div class="w-full {% block auth_card_width %}max-w-md{% endblock %}\n                bg-white rounded-xl shadow border border-slate-100\n                max-h-full overflow-y-auto p-5 sm:p-6">\n        {% block auth_content %}{% endblock %}\n    </div>\n</main>\n{% endblock %}\n\n{% block footer %}\n<footer class="text-center text-[11px] text-slate-500 py-2 shrink-0">\n    &copy; {{ 2026 }} Sangguniang Kabataan ng Bukal Scholarship Portal\n</footer>\n{% endblock %}\n',
    'student/announcements.html': '{% extends "student/_layout.html" %}\n{% block title %}Events · Sangguniang Kabataan ng Bukal Scholarship Portal{% endblock %}\n\n{% set status_styles = {\n    \'open\':        \'bg-green-100 text-green-800\',\n    \'upcoming\':    \'bg-amber-100 text-amber-800\',\n    \'closed\':      \'bg-slate-200 text-slate-700\',\n    \'unscheduled\': \'bg-slate-100 text-slate-600\',\n} %}\n{% set category_labels = {\n    \'registration\': \'Scholarship Registration\',\n    \'payout\':       \'Scholarship Pay Out\',\n    \'general_orientation\':  \'General Orientation\',\n    \'general\':      \'General\',\n} %}\n{% set category_styles = {\n    \'registration\': \'bg-brand-50 text-brand-700\',\n    \'payout\':       \'bg-blue-50 text-blue-700\',\n    \'general_orientation\':  \'bg-purple-50 text-purple-700\',\n    \'general\':      \'bg-slate-100 text-slate-700\',\n} %}\n\n{% block student_content %}\n<div class="bg-white rounded-xl shadow-sm border border-slate-100 p-3 sm:p-6">\n    <div class="flex items-center gap-2 mb-3 sm:mb-4">\n        <i class="fa-solid fa-bullhorn text-brand-600"></i>\n        <h1 class="text-base sm:text-xl font-bold text-brand-700">Events</h1>\n    </div>\n\n    {% if announcements %}\n        <div class="space-y-3 sm:space-y-4">\n            {% for a in announcements %}\n                <article id="anc-{{ a.id }}" class="border border-slate-100 rounded-lg p-3 sm:p-4 hover:bg-slate-50 transition scroll-mt-24">\n                    <div class="flex items-start justify-between gap-2 sm:gap-3 flex-wrap">\n                        <div class="min-w-0">\n                            <div class="flex items-center gap-1.5 sm:gap-2 flex-wrap mb-1">\n                                <span class="text-[10px] sm:text-xs px-2 py-0.5 rounded {{ category_styles.get(a.category, \'bg-slate-100 text-slate-700\') }}">\n                                    {{ category_labels.get(a.category, \'General\') }}\n                                </span>\n                                {% if a.status != \'unscheduled\' %}\n                                    <span class="text-[10px] sm:text-xs uppercase px-2 py-0.5 rounded {{ status_styles.get(a.status, \'bg-slate-100 text-slate-700\') }}">\n                                        {{ a.status }}\n                                    </span>\n                                {% endif %}\n                            </div>\n                            <h2 class="font-semibold text-slate-800 text-sm sm:text-base">{{ a.title }}</h2>\n                        </div>\n                        <time class="text-[11px] sm:text-xs text-slate-500 whitespace-nowrap">{{ a.created_at | ph_date }}</time>\n                    </div>\n                    {% if a.start_at and a.end_at %}\n                        <p class="text-[11px] sm:text-xs text-slate-500 mt-1">\n                            <i class="fa-regular fa-calendar mr-1"></i>\n                            {{ a.start_at | ph }} → {{ a.end_at | ph }}\n                        </p>\n                    {% endif %}\n                    <p class="mt-2 text-xs sm:text-sm text-slate-700 whitespace-pre-line leading-relaxed">{{ a.body }}</p>\n\n                    {% if a.category == \'registration\' %}\n                        <div class="mt-2 sm:mt-3">\n                            {% if already_verified %}\n                                <button type="button" disabled\n                                        class="inline-flex items-center gap-2 px-3 sm:px-4 py-1.5 sm:py-2 rounded-md bg-green-100 text-green-800 text-xs sm:text-sm font-medium cursor-not-allowed">\n                                    <i class="fa-solid fa-circle-check"></i> Verified scholar\n                                </button>\n                            {% elif a.status == \'open\' %}\n                                <form method="post" action="{{ url_for(\'student.apply\') }}">\n                                    <button type="submit"\n                                            class="inline-flex items-center gap-2 px-3 sm:px-4 py-1.5 sm:py-2 rounded-md bg-brand-500 hover:bg-brand-600 text-white text-xs sm:text-sm font-medium">\n                                        <i class="fa-solid fa-paper-plane"></i> Apply now\n                                    </button>\n                                </form>\n                            {% elif a.status == \'upcoming\' %}\n                                <button type="button" disabled\n                                        class="inline-flex items-center gap-2 px-3 sm:px-4 py-1.5 sm:py-2 rounded-md bg-slate-200 text-slate-500 text-xs sm:text-sm font-medium cursor-not-allowed">\n                                    <i class="fa-regular fa-clock"></i> Opens {{ a.start_at | ph_date }}\n                                </button>\n                            {% else %}\n                                <button type="button" disabled\n                                        class="inline-flex items-center gap-2 px-3 sm:px-4 py-1.5 sm:py-2 rounded-md bg-slate-200 text-slate-500 text-xs sm:text-sm font-medium cursor-not-allowed">\n                                    <i class="fa-solid fa-lock"></i> Registration closed\n                                </button>\n                            {% endif %}\n                        </div>\n                    {% elif a.category == \'payout\' %}\n                        {% set orient_req = orientation_status.get(a.id, {}) %}\n                        {% set needs_orientation = orient_req and not orient_req.get(\'attended\') %}\n                        \n                        {# Show warning if orientation is required but not attended #}\n                        {% if needs_orientation %}\n                        <div class="mt-2 bg-amber-50 border border-amber-200 rounded-md p-2">\n                            <p class="text-[11px] sm:text-xs text-amber-800">\n                                <i class="fa-solid fa-exclamation-triangle mr-1"></i>\n                                <span class="font-semibold">General Orientation required.</span>\n                                You must attend the required orientation event before joining this pay-out.\n                            </p>\n                        </div>\n                        {% endif %}\n                        \n                        <div class="mt-2 sm:mt-3">\n                            {% if a.id in joined_ids %}\n                                <button type="button" disabled\n                                        class="inline-flex items-center gap-2 px-3 sm:px-4 py-1.5 sm:py-2 rounded-md bg-green-100 text-green-800 text-xs sm:text-sm font-medium cursor-not-allowed">\n                                    <i class="fa-solid fa-circle-check"></i> Joined\n                                </button>\n                            {% elif needs_orientation %}\n                                <button type="button" disabled\n                                        class="inline-flex items-center gap-2 px-3 sm:px-4 py-1.5 sm:py-2 rounded-md bg-slate-300 text-slate-600 text-xs sm:text-sm font-medium cursor-not-allowed">\n                                    <i class="fa-solid fa-lock"></i> Attend orientation first\n                                </button>\n                            {% elif a.status == \'open\' %}\n                                <button type="button"\n                                        data-sign-open\n                                        data-anc-id="{{ a.id }}"\n                                        data-event-title="{{ a.title }}"\n                                        data-event-kind="Pay-out"\n                                        class="inline-flex items-center gap-2 px-3 sm:px-4 py-1.5 sm:py-2 rounded-md bg-blue-600 hover:bg-blue-700 text-white text-xs sm:text-sm font-medium">\n                                    <i class="fa-solid fa-handshake"></i> Sign &amp; join pay-out\n                                </button>\n                            {% elif a.status == \'upcoming\' %}\n                                <button type="button" disabled\n                                        class="inline-flex items-center gap-2 px-3 sm:px-4 py-1.5 sm:py-2 rounded-md bg-slate-200 text-slate-500 text-xs sm:text-sm font-medium cursor-not-allowed">\n                                    <i class="fa-regular fa-clock"></i> Opens {{ a.start_at | ph_date }}\n                                </button>\n                            {% else %}\n                                <button type="button" disabled\n                                        class="inline-flex items-center gap-2 px-3 sm:px-4 py-1.5 sm:py-2 rounded-md bg-slate-200 text-slate-500 text-xs sm:text-sm font-medium cursor-not-allowed">\n                                    <i class="fa-solid fa-lock"></i> Pay-out closed\n                                </button>\n                            {% endif %}\n                        </div>\n                    {% elif a.category == \'general_orientation\' %}\n                        <div class="mt-2 sm:mt-3">\n                            {% if a.id in joined_ids %}\n                                <button type="button" disabled\n                                        class="inline-flex items-center gap-2 px-3 sm:px-4 py-1.5 sm:py-2 rounded-md bg-green-100 text-green-800 text-xs sm:text-sm font-medium cursor-not-allowed">\n                                    <i class="fa-solid fa-circle-check"></i> Joined\n                                </button>\n                            {% elif a.status == \'open\' %}\n                                <button type="button"\n                                        data-sign-open\n                                        data-anc-id="{{ a.id }}"\n                                        data-event-title="{{ a.title }}"\n                                        data-event-kind="General Orientation"\n                                        class="inline-flex items-center gap-2 px-3 sm:px-4 py-1.5 sm:py-2 rounded-md bg-purple-600 hover:bg-purple-700 text-white text-xs sm:text-sm font-medium">\n                                    <i class="fa-solid fa-pen-nib"></i> Sign &amp; join orientation\n                                </button>\n                            {% elif a.status == \'upcoming\' %}\n                                <button type="button" disabled\n                                        class="inline-flex items-center gap-2 px-3 sm:px-4 py-1.5 sm:py-2 rounded-md bg-slate-200 text-slate-500 text-xs sm:text-sm font-medium cursor-not-allowed">\n                                    <i class="fa-regular fa-clock"></i> Opens {{ a.start_at | ph_date }}\n                                </button>\n                            {% else %}\n                                <button type="button" disabled\n                                        class="inline-flex items-center gap-2 px-3 sm:px-4 py-1.5 sm:py-2 rounded-md bg-slate-200 text-slate-500 text-xs sm:text-sm font-medium cursor-not-allowed">\n                                    <i class="fa-solid fa-lock"></i> Orientation closed\n                                </button>\n                            {% endif %}\n                        </div>\n                    {% endif %}\n                </article>\n            {% endfor %}\n        </div>\n    {% else %}\n        <p class="text-slate-500 text-sm">No events yet. Check back later.</p>\n    {% endif %}\n</div>\n\n{# ===== Signature pad modal — shown when the student taps Sign & join. ===== #}\n<div id="signature-modal"\n     class="hidden fixed inset-0 z-[70] flex items-center justify-center p-3 sm:p-4"\n     role="dialog" aria-modal="true" aria-labelledby="signature-title">\n    <div class="absolute inset-0 bg-slate-900/60" data-sign-close></div>\n    <form method="post" id="signature-form"\n          class="relative bg-white rounded-xl shadow-xl w-full max-w-2xl flex flex-col overflow-hidden max-h-[95vh]">\n        <div class="flex items-start gap-3 px-5 py-4 border-b">\n            <span class="w-10 h-10 rounded-full bg-brand-50 text-brand-600 flex items-center justify-center shrink-0">\n                <i class="fa-solid fa-pen-nib"></i>\n            </span>\n            <div class="min-w-0">\n                <h2 id="signature-title" class="text-base sm:text-lg font-bold text-slate-800">\n                    Sign to join\n                </h2>\n                <p class="text-xs sm:text-sm text-slate-500 mt-0.5">\n                    <span id="signature-event-kind">Event</span> ·\n                    <span id="signature-event-title" class="font-medium text-slate-700"></span>\n                </p>\n            </div>\n        </div>\n        <div class="px-5 py-4 space-y-3">\n            <p class="text-xs sm:text-sm text-slate-600">\n                Pumirma sa loob ng box gamit ang mouse o daliri. Hawakan ang\n                <span class="font-medium">Clear</span> kapag gusto mong simulan ulit.\n            </p>\n            <div class="rounded-lg border border-slate-200 bg-slate-50 overflow-hidden">\n                <canvas id="signature-pad"\n                        width="900" height="380"\n                        class="w-full block touch-none bg-white"\n                        style="height: clamp(280px, 45vh, 420px);"></canvas>\n            </div>\n            <div class="flex items-center justify-between">\n                <p id="signature-help" class="text-[11px] text-slate-500"></p>\n                <button type="button" data-sign-clear\n                        class="text-xs text-slate-500 hover:text-slate-700 underline">\n                    Clear\n                </button>\n            </div>\n            <input type="hidden" name="signature" id="signature-data" />\n        </div>\n        <div class="px-5 py-3 border-t flex justify-end gap-2 bg-slate-50">\n            <button type="button" data-sign-close\n                    class="px-3 sm:px-4 py-2 rounded-md bg-white border border-slate-200 text-slate-700 hover:bg-slate-100 text-sm font-medium">\n                Cancel\n            </button>\n            <button type="submit" id="signature-submit" disabled\n                    class="px-3 sm:px-4 py-2 rounded-md bg-brand-500 hover:bg-brand-600 text-white text-sm font-semibold disabled:bg-slate-300 disabled:cursor-not-allowed">\n                <i class="fa-solid fa-check mr-1"></i>\n                Confirm join\n            </button>\n        </div>\n    </form>\n</div>\n\n<script>\n(function () {\n    const modal      = document.getElementById(\'signature-modal\');\n    const form       = document.getElementById(\'signature-form\');\n    const canvas     = document.getElementById(\'signature-pad\');\n    const dataInput  = document.getElementById(\'signature-data\');\n    const submitBtn  = document.getElementById(\'signature-submit\');\n    const help       = document.getElementById(\'signature-help\');\n    const eventTitle = document.getElementById(\'signature-event-title\');\n    const eventKind  = document.getElementById(\'signature-event-kind\');\n    if (!modal || !canvas) return;\n\n    const ctx = canvas.getContext(\'2d\');\n    let drawing = false;\n    let dirty   = false;\n    let lastX = 0, lastY = 0;\n\n    function fitCanvas() {\n        // Match the canvas backing store to its CSS size so strokes\n        // line up with the cursor on high-DPI screens.\n        const rect = canvas.getBoundingClientRect();\n        const ratio = window.devicePixelRatio || 1;\n        canvas.width  = Math.round(rect.width * ratio);\n        canvas.height = Math.round(rect.height * ratio);\n        ctx.setTransform(ratio, 0, 0, ratio, 0, 0);\n        ctx.lineCap = \'round\';\n        ctx.lineJoin = \'round\';\n        ctx.lineWidth = 2.2;\n        ctx.strokeStyle = \'#0f172a\';\n        ctx.fillStyle = \'#ffffff\';\n        ctx.fillRect(0, 0, rect.width, rect.height);\n    }\n\n    function clearPad() {\n        const rect = canvas.getBoundingClientRect();\n        ctx.fillStyle = \'#ffffff\';\n        ctx.fillRect(0, 0, rect.width, rect.height);\n        dirty = false;\n        submitBtn.disabled = true;\n        if (help) help.textContent = \'\';\n        dataInput.value = \'\';\n    }\n\n    function pointerXY(e) {\n        const rect = canvas.getBoundingClientRect();\n        const t = (e.touches && e.touches[0]) || (e.changedTouches && e.changedTouches[0]) || e;\n        return { x: t.clientX - rect.left, y: t.clientY - rect.top };\n    }\n\n    function start(e) {\n        e.preventDefault();\n        drawing = true;\n        const p = pointerXY(e);\n        lastX = p.x; lastY = p.y;\n    }\n    function move(e) {\n        if (!drawing) return;\n        e.preventDefault();\n        const p = pointerXY(e);\n        ctx.beginPath();\n        ctx.moveTo(lastX, lastY);\n        ctx.lineTo(p.x, p.y);\n        ctx.stroke();\n        lastX = p.x; lastY = p.y;\n        if (!dirty) {\n            dirty = true;\n            submitBtn.disabled = false;\n            if (help) help.textContent = \'Pirma na-detect. Pwede mo nang i-confirm.\';\n        }\n    }\n    function end(e) {\n        drawing = false;\n    }\n\n    canvas.addEventListener(\'mousedown\', start);\n    canvas.addEventListener(\'mousemove\', move);\n    canvas.addEventListener(\'mouseup\', end);\n    canvas.addEventListener(\'mouseleave\', end);\n    canvas.addEventListener(\'touchstart\', start, { passive: false });\n    canvas.addEventListener(\'touchmove\', move, { passive: false });\n    canvas.addEventListener(\'touchend\', end);\n    canvas.addEventListener(\'touchcancel\', end);\n\n    function open(opts) {\n        form.action = opts.action;\n        eventTitle.textContent = opts.title || \'\';\n        eventKind.textContent  = opts.kind  || \'Event\';\n        modal.classList.remove(\'hidden\');\n        document.body.classList.add(\'overflow-hidden\');\n        // Wait a tick for layout, then size the canvas.\n        requestAnimationFrame(function () {\n            fitCanvas();\n            clearPad();\n        });\n    }\n    function close() {\n        modal.classList.add(\'hidden\');\n        document.body.classList.remove(\'overflow-hidden\');\n    }\n\n    document.addEventListener(\'click\', function (e) {\n        const trigger = e.target.closest(\'[data-sign-open]\');\n        if (trigger) {\n            open({\n                action: \'{{ url_for("student.join_payout", anc_id=0) }}\'.replace(\'/0/\', \'/\' + trigger.dataset.ancId + \'/\'),\n                title:  trigger.dataset.eventTitle,\n                kind:   trigger.dataset.eventKind,\n            });\n            return;\n        }\n        if (e.target.closest(\'[data-sign-close]\')) { close(); return; }\n        if (e.target.closest(\'[data-sign-clear]\')) { clearPad(); return; }\n    });\n\n    form.addEventListener(\'submit\', function (e) {\n        if (!dirty) {\n            e.preventDefault();\n            if (help) help.textContent = \'Pumirma muna sa box bago mag-confirm.\';\n            return;\n        }\n        // Compress to PNG and stash in the hidden field.\n        try {\n            dataInput.value = canvas.toDataURL(\'image/png\');\n        } catch (err) {\n            e.preventDefault();\n            if (help) help.textContent = \'Hindi ma-save ang signature. Subukan ulit.\';\n        }\n    });\n\n    document.addEventListener(\'keydown\', function (e) {\n        if (e.key === \'Escape\' && !modal.classList.contains(\'hidden\')) close();\n    });\n\n    window.addEventListener(\'resize\', function () {\n        if (modal.classList.contains(\'hidden\')) return;\n        // Snapshot the current strokes before re-fitting.\n        const snap = canvas.toDataURL(\'image/png\');\n        fitCanvas();\n        const img = new Image();\n        img.onload = function () {\n            const rect = canvas.getBoundingClientRect();\n            ctx.drawImage(img, 0, 0, rect.width, rect.height);\n        };\n        img.src = snap;\n    });\n})();\n</script>\n{% endblock %}\n',
    'student/application.html': '{% extends "student/_layout.html" %}\n{% block title %}Application requirements · Sangguniang Kabataan ng Bukal Scholarship Portal{% endblock %}\n\n{% set status_styles = {\n    \'pending\':  \'bg-amber-100 text-amber-800\',\n    \'verified\': \'bg-green-100 text-green-800\',\n    \'rejected\': \'bg-red-100 text-red-800\',\n} %}\n\n{% block student_content %}\n<div class="mb-3">\n    <a href="{{ url_for(\'student.applications_list\') }}"\n       class="inline-flex items-center gap-2 text-xs sm:text-sm text-slate-600 hover:text-brand-700">\n        <i class="fa-solid fa-arrow-left"></i>\n        Back to my applications\n    </a>\n</div>\n\n{% set is_verified = application.status == \'verified\' %}\n{% set locked = is_verified or (not window_open and application.status not in (\'pending\', \'rejected\')) %}\n\n{% if is_verified %}\n    <div class="mb-3 p-3 sm:p-4 rounded-xl border border-green-200 bg-green-50 text-green-800 text-xs sm:text-sm flex items-start gap-2 sm:gap-3">\n        <i class="fa-solid fa-circle-check mt-0.5"></i>\n        <div>\n            <p class="font-semibold">Your application has been verified.</p>\n            <p>Salamat! Wala ka nang kailangan i-submit dito. Bantayan mo na lang ang\n                <a href="{{ url_for(\'student.announcements\') }}" class="underline">events</a>\n                para sa pay-out at iba pang updates.\n            </p>\n        </div>\n    </div>\n{% elif not window_open and application.status not in (\'pending\', \'rejected\') %}\n    <div class="mb-3 p-3 sm:p-4 rounded-xl border border-amber-200 bg-amber-50 text-amber-800 text-xs sm:text-sm flex items-start gap-2 sm:gap-3">\n        <i class="fa-solid fa-lock mt-0.5"></i>\n        <div>\n            <p class="font-semibold">The registration window for this application is closed.</p>\n            <p>You can view what was submitted, but you can no longer make changes.\n                {% if open_registration %}\n                    A new registration is open —\n                    <a href="{{ url_for(\'student.applications_list\') }}" class="underline">go back to your applications</a>\n                    to apply again.\n                {% endif %}\n            </p>\n        </div>\n    </div>\n{% elif not window_open and application.status in (\'pending\', \'rejected\') %}\n    <div class="mb-3 p-3 sm:p-4 rounded-xl border border-blue-200 bg-blue-50 text-blue-800 text-xs sm:text-sm flex items-start gap-2 sm:gap-3">\n        <i class="fa-solid fa-info-circle mt-0.5"></i>\n        <div>\n            <p class="font-semibold">The original registration window is closed, but you can still update your application.</p>\n            <p>You can upload or replace documents for your pending application. The admin will review any changes.</p>\n        </div>\n    </div>\n{% endif %}\n\n<form method="post"\n      action="{{ url_for(\'student.submit_requirements\', app_id=application.id) }}"\n      enctype="multipart/form-data"\n      data-require-complete\n      class="grid md:grid-cols-3 gap-4 sm:gap-6">\n\n    <section class="md:col-span-2 space-y-3 sm:space-y-4">\n        <div class="bg-white rounded-xl shadow-sm p-4 sm:p-6 border border-slate-100">\n            <div class="flex items-start justify-between gap-2 sm:gap-3 mb-2 sm:mb-3 flex-wrap">\n                <div class="min-w-0">\n                    <h1 class="text-lg sm:text-2xl font-bold truncate">\n                        {{ application.registration.title if application.registration else \'My application\' }}\n                    </h1>\n                    <p class="text-xs sm:text-sm text-slate-500 mt-1">\n                        {{ level_label }} · {{ year_label }}\n                    </p>\n                    {% if application.registration and application.registration.start_at and application.registration.end_at %}\n                        <p class="text-[11px] sm:text-xs text-slate-500 mt-0.5">\n                            <i class="fa-regular fa-calendar mr-1"></i>\n                            {{ application.registration.start_at | ph }} → {{ application.registration.end_at | ph }}\n                        </p>\n                    {% endif %}\n                </div>\n                <span class="text-[10px] sm:text-xs uppercase tracking-wide px-2 py-1 rounded {{ status_styles.get(application.status, \'bg-slate-100 text-slate-700\') }}">\n                    {{ application.status }}\n                </span>\n            </div>\n\n            {% if application.notes %}\n                <div class="p-3 rounded-md bg-slate-50 border border-slate-200 text-xs sm:text-sm">\n                    <p class="font-medium text-slate-700 mb-1">Reviewer notes</p>\n                    <p class="text-slate-600 whitespace-pre-line">{{ application.notes }}</p>\n                </div>\n            {% endif %}\n        </div>\n\n        <h2 class="text-base sm:text-lg font-semibold">Required documents</h2>\n\n        <div class="space-y-2 sm:space-y-3">\n            {% for s in slots %}\n                {% set is_image = s.kind == \'image\' %}\n                {% set accept = \'image/*\' if is_image else \'application/pdf\' %}\n                <div class="bg-white rounded-xl shadow-sm border border-slate-100 p-3 sm:p-4">\n                    <div class="flex items-start justify-between gap-2 sm:gap-3 flex-wrap">\n                        <div class="flex items-start gap-2 sm:gap-3 min-w-0">\n                            <span class="w-8 h-8 sm:w-9 sm:h-9 rounded-md bg-brand-50 text-brand-600 flex items-center justify-center shrink-0">\n                                <i class="fa-solid {{ \'fa-id-card\' if is_image else \'fa-file-pdf\' }}"></i>\n                            </span>\n                            <div class="min-w-0">\n                                <p class="font-medium text-sm sm:text-base">{{ s.label }}</p>\n                                <p class="text-[11px] sm:text-xs text-slate-500">\n                                    {% if is_image %}\n                                        Take a photo with the camera, or upload an image (JPG/PNG). Max 5 MB.\n                                    {% else %}\n                                        PDF file only. Max 5 MB.\n                                    {% endif %}\n                                </p>\n                                {% if s.file %}\n                                    <p class="text-[11px] sm:text-xs text-slate-600 mt-1 break-all">\n                                        <i class="fa-solid fa-circle-check text-green-600 mr-1"></i>\n                                        <span class="break-all">{{ s.file.file_name }}</span>\n                                        <span class="text-slate-400">· {{ (s.file.size_bytes or 0) // 1024 }} KB</span>\n                                    </p>\n                                {% endif %}\n                            </div>\n                        </div>\n                        <span class="text-[10px] sm:text-xs px-2 py-0.5 sm:py-1 rounded\n                                     {% if s.file %}bg-green-100 text-green-800{% else %}bg-slate-100 text-slate-600{% endif %}">\n                            {% if s.file %}Uploaded{% else %}Missing{% endif %}\n                        </span>\n                    </div>\n\n                    <div class="mt-2 sm:mt-3">\n                        <input type="file"\n                               name="document_{{ s.key }}"\n                               accept="{{ accept }}"\n                               data-slot-input\n                               data-has-existing="{{ \'1\' if s.file else \'0\' }}"\n                               {% if is_image %}capture="environment"{% endif %}\n                               {% if locked %}disabled{% endif %}\n                               class="block text-xs sm:text-sm w-full file:mr-2 sm:file:mr-3 file:px-2 sm:file:px-3 file:py-1 sm:file:py-1.5 file:rounded-md\n                                      file:border-0 file:bg-brand-50 file:text-brand-700 hover:file:bg-brand-100\n                                      disabled:opacity-60 disabled:cursor-not-allowed" />\n                    </div>\n                </div>\n            {% endfor %}\n        </div>\n\n        <div data-submit-card\n             class="bg-white rounded-xl shadow-sm border border-slate-100 p-3 sm:p-4 flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2 sm:gap-3\n                    {% if locked or (is_complete and application.status == \'pending\') %}hidden{% endif %}">\n            <p class="text-xs sm:text-sm text-slate-600" data-submit-help>\n                {% if is_complete %}\n                    All requirements are complete. Tap <span class="font-medium">Submit</span> to send to the admin.\n                {% else %}\n                    You need to upload <span class="font-medium">all</span> requirements before submitting.\n                {% endif %}\n            </p>\n            <button type="button"\n                    data-submit-button\n                    {% if locked or not is_complete %}disabled{% endif %}\n                    class="px-4 sm:px-5 py-2 rounded-md bg-brand-500 hover:bg-brand-600 text-white text-sm font-semibold whitespace-nowrap\n                           disabled:bg-slate-300 disabled:cursor-not-allowed">\n                <i class="fa-solid fa-paper-plane mr-1"></i>\n                Submit requirements\n            </button>\n        </div>\n\n        {# Shown after the student has fully submitted and the admin\n           hasn\'t decided yet. Hidden the moment they pick a replacement\n           file, so the submit button reappears. Also hidden when the\n           application is already verified — the page then has nothing\n           the student can act on. #}\n        <div data-submitted-note\n             class="bg-green-50 border border-green-200 rounded-xl p-3 sm:p-4 flex items-start gap-2 sm:gap-3\n                    {% if is_verified or not (is_complete and application.status == \'pending\') %}hidden{% endif %}">\n            <span class="w-8 h-8 rounded-full bg-green-100 text-green-700 flex items-center justify-center shrink-0">\n                <i class="fa-solid fa-circle-check"></i>\n            </span>\n            <div class="text-xs sm:text-sm">\n                <p class="font-semibold text-green-800">Your documents are uploaded.</p>\n                <p class="text-green-700 mt-0.5">\n                    They are now being reviewed by the admin. We\'ll let you know once a decision is made.\n                </p>\n            </div>\n        </div>\n    </section>\n\n    <aside class="bg-white rounded-xl shadow-sm p-4 sm:p-6 border border-slate-100 h-fit">\n        <h2 class="font-semibold mb-2 text-sm sm:text-base">What happens next?</h2>\n        <ol class="list-decimal list-inside text-xs sm:text-sm text-slate-600 space-y-1">\n            <li>Choose a file for each requirement.</li>\n            <li>Tap Submit to save them all at once.</li>\n            <li>The admin will review your submission.</li>\n            <li>The status will change to <em>verified</em> or <em>rejected</em>.</li>\n        </ol>\n    </aside>\n\n    {# Confirmation pop-up shown right before the application is sent. #}\n    <div id="submit-confirm-modal"\n         class="hidden fixed inset-0 z-[70] flex items-center justify-center p-4"\n         role="dialog" aria-modal="true" aria-labelledby="submit-confirm-title">\n        <div class="absolute inset-0 bg-slate-900/60" data-confirm-close></div>\n        <div class="relative bg-white rounded-xl shadow-xl w-full max-w-md flex flex-col overflow-hidden">\n            <div class="flex items-start gap-3 px-5 py-4 border-b">\n                <span class="w-10 h-10 rounded-full bg-brand-50 text-brand-600 flex items-center justify-center shrink-0">\n                    <i class="fa-solid fa-paper-plane"></i>\n                </span>\n                <div class="min-w-0">\n                    <h2 id="submit-confirm-title" class="text-base sm:text-lg font-bold text-slate-800">\n                        Submit your application?\n                    </h2>\n                    <p class="text-xs sm:text-sm text-slate-500 mt-0.5">\n                        Before submitting, make sure all files are correct and clear.\n                    </p>\n                </div>\n            </div>\n            <div class="px-5 py-4 text-sm text-slate-700 space-y-3">\n                <p>\n                    Once submitted, the admin will see your application\n                    for review. You can still replace files while the\n                    registration window is open.\n                </p>\n                <ul class="text-xs sm:text-sm text-slate-600 list-disc list-inside space-y-0.5">\n                    {% for s in slots %}\n                        <li>\n                            <span class="font-medium">{{ s.label }}</span>\n                            <span class="text-slate-400">·</span>\n                            <span class="text-green-700">\n                                <i class="fa-solid fa-circle-check"></i> Ready to submit\n                            </span>\n                        </li>\n                    {% endfor %}\n                </ul>\n            </div>\n            <div class="px-5 py-3 border-t flex justify-end gap-2 bg-slate-50">\n                <button type="button" data-confirm-close\n                        class="px-3 sm:px-4 py-2 rounded-md bg-white border border-slate-200 text-slate-700 hover:bg-slate-100 text-sm font-medium">\n                    Cancel\n                </button>\n                <button type="button" data-confirm-submit\n                        class="px-3 sm:px-4 py-2 rounded-md bg-brand-500 hover:bg-brand-600 text-white text-sm font-semibold">\n                    <i class="fa-solid fa-paper-plane mr-1"></i>\n                    Yes, submit now\n                </button>\n            </div>\n        </div>\n    </div>\n</form>\n\n{% if (window_open or application.status in (\'pending\', \'rejected\')) and not is_verified %}\n<script>\n(function () {\n    const form = document.querySelector(\'form[data-require-complete]\');\n    if (!form) return;\n\n    const inputs        = form.querySelectorAll(\'[data-slot-input]\');\n    const submitBtn     = form.querySelector(\'[data-submit-button]\');\n    const submitCard    = form.querySelector(\'[data-submit-card]\');\n    const submittedNote = form.querySelector(\'[data-submitted-note]\');\n    const helpText      = form.querySelector(\'[data-submit-help]\');\n    const modal         = document.getElementById(\'submit-confirm-modal\');\n    if (!submitBtn) return;\n\n    const initialStatus  = {{ application.status | tojson }};\n    const initiallyClean = {{ (is_complete and application.status == \'pending\') | tojson }};\n\n    const completeMsg   = \'All requirements are complete. Tap Submit to send to the admin.\';\n    const incompleteMsg = \'You need to upload all requirements before submitting.\';\n\n    function hasNewSelection() {\n        for (const el of inputs) {\n            if (el.files && el.files.length > 0) return true;\n        }\n        return false;\n    }\n\n    function isComplete() {\n        let complete = true;\n        inputs.forEach(function (el) {\n            const hasExisting = el.getAttribute(\'data-has-existing\') === \'1\';\n            const hasNew = el.files && el.files.length > 0;\n            if (!hasExisting && !hasNew) complete = false;\n        });\n        return complete;\n    }\n\n    function refresh() {\n        const complete   = isComplete();\n        const newPicked  = hasNewSelection();\n        // Show the "submitted, awaiting review" note when the student\n        // already has a complete pending submission AND hasn\'t picked a\n        // replacement file in this session. Otherwise show the submit\n        // card so they can re-submit.\n        const showNote   = initiallyClean && !newPicked;\n\n        submitBtn.disabled = !complete;\n        if (helpText) helpText.textContent = complete ? completeMsg : incompleteMsg;\n\n        if (submittedNote) submittedNote.classList.toggle(\'hidden\', !showNote);\n        if (submitCard)    submitCard.classList.toggle(\'hidden\', showNote);\n    }\n\n    function openModal() {\n        if (!modal) { form.submit(); return; }\n        modal.classList.remove(\'hidden\');\n    }\n    function closeModal() {\n        if (modal) modal.classList.add(\'hidden\');\n    }\n\n    inputs.forEach(function (el) { el.addEventListener(\'change\', refresh); });\n\n    submitBtn.addEventListener(\'click\', function (e) {\n        e.preventDefault();\n        if (submitBtn.disabled) return;\n        openModal();\n    });\n\n    if (modal) {\n        modal.addEventListener(\'click\', function (e) {\n            if (e.target.closest(\'[data-confirm-close]\')) { closeModal(); return; }\n            if (e.target.closest(\'[data-confirm-submit]\')) {\n                closeModal();\n                form.submit();\n            }\n        });\n        document.addEventListener(\'keydown\', function (e) {\n            if (e.key === \'Escape\') closeModal();\n        });\n    }\n\n    refresh();\n})();\n</script>\n{% endif %}\n{% endblock %}\n',
    'student/applications.html': '{% extends "student/_layout.html" %}\n{% block title %}My Applications · Sangguniang Kabataan ng Bukal Scholarship Portal{% endblock %}\n\n{% set status_styles = {\n    \'pending\':  \'bg-amber-100 text-amber-800\',\n    \'verified\': \'bg-green-100 text-green-800\',\n    \'rejected\': \'bg-red-100 text-red-800\',\n} %}\n\n{% block student_content %}\n<div class="space-y-3 sm:space-y-5">\n\n    {# ---------- Open registration banner ---------- #}\n    {% if already_verified %}\n        <div class="rounded-xl border border-green-200 bg-green-50 p-3 sm:p-5 flex items-start gap-2 sm:gap-3 shadow-sm">\n            <span class="w-9 h-9 sm:w-10 sm:h-10 rounded-full bg-green-500 text-white flex items-center justify-center shrink-0">\n                <i class="fa-solid fa-circle-check"></i>\n            </span>\n            <div class="text-xs sm:text-sm text-green-800">\n                <p class="font-semibold text-sm sm:text-base">You\'re already a verified scholar.</p>\n                <p>Hindi ka na pwedeng mag-apply ulit sa scholarship registration. Bantayan mo na lang ang\n                    <a href="{{ url_for(\'student.announcements\') }}" class="underline font-medium">events</a>\n                    para sa pay-out at iba pang updates.\n                </p>\n            </div>\n        </div>\n    {% elif open_registration %}\n        <div class="rounded-xl border border-brand-200 bg-brand-50 p-3 sm:p-5 flex flex-col sm:flex-row sm:items-center gap-3 sm:gap-4 shadow-sm">\n            <span class="w-10 h-10 sm:w-11 sm:h-11 rounded-full bg-brand-500 text-white flex items-center justify-center shrink-0">\n                <i class="fa-solid fa-bullhorn"></i>\n            </span>\n            <div class="flex-1 min-w-0">\n                <p class="text-[11px] sm:text-xs uppercase tracking-wide text-brand-700 font-semibold">\n                    Registration is open\n                </p>\n                <p class="font-semibold text-brand-800 truncate text-sm sm:text-base">{{ open_registration.title }}</p>\n                {% if open_registration.start_at and open_registration.end_at %}\n                    <p class="text-[11px] sm:text-xs text-brand-700/80 mt-0.5">\n                        <i class="fa-regular fa-calendar mr-1"></i>\n                        {{ open_registration.start_at | ph }} → {{ open_registration.end_at | ph }}\n                    </p>\n                {% endif %}\n            </div>\n            {% if open_application %}\n                <a href="{{ url_for(\'student.application\', app_id=open_application.id) }}"\n                   class="inline-flex items-center gap-2 px-3 sm:px-4 py-2 rounded-md bg-brand-500 hover:bg-brand-600 text-white text-sm font-semibold whitespace-nowrap">\n                    <i class="fa-solid fa-pen-to-square"></i>\n                    Continue\n                </a>\n            {% elif not orientation_attended %}\n                <div class="inline-flex items-center gap-2 px-3 sm:px-4 py-2 rounded-md bg-slate-300 text-slate-600 text-sm font-semibold whitespace-nowrap cursor-not-allowed">\n                    <i class="fa-solid fa-lock"></i>\n                    Apply now\n                </div>\n            {% else %}\n                <form method="post" action="{{ url_for(\'student.apply\') }}">\n                    <button type="submit"\n                            class="inline-flex items-center gap-2 px-3 sm:px-4 py-2 rounded-md bg-brand-500 hover:bg-brand-600 text-white text-sm font-semibold whitespace-nowrap">\n                        <i class="fa-solid fa-paper-plane"></i>\n                        Apply now\n                    </button>\n                </form>\n            {% endif %}\n        </div>\n        \n        {# Show orientation requirement notice if not attended #}\n        {% if orientation_required and not orientation_attended %}\n        <div class="rounded-xl border border-amber-200 bg-amber-50 p-3 sm:p-5 flex items-start gap-2 sm:gap-3 shadow-sm">\n            <span class="w-9 h-9 sm:w-10 sm:h-10 rounded-full bg-amber-500 text-white flex items-center justify-center shrink-0">\n                <i class="fa-solid fa-exclamation-triangle"></i>\n            </span>\n            <div class="text-xs sm:text-sm text-amber-800">\n                <p class="font-semibold text-sm sm:text-base">General Orientation Required</p>\n                <p>Dapat dumalo ka muna sa <span class="font-semibold">"{{ orientation_required.title }}"</span> event bago ka makapag-apply para sa scholarship. Bisitahin ang\n                    <a href="{{ url_for(\'student.announcements\') }}" class="underline font-medium">events page</a>\n                    para makita ang mga available orientation events.\n                </p>\n            </div>\n        </div>\n        {% endif %}\n    {% else %}\n        <div class="rounded-xl border border-slate-200 bg-white p-3 sm:p-5 flex items-start gap-2 sm:gap-3 shadow-sm">\n            <span class="w-9 h-9 sm:w-10 sm:h-10 rounded-full bg-slate-100 text-slate-500 flex items-center justify-center shrink-0">\n                <i class="fa-solid fa-lock"></i>\n            </span>\n            <div class="text-xs sm:text-sm text-slate-600">\n                <p class="font-semibold text-slate-800 text-sm sm:text-base">Scholarship registration is currently closed.</p>\n                <p>Check the\n                    <a href="{{ url_for(\'student.announcements\') }}" class="text-brand-700 underline">events</a>\n                    for the next registration window.</p>\n            </div>\n        </div>\n    {% endif %}\n\n    {# ---------- Application list ---------- #}\n    <section class="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">\n        <header class="px-3 sm:px-5 py-2 sm:py-3 border-b flex items-center justify-between">\n            <h1 class="font-semibold text-sm sm:text-base">My applications</h1>\n            <span class="text-[11px] sm:text-xs text-slate-500">{{ applications | length }} total</span>\n        </header>\n\n        {% if applications %}\n            <ul class="divide-y divide-slate-100">\n                {% for a in applications %}\n                    {% set reg = a.registration %}\n                    <li>\n                        <a href="{{ url_for(\'student.application\', app_id=a.id) }}"\n                           class="flex items-start gap-2 sm:gap-3 px-3 sm:px-5 py-3 sm:py-4 hover:bg-slate-50 transition">\n                            <span class="w-9 h-9 sm:w-10 sm:h-10 rounded-md bg-brand-50 text-brand-600 flex items-center justify-center shrink-0">\n                                <i class="fa-solid fa-file-lines"></i>\n                            </span>\n                            <div class="flex-1 min-w-0">\n                                <div class="flex items-center gap-1.5 sm:gap-2 flex-wrap">\n                                    <p class="font-semibold text-slate-800 truncate text-sm">\n                                        {{ reg.title if reg else \'Application\' }}\n                                    </p>\n                                    <span class="text-[10px] uppercase tracking-wide px-2 py-0.5 rounded {{ status_styles.get(a.status, \'bg-slate-100 text-slate-700\') }}">\n                                        {{ a.status }}\n                                    </span>\n                                </div>\n                                <p class="text-[11px] sm:text-xs text-slate-500 mt-0.5">\n                                    {{ a.level_label }} · {{ a.year_label }}\n                                    <span class="text-slate-300">·</span>\n                                    {{ a.created_at | ph_date }}\n                                </p>\n                                {% if a.notes %}\n                                    <p class="text-[11px] sm:text-xs text-slate-600 mt-1 line-clamp-2">\n                                        <i class="fa-regular fa-comment mr-1 text-slate-400"></i>\n                                        {{ a.notes }}\n                                    </p>\n                                {% endif %}\n                            </div>\n                            <i class="fa-solid fa-chevron-right text-slate-300 mt-1 text-xs"></i>\n                        </a>\n                    </li>\n                {% endfor %}\n            </ul>\n        {% else %}\n            <div class="px-4 py-8 text-center text-xs sm:text-sm text-slate-500">\n                <i class="fa-regular fa-folder-open text-2xl sm:text-3xl text-slate-300 mb-2 block"></i>\n                You don\'t have any applications yet.\n                {% if already_verified %}\n                    Verified ka na sa nakaraang registration.\n                {% elif open_registration %}\n                    Tap <span class="font-semibold">Apply now</span> above to get started.\n                {% else %}\n                    Wait for the next registration window.\n                {% endif %}\n            </div>\n        {% endif %}\n    </section>\n</div>\n{% endblock %}\n',
    'student/dashboard.html': '{% extends "student/_layout.html" %}\n{% block title %}Dashboard · Sangguniang Kabataan ng Bukal Scholarship Portal{% endblock %}\n\n{% set status_styles = {\n    \'pending\':     \'bg-amber-100 text-amber-800\',\n    \'verified\':    \'bg-green-100 text-green-800\',\n    \'rejected\':    \'bg-red-100 text-red-800\',\n    \'open\':        \'bg-green-100 text-green-800\',\n    \'upcoming\':    \'bg-amber-100 text-amber-800\',\n    \'closed\':      \'bg-slate-200 text-slate-700\',\n    \'unscheduled\': \'bg-slate-100 text-slate-600\',\n} %}\n{% set category_labels = {\n    \'registration\': \'Scholarship Registration\',\n    \'payout\':       \'Scholarship Pay Out\',\n    \'general_orientation\':  \'General Orientation\',\n    \'general\':      \'General\',\n} %}\n{% set category_styles = {\n    \'registration\': \'bg-brand-50 text-brand-700\',\n    \'payout\':       \'bg-blue-50 text-blue-700\',\n    \'general_orientation\':  \'bg-purple-50 text-purple-700\',\n    \'general\':      \'bg-slate-100 text-slate-700\',\n} %}\n\n{% macro quick_action(href, icon, title, sub) %}\n    <a href="{{ href }}"\n       class="flex items-center gap-3 p-3 sm:p-4 rounded-xl border border-slate-100 bg-white hover:border-brand-300 hover:bg-brand-50/40 transition shadow-sm">\n        <span class="w-10 h-10 rounded-md flex items-center justify-center bg-brand-50 text-brand-700">\n            <i class="fa-solid {{ icon }}"></i>\n        </span>\n        <div class="min-w-0">\n            <p class="font-semibold text-sm text-slate-800 truncate">{{ title }}</p>\n            <p class="text-[11px] text-slate-500 truncate">{{ sub }}</p>\n        </div>\n    </a>\n{% endmacro %}\n\n{% block student_content %}\n<div class="space-y-3 sm:space-y-5">\n\n    {# ---------- Greeting + open registration banner ---------- #}\n    <section class="bg-white rounded-xl shadow-sm border border-slate-100 p-4 sm:p-5">\n        <div class="flex items-start justify-between gap-3 flex-wrap">\n            <div class="min-w-0">\n                <p class="text-xs uppercase tracking-wide text-slate-500">Welcome back</p>\n                <h1 class="text-lg sm:text-2xl font-bold text-slate-800 truncate">\n                    Hi, {{ session.get(\'full_name\') or \'student\' }}\n                </h1>\n                <p class="text-xs sm:text-sm text-slate-500 mt-0.5">\n                    Here\'s a quick look at your scholarship account.\n                </p>\n            </div>\n\n            {% if already_verified %}\n                <div class="rounded-xl border border-green-200 bg-green-50 p-3 sm:p-4 flex items-center gap-3 flex-1 sm:flex-none min-w-[14rem]">\n                    <span class="w-9 h-9 rounded-full bg-green-500 text-white flex items-center justify-center shrink-0">\n                        <i class="fa-solid fa-circle-check"></i>\n                    </span>\n                    <div class="min-w-0">\n                        <p class="text-[10px] uppercase tracking-wide text-green-700 font-semibold">\n                            You\'re a verified scholar\n                        </p>\n                        <p class="text-xs text-green-800">\n                            Watch the events for the next pay-out.\n                        </p>\n                    </div>\n                </div>\n            {% elif open_registration %}\n                <div class="rounded-xl border border-brand-200 bg-brand-50 p-3 sm:p-4 flex items-center gap-3 flex-1 sm:flex-none min-w-[14rem]">\n                    <span class="w-9 h-9 rounded-full bg-brand-500 text-white flex items-center justify-center shrink-0">\n                        <i class="fa-solid fa-bullhorn"></i>\n                    </span>\n                    <div class="min-w-0">\n                        <p class="text-[10px] uppercase tracking-wide text-brand-700 font-semibold">\n                            Registration is open\n                        </p>\n                        <p class="font-semibold text-brand-800 truncate text-sm">{{ open_registration.title }}</p>\n                        {% if open_application %}\n                            <a href="{{ url_for(\'student.application\', app_id=open_application.id) }}"\n                               class="inline-flex items-center gap-1 text-xs text-brand-700 hover:underline mt-0.5">\n                                <i class="fa-solid fa-pen-to-square"></i>\n                                Continue your application\n                            </a>\n                        {% else %}\n                            <form method="post" action="{{ url_for(\'student.apply\') }}" class="mt-1">\n                                <button type="submit"\n                                        class="inline-flex items-center gap-1.5 text-xs px-3 py-1 rounded-md bg-brand-500 hover:bg-brand-600 text-white font-medium">\n                                    <i class="fa-solid fa-paper-plane"></i>\n                                    Apply now\n                                </button>\n                            </form>\n                        {% endif %}\n                    </div>\n                </div>\n            {% else %}\n                <div class="rounded-xl border border-slate-200 bg-slate-50 p-3 sm:p-4 flex items-center gap-3 flex-1 sm:flex-none min-w-[14rem]">\n                    <span class="w-9 h-9 rounded-full bg-slate-200 text-slate-600 flex items-center justify-center shrink-0">\n                        <i class="fa-solid fa-lock"></i>\n                    </span>\n                    <div class="min-w-0">\n                        <p class="text-[10px] uppercase tracking-wide text-slate-500 font-semibold">\n                            Registration closed\n                        </p>\n                        <p class="text-xs text-slate-600">\n                            Watch the events for the next window.\n                        </p>\n                    </div>\n                </div>\n            {% endif %}\n        </div>\n    </section>\n\n    {# ---------- Quick stats ---------- #}\n    <div class="grid grid-cols-2 sm:grid-cols-4 gap-3">\n        <div class="bg-white rounded-xl shadow-sm border border-slate-100 p-3 sm:p-4">\n            <p class="text-[11px] uppercase tracking-wide text-slate-500">Total</p>\n            <p class="text-2xl font-bold text-slate-800">{{ status_counts.total }}</p>\n            <p class="text-[11px] text-slate-500">Applications</p>\n        </div>\n        <div class="bg-white rounded-xl shadow-sm border border-slate-100 p-3 sm:p-4">\n            <p class="text-[11px] uppercase tracking-wide text-amber-700">Pending</p>\n            <p class="text-2xl font-bold text-amber-700">{{ status_counts.pending }}</p>\n            <p class="text-[11px] text-slate-500">Awaiting review</p>\n        </div>\n        <div class="bg-white rounded-xl shadow-sm border border-slate-100 p-3 sm:p-4">\n            <p class="text-[11px] uppercase tracking-wide text-green-700">Verified</p>\n            <p class="text-2xl font-bold text-green-700">{{ status_counts.verified }}</p>\n            <p class="text-[11px] text-slate-500">Approved</p>\n        </div>\n        <div class="bg-white rounded-xl shadow-sm border border-slate-100 p-3 sm:p-4">\n            <p class="text-[11px] uppercase tracking-wide text-red-700">Needs updates</p>\n            <p class="text-2xl font-bold text-red-700">{{ status_counts.rejected }}</p>\n            <p class="text-[11px] text-slate-500">Re-submit required</p>\n        </div>\n    </div>\n\n    {# ---------- Quick actions ---------- #}\n    <section>\n        <h2 class="text-sm font-semibold text-slate-700 mb-2">Quick actions</h2>\n        <div class="grid sm:grid-cols-2 lg:grid-cols-4 gap-3">\n            {{ quick_action(\n                url_for(\'student.applications_list\'),\n                \'fa-file-lines\',\n                \'My applications\',\n                (status_counts.total | string) ~ \' total\'\n            ) }}\n            {{ quick_action(\n                url_for(\'student.profile\'),\n                \'fa-user\',\n                \'My profile\',\n                \'Personal info & email\'\n            ) }}\n            {{ quick_action(\n                url_for(\'student.announcements\'),\n                \'fa-bullhorn\',\n                \'Events\',\n                \'See updates and events\'\n            ) }}\n            {% if active_application %}\n                {{ quick_action(\n                    url_for(\'student.application\', app_id=active_application.id),\n                    \'fa-cloud-arrow-up\',\n                    \'Upload documents\',\n                    \'Continue your active application\'\n                ) }}\n            {% else %}\n                {{ quick_action(\n                    url_for(\'student.applications_list\'),\n                    \'fa-paper-plane\',\n                    \'Start an application\',\n                    \'When registration opens\'\n                ) }}\n            {% endif %}\n        </div>\n    </section>\n\n    <div class="grid lg:grid-cols-3 gap-3 sm:gap-4">\n\n        {# ---------- Active application progress ---------- #}\n        <section class="lg:col-span-2 bg-white rounded-xl shadow-sm border border-slate-100 p-4 sm:p-5">\n            <header class="flex items-start justify-between gap-3 flex-wrap mb-3">\n                <div class="min-w-0">\n                    <h2 class="font-semibold text-base sm:text-lg">Active application</h2>\n                    {% if active_application %}\n                        <p class="text-xs text-slate-500 truncate">\n                            {{ active_application.registration.title if active_application.registration else \'Application\' }}\n                        </p>\n                    {% else %}\n                        <p class="text-xs text-slate-500">No application started yet.</p>\n                    {% endif %}\n                </div>\n                {% if active_application %}\n                    <span class="text-[10px] uppercase tracking-wide px-2 py-0.5 rounded {{ status_styles.get(active_application.status, \'bg-slate-100 text-slate-700\') }}">\n                        {{ active_application.status }}\n                    </span>\n                {% endif %}\n            </header>\n\n            {% if active_application %}\n                <div class="mb-3">\n                    <div class="flex items-center justify-between text-xs text-slate-500 mb-1">\n                        <span>Requirements progress</span>\n                        <span class="font-semibold text-slate-700">{{ active_progress }}%</span>\n                    </div>\n                    <div class="h-2 rounded bg-slate-100 overflow-hidden">\n                        <div class="h-full bg-brand-400 transition-all"\n                             style="width: {{ active_progress }}%;"></div>\n                    </div>\n                </div>\n\n                {% if active_missing %}\n                    <p class="text-xs sm:text-sm text-slate-600 mb-2 font-medium">Still needed:</p>\n                    <ul class="text-xs sm:text-sm text-slate-700 space-y-1 mb-3">\n                        {% for label in active_missing %}\n                            <li class="flex items-center gap-2">\n                                <i class="fa-regular fa-circle text-slate-300"></i>\n                                {{ label }}\n                            </li>\n                        {% endfor %}\n                    </ul>\n                {% else %}\n                    <div class="rounded-lg bg-green-50 border border-green-200 text-green-800 px-3 py-2 text-xs sm:text-sm mb-3">\n                        <i class="fa-solid fa-circle-check mr-1"></i>\n                        Kompleto na ang requirements. Pwede mo nang i-submit.\n                    </div>\n                {% endif %}\n\n                <div class="flex items-center gap-2 flex-wrap">\n                    <a href="{{ url_for(\'student.application\', app_id=active_application.id) }}"\n                       class="inline-flex items-center gap-2 px-3 sm:px-4 py-2 rounded-md bg-brand-500 hover:bg-brand-600 text-white text-sm font-semibold">\n                        <i class="fa-solid fa-arrow-right"></i>\n                        Open application\n                    </a>\n                    <a href="{{ url_for(\'student.applications_list\') }}"\n                       class="inline-flex items-center gap-2 px-3 sm:px-4 py-2 rounded-md bg-white border border-slate-200 text-slate-700 hover:bg-slate-50 text-sm">\n                        See all applications\n                    </a>\n                </div>\n            {% else %}\n                <p class="text-xs sm:text-sm text-slate-500">\n                    {% if open_registration %}\n                        Tap <span class="font-semibold">Apply now</span> sa banner sa itaas para magsimula.\n                    {% else %}\n                        Maghintay ng susunod na registration window. Lalabas dito ang\n                        progress ng requirements pagkatapos mong mag-apply.\n                    {% endif %}\n                </p>\n            {% endif %}\n        </section>\n\n        {# ---------- My events ---------- #}\n        <section class="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">\n            <header class="px-4 py-3 border-b flex items-center justify-between">\n                <h2 class="font-semibold text-sm">My events</h2>\n                <a href="{{ url_for(\'student.announcements\') }}" class="text-xs text-brand-600 hover:underline">\n                    See all &rarr;\n                </a>\n            </header>\n            {% if joined_events %}\n                <ul class="divide-y divide-slate-100">\n                    {% for e in joined_events %}\n                        <li class="px-4 py-3">\n                            <div class="flex items-center gap-2 flex-wrap mb-1">\n                                <span class="text-[10px] uppercase px-2 py-0.5 rounded {{ category_styles.get(e.category, \'bg-slate-100 text-slate-700\') }}">\n                                    {{ category_labels.get(e.category, \'Event\') }}\n                                </span>\n                                <span class="text-[10px] uppercase px-2 py-0.5 rounded {{ status_styles.get(e.status, \'bg-slate-100 text-slate-700\') }}">\n                                    {{ e.status }}\n                                </span>\n                            </div>\n                            <p class="font-medium text-sm truncate">{{ e.title }}</p>\n                            {% if e.start_at and e.end_at %}\n                                <p class="text-[11px] text-slate-500 mt-0.5">\n                                    <i class="fa-regular fa-calendar mr-1"></i>\n                                    {{ e.start_at | ph_date }} → {{ e.end_at | ph_date }}\n                                </p>\n                            {% endif %}\n                        </li>\n                    {% endfor %}\n                </ul>\n            {% else %}\n                <p class="px-4 py-6 text-xs text-slate-500 text-center">\n                    Wala ka pang sinasaling event. Tingnan mo ang\n                    <a href="{{ url_for(\'student.announcements\') }}"\n                       class="text-brand-600 hover:underline">events</a>.\n                </p>\n            {% endif %}\n        </section>\n    </div>\n\n    {# ---------- Latest events ---------- #}\n    <section class="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden">\n        <header class="px-4 py-3 border-b flex items-center justify-between">\n            <h2 class="font-semibold text-sm">Latest events</h2>\n            <a href="{{ url_for(\'student.announcements\') }}" class="text-xs text-brand-600 hover:underline">\n                See all &rarr;\n            </a>\n        </header>\n        {% if announcements %}\n            <ul class="divide-y divide-slate-100">\n                {% for a in announcements %}\n                    <li class="px-4 py-3">\n                        <div class="flex items-center gap-2 flex-wrap mb-1">\n                            <span class="text-[10px] uppercase px-2 py-0.5 rounded {{ category_styles.get(a.category, \'bg-slate-100 text-slate-700\') }}">\n                                {{ category_labels.get(a.category, \'General\') }}\n                            </span>\n                            {% if a.status != \'unscheduled\' %}\n                                <span class="text-[10px] uppercase px-2 py-0.5 rounded {{ status_styles.get(a.status, \'bg-slate-100 text-slate-700\') }}">\n                                    {{ a.status }}\n                                </span>\n                            {% endif %}\n                            {% if a.id in joined_ids %}\n                                <span class="text-[10px] uppercase px-2 py-0.5 rounded bg-green-100 text-green-800">\n                                    <i class="fa-solid fa-circle-check mr-0.5"></i> joined\n                                </span>\n                            {% endif %}\n                        </div>\n                        <p class="font-medium text-sm truncate">{{ a.title }}</p>\n                        <p class="text-[11px] sm:text-xs text-slate-500 line-clamp-2 mt-0.5">{{ a.body }}</p>\n                    </li>\n                {% endfor %}\n            </ul>\n        {% else %}\n            <p class="px-4 py-6 text-xs text-slate-500 text-center">No events yet.</p>\n        {% endif %}\n    </section>\n</div>\n{% endblock %}\n',
    'student/profile.html': '{% extends "student/_layout.html" %}\n{% block title %}My Profile · Sangguniang Kabataan ng Bukal Scholarship Portal{% endblock %}\n\n{% set status_styles = {\n    \'pending\':  \'bg-amber-100 text-amber-800\',\n    \'verified\': \'bg-green-100 text-green-800\',\n    \'rejected\': \'bg-red-100 text-red-800\',\n} %}\n\n{% block student_content %}\n<div class="space-y-3 sm:space-y-6 max-w-3xl">\n\n    {# Header card #}\n    <section class="bg-white rounded-xl shadow-sm border border-slate-100 p-4 sm:p-6 flex items-center gap-3 sm:gap-4">\n        <div class="w-12 h-12 sm:w-14 sm:h-14 rounded-full bg-brand-100 text-brand-700 flex items-center justify-center text-base sm:text-xl font-bold shrink-0">\n            {{ (profile.first_name or \'?\')[:1] | upper }}{{ (profile.last_name or \'\')[:1] | upper }}\n        </div>\n        <div class="min-w-0">\n            <h1 class="text-base sm:text-2xl font-bold truncate">{{ profile.full_name or \'My profile\' }}</h1>\n            <p class="text-xs sm:text-sm text-slate-500 capitalize">{{ profile.role or \'student\' }}</p>\n        </div>\n    </section>\n\n    {# Personal information — name fields are read-only #}\n    <section class="bg-white rounded-xl shadow-sm border border-slate-100 p-4 sm:p-6">\n        <header class="mb-3 sm:mb-4">\n            <h2 class="font-semibold text-base sm:text-lg">Personal information</h2>\n            <p class="text-[11px] sm:text-xs text-slate-500">Name fields cannot be changed after sign-up.</p>\n        </header>\n\n        <div class="grid sm:grid-cols-2 gap-3 sm:gap-4 text-xs sm:text-sm">\n            <div>\n                <label class="block text-[11px] sm:text-xs font-medium text-slate-500 mb-1">First name</label>\n                <input type="text" value="{{ profile.first_name or \'\' }}" readonly\n                       class="w-full rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-slate-700" />\n            </div>\n            <div>\n                <label class="block text-[11px] sm:text-xs font-medium text-slate-500 mb-1">Middle name</label>\n                <input type="text" value="{{ profile.middle_name or \'—\' }}" readonly\n                       class="w-full rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-slate-700" />\n            </div>\n            <div>\n                <label class="block text-[11px] sm:text-xs font-medium text-slate-500 mb-1">Last name</label>\n                <input type="text" value="{{ profile.last_name or \'\' }}" readonly\n                       class="w-full rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-slate-700" />\n            </div>\n            <div>\n                <label class="block text-[11px] sm:text-xs font-medium text-slate-500 mb-1">Suffix</label>\n                <input type="text" value="{{ profile.suffix or \'—\' }}" readonly\n                       class="w-full rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-slate-700" />\n            </div>\n        </div>\n    </section>\n\n    {# Contact #}\n    <section class="bg-white rounded-xl shadow-sm border border-slate-100 p-4 sm:p-6">\n        <header class="mb-3 sm:mb-4">\n            <h2 class="font-semibold text-base sm:text-lg">Contact</h2>\n        </header>\n        <div class="grid sm:grid-cols-2 gap-3 sm:gap-4 text-xs sm:text-sm">\n            <div>\n                <label class="block text-[11px] sm:text-xs font-medium text-slate-500 mb-1">Email</label>\n                <input type="text" value="{{ email or \'—\' }}" readonly\n                       class="w-full rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-slate-700" />\n            </div>\n            <div>\n                <label class="block text-[11px] sm:text-xs font-medium text-slate-500 mb-1">Facebook</label>\n                {% if profile.facebook_url %}\n                    <a href="{{ profile.facebook_url }}" target="_blank" rel="noopener"\n                       class="inline-flex items-center gap-2 px-3 py-2 rounded-md border border-slate-200 bg-slate-50 text-brand-700 hover:underline w-full truncate">\n                        <i class="fa-brands fa-facebook"></i>\n                        <span class="truncate">{{ profile.facebook_url }}</span>\n                    </a>\n                {% else %}\n                    <input type="text" value="—" readonly\n                           class="w-full rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-slate-700" />\n                {% endif %}\n            </div>\n        </div>\n    </section>\n\n    {# Address — read-only, captured at sign-up #}\n    <section class="bg-white rounded-xl shadow-sm border border-slate-100 p-4 sm:p-6">\n        <header class="mb-3 sm:mb-4">\n            <h2 class="font-semibold text-base sm:text-lg">Home address</h2>\n        </header>\n        <div class="grid sm:grid-cols-3 gap-3 sm:gap-4 text-xs sm:text-sm">\n            <div>\n                <label class="block text-[11px] sm:text-xs font-medium text-slate-500 mb-1">House / Lot / Block</label>\n                <input type="text" value="{{ profile.address_house_no or \'—\' }}" readonly\n                       class="w-full rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-slate-700" />\n            </div>\n            <div>\n                <label class="block text-[11px] sm:text-xs font-medium text-slate-500 mb-1">Street</label>\n                <input type="text" value="{{ profile.address_street or \'—\' }}" readonly\n                       class="w-full rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-slate-700" />\n            </div>\n            <div>\n                <label class="block text-[11px] sm:text-xs font-medium text-slate-500 mb-1">Purok / Sitio</label>\n                <input type="text" value="{{ profile.address_purok or \'—\' }}" readonly\n                       class="w-full rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-slate-700" />\n            </div>\n            <div>\n                <label class="block text-[11px] sm:text-xs font-medium text-slate-500 mb-1">Barangay</label>\n                <input type="text" value="{{ profile.address_barangay or \'—\' }}" readonly\n                       class="w-full rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-slate-700" />\n            </div>\n            <div>\n                <label class="block text-[11px] sm:text-xs font-medium text-slate-500 mb-1">City / Municipality</label>\n                <input type="text" value="{{ profile.address_city or \'—\' }}" readonly\n                       class="w-full rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-slate-700" />\n            </div>\n            <div>\n                <label class="block text-[11px] sm:text-xs font-medium text-slate-500 mb-1">Province</label>\n                <input type="text" value="{{ profile.address_province or \'—\' }}" readonly\n                       class="w-full rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-slate-700" />\n            </div>\n            <div>\n                <label class="block text-[11px] sm:text-xs font-medium text-slate-500 mb-1">ZIP code</label>\n                <input type="text" value="{{ profile.address_zip or \'—\' }}" readonly\n                       class="w-full rounded-md border border-slate-200 bg-slate-50 px-3 py-2 text-slate-700" />\n            </div>\n        </div>\n    </section>\n\n    {# Application history #}\n    <section class="bg-white rounded-xl shadow-sm border border-slate-100 p-4 sm:p-6">\n        <header class="flex items-center justify-between gap-2 sm:gap-3 mb-3 sm:mb-4 flex-wrap">\n            <h2 class="font-semibold text-base sm:text-lg">Application history</h2>\n            <a href="{{ url_for(\'student.applications_list\') }}"\n               class="text-xs sm:text-sm text-brand-600 hover:underline">Manage applications &rarr;</a>\n        </header>\n\n        {% if applications %}\n            <ul class="divide-y divide-slate-100">\n                {% for a in applications %}\n                    <li class="py-2 sm:py-3">\n                        <a href="{{ url_for(\'student.application\', app_id=a.id) }}"\n                           class="flex items-start gap-2 sm:gap-3 hover:bg-slate-50 -mx-2 px-2 py-1 rounded-md">\n                            <span class="w-8 h-8 sm:w-9 sm:h-9 rounded-md bg-brand-50 text-brand-600 flex items-center justify-center shrink-0">\n                                <i class="fa-solid fa-file-lines"></i>\n                            </span>\n                            <div class="flex-1 min-w-0">\n                                <p class="font-medium text-xs sm:text-sm truncate">\n                                    {{ a.registration.title if a.registration else \'Application\' }}\n                                </p>\n                                <p class="text-[11px] sm:text-xs text-slate-500">\n                                    {{ a.level_label }} · {{ a.year_label }}\n                                    <span class="text-slate-300">·</span>\n                                    {{ a.created_at | ph_date }}\n                                </p>\n                            </div>\n                            <span class="text-[10px] sm:text-xs uppercase tracking-wide px-2 py-1 rounded shrink-0 {{ status_styles.get(a.status, \'bg-slate-100 text-slate-700\') }}">\n                                {{ a.status }}\n                            </span>\n                        </a>\n                    </li>\n                {% endfor %}\n            </ul>\n        {% else %}\n            <p class="text-xs sm:text-sm text-slate-500">No applications yet.</p>\n        {% endif %}\n    </section>\n</div>\n{% endblock %}\n',
    'student/select_level.html': '{% extends "student/_layout.html" %}\n{% block title %}Choose your level · Sangguniang Kabataan ng Bukal Scholarship Portal{% endblock %}\n\n{% block student_content %}\n<div class="mb-4">\n    <a href="{{ url_for(\'student.applications_list\') }}"\n       class="inline-flex items-center gap-2 text-sm text-slate-600 hover:text-brand-700">\n        <i class="fa-solid fa-arrow-left"></i>\n        Back to my applications\n    </a>\n</div>\n\n{% if not window_open %}\n    <div class="mb-4 p-4 rounded-xl border border-amber-200 bg-amber-50 text-amber-800 text-sm flex items-start gap-3">\n        <i class="fa-solid fa-lock mt-0.5"></i>\n        <div>\n            <p class="font-semibold">The registration window for this application is closed.</p>\n            <p>You can no longer change this application.</p>\n        </div>\n    </div>\n{% endif %}\n<section class="bg-white rounded-xl shadow-sm p-4 sm:p-6 border border-slate-100 max-w-2xl">\n    <h1 class="text-lg sm:text-2xl font-bold mb-1">Tell us about your studies</h1>\n    <p class="text-xs sm:text-sm text-slate-500 mb-4 sm:mb-5">\n        Pick your education level and current year. The required documents\n        change depending on what you choose.\n    </p>\n\n    <form method="post" action="{{ url_for(\'student.set_level\', app_id=application.id) }}"\n          class="space-y-4 sm:space-y-5" id="level-form">\n        <div>\n            <p class="text-sm font-medium mb-2">Education level</p>\n            <div class="grid sm:grid-cols-2 gap-2 sm:gap-3">\n                {% for key, label in [(\'senior_high\', \'Senior High School\'), (\'college\', \'College\')] %}\n                    <label class="flex items-start gap-2 sm:gap-3 border border-slate-200 rounded-lg p-2.5 sm:p-3 cursor-pointer hover:border-brand-400 has-[:checked]:border-brand-500 has-[:checked]:bg-brand-50">\n                        <input type="radio" name="education_level" value="{{ key }}"\n                               class="mt-1" required\n                               data-level-radio\n                               {% if application.education_level == key %}checked{% endif %}\n                               {% if not window_open %}disabled{% endif %} />\n                        <span>\n                            <span class="font-medium block text-sm">{{ label }}</span>\n                            <span class="text-[11px] sm:text-xs text-slate-500">\n                                {% if key == \'senior_high\' %}Grade 11 or Grade 12{% else %}1st to 5th year{% endif %}\n                            </span>\n                        </span>\n                    </label>\n                {% endfor %}\n            </div>\n        </div>\n\n        <div>\n            <label class="block text-sm font-medium mb-1">Year level</label>\n            <select name="year_level" id="year-select" required\n                    {% if not window_open %}disabled{% endif %}\n                    class="w-full sm:w-64 rounded-md border border-slate-300 px-3 py-2 bg-white text-sm focus:outline-none focus:ring-2 focus:ring-brand-400 disabled:bg-slate-100 disabled:text-slate-400">\n                <option value="">— Pick your level first —</option>\n                {% for level_key, opts in year_options.items() %}\n                    {% for value, label in opts %}\n                        <option value="{{ value }}" data-level="{{ level_key }}"\n                                {% if application.year_level == value %}selected{% endif %}>\n                            {{ label }}\n                        </option>\n                    {% endfor %}\n                {% endfor %}\n            </select>\n        </div>\n\n        <button type="submit"\n                {% if not window_open %}disabled{% endif %}\n                class="px-4 py-2 rounded-md bg-brand-500 hover:bg-brand-600 text-white text-sm font-medium\n                       disabled:bg-slate-300 disabled:cursor-not-allowed">\n            Save and continue\n        </button>\n    </form>\n</section>\n\n<script>\n(function () {\n    const form    = document.getElementById(\'level-form\');\n    const select  = document.getElementById(\'year-select\');\n    if (!form || !select) return;\n\n    function refresh() {\n        const checked = form.querySelector(\'[data-level-radio]:checked\');\n        const level   = checked ? checked.value : \'\';\n        let firstMatch = null;\n        Array.from(select.options).forEach(opt => {\n            const lvl = opt.dataset.level;\n            if (!lvl) { opt.hidden = !!level; return; }   // placeholder\n            const match = lvl === level;\n            opt.hidden = !match;\n            if (match && !firstMatch) firstMatch = opt;\n        });\n        // If the current selection is hidden, reset to first matching.\n        const cur = select.options[select.selectedIndex];\n        if (!cur || cur.hidden) {\n            select.value = firstMatch ? firstMatch.value : \'\';\n        }\n    }\n\n    form.querySelectorAll(\'[data-level-radio]\').forEach(r =>\n        r.addEventListener(\'change\', refresh));\n    refresh();\n})();\n</script>\n{% endblock %}\n',
    'student/_layout.html': '{% extends "base.html" %}\n\n{# Layout for student pages.\n   Pages should override `student_content` instead of `content`.\n   Desktop: persistent left sidebar.\n   Mobile : a hamburger button that opens a centered modal menu —\n            no off-canvas drawer wasting horizontal space. #}\n\n{% block content %}\n<div class="md:grid md:grid-cols-[15rem_1fr] md:gap-6">\n\n    {# ----- Mobile top bar (visible below md) ----- #}\n    <div class="md:hidden flex items-center justify-between mb-3">\n        <button type="button" data-student-menu-open\n                class="inline-flex items-center gap-2 px-3 py-1.5 rounded-md bg-white border border-slate-200 text-slate-700 text-sm">\n            <i class="fa-solid fa-bars"></i>\n            <span class="font-medium">Menu</span>\n        </button>\n        <span class="text-xs text-slate-500 truncate max-w-[55%]">{{ session.get(\'full_name\') }}</span>\n    </div>\n\n    {# ----- Desktop sidebar (md+) ----- #}\n    <aside class="hidden md:block">\n        <div class="bg-white rounded-xl shadow-sm border border-slate-100 p-3 sticky top-24 max-h-[calc(100vh-7rem)] overflow-y-auto">\n            <span class="block text-xs uppercase tracking-wide text-slate-500 mb-2 px-1">Student menu</span>\n\n            {% set nav_base = "flex items-center gap-3 px-3 py-2 rounded-md text-sm font-medium" %}\n            {% set nav_active = "bg-brand-50 text-brand-700" %}\n            {% set nav_idle = "text-slate-700 hover:bg-slate-100" %}\n\n            <nav class="space-y-1">\n                <a href="{{ url_for(\'student.dashboard\') }}"\n                   class="{{ nav_base }} {% if request.endpoint == \'student.dashboard\' %}{{ nav_active }}{% else %}{{ nav_idle }}{% endif %}">\n                    <i class="fa-solid fa-gauge-high w-5 text-center"></i>\n                    <span>Dashboard</span>\n                </a>\n                <a href="{{ url_for(\'student.applications_list\') }}"\n                   class="{{ nav_base }} {% if request.endpoint in [\'student.applications_list\', \'student.application\'] %}{{ nav_active }}{% else %}{{ nav_idle }}{% endif %}">\n                    <i class="fa-solid fa-file-lines w-5 text-center"></i>\n                    <span>My applications</span>\n                </a>\n                <a href="{{ url_for(\'student.profile\') }}"\n                   class="{{ nav_base }} {% if request.endpoint == \'student.profile\' %}{{ nav_active }}{% else %}{{ nav_idle }}{% endif %}">\n                    <i class="fa-solid fa-user w-5 text-center"></i>\n                    <span>My profile</span>\n                </a>\n                <a href="{{ url_for(\'student.announcements\') }}"\n                   class="{{ nav_base }} {% if request.endpoint == \'student.announcements\' %}{{ nav_active }}{% else %}{{ nav_idle }}{% endif %}">\n                    <i class="fa-solid fa-bullhorn w-5 text-center"></i>\n                    <span>Events</span>\n                </a>\n                <a href="{{ url_for(\'public.logout\') }}"\n                   class="{{ nav_base }} text-red-600 hover:bg-red-50">\n                    <i class="fa-solid fa-right-from-bracket w-5 text-center"></i>\n                    <span>Log out</span>\n                </a>\n            </nav>\n        </div>\n    </aside>\n\n    {# ----- Main content ----- #}\n    <div class="min-w-0">\n        {% block student_content %}{% endblock %}\n    </div>\n</div>\n\n{# ----- Mobile menu modal (centered) ----- #}\n<div id="student-menu-modal"\n     class="hidden fixed inset-0 z-[60] flex items-end sm:items-center justify-center md:hidden"\n     role="dialog" aria-modal="true" aria-labelledby="student-menu-title">\n    <div class="absolute inset-0 bg-slate-900/50" data-student-menu-close></div>\n    <div class="relative bg-white w-full sm:max-w-sm sm:mx-4 rounded-t-2xl sm:rounded-2xl shadow-2xl overflow-hidden">\n        <div class="flex items-center justify-between px-4 py-3 border-b">\n            <span id="student-menu-title" class="text-xs uppercase tracking-wide text-slate-500">Student menu</span>\n            <button type="button" data-student-menu-close\n                    class="text-slate-400 hover:text-slate-600 p-1" aria-label="Close menu">\n                <i class="fa-solid fa-xmark"></i>\n            </button>\n        </div>\n\n        {% set m_base = "flex items-center gap-3 px-4 py-3 text-sm" %}\n        {% set m_active = "bg-brand-50 text-brand-700 font-semibold" %}\n        {% set m_idle = "text-slate-700 hover:bg-slate-50" %}\n\n        <nav class="divide-y divide-slate-100">\n            <a href="{{ url_for(\'student.dashboard\') }}"\n               class="{{ m_base }} {% if request.endpoint == \'student.dashboard\' %}{{ m_active }}{% else %}{{ m_idle }}{% endif %}">\n                <i class="fa-solid fa-gauge-high w-5 text-center"></i>\n                <span>Dashboard</span>\n            </a>\n            <a href="{{ url_for(\'student.applications_list\') }}"\n               class="{{ m_base }} {% if request.endpoint in [\'student.applications_list\', \'student.application\'] %}{{ m_active }}{% else %}{{ m_idle }}{% endif %}">\n                <i class="fa-solid fa-file-lines w-5 text-center"></i>\n                <span>My applications</span>\n            </a>\n            <a href="{{ url_for(\'student.profile\') }}"\n               class="{{ m_base }} {% if request.endpoint == \'student.profile\' %}{{ m_active }}{% else %}{{ m_idle }}{% endif %}">\n                <i class="fa-solid fa-user w-5 text-center"></i>\n                <span>My profile</span>\n            </a>\n            <a href="{{ url_for(\'student.announcements\') }}"\n               class="{{ m_base }} {% if request.endpoint == \'student.announcements\' %}{{ m_active }}{% else %}{{ m_idle }}{% endif %}">\n                <i class="fa-solid fa-bullhorn w-5 text-center"></i>\n                <span>Events</span>\n            </a>\n            <a href="{{ url_for(\'public.logout\') }}"\n               class="{{ m_base }} text-red-600 hover:bg-red-50">\n                <i class="fa-solid fa-right-from-bracket w-5 text-center"></i>\n                <span>Log out</span>\n            </a>\n        </nav>\n    </div>\n</div>\n\n{# ----- Fixed notification button ----- #}\n{% include "_notification_button.html" %}\n\n<script>\n(function () {\n    const modal = document.getElementById(\'student-menu-modal\');\n    if (!modal) return;\n    function open()  { modal.classList.remove(\'hidden\'); document.body.classList.add(\'overflow-hidden\'); }\n    function close() { modal.classList.add(\'hidden\');    document.body.classList.remove(\'overflow-hidden\'); }\n    document.addEventListener(\'click\', function (e) {\n        if (e.target.closest(\'[data-student-menu-open]\'))  { e.preventDefault(); open();  return; }\n        if (e.target.closest(\'[data-student-menu-close]\')) { close(); return; }\n    });\n    document.addEventListener(\'keydown\', function (e) {\n        if (e.key === \'Escape\' && !modal.classList.contains(\'hidden\')) close();\n    });\n})();\n</script>\n{% endblock %}\n',
}
